window.HB_TR["exodus"]["ur"]=["1۔ اب یہ بنی اسرائیل کے نام ہیں، جو مصر میں آئے؛ ہر آدمی اور اس کا گھرانہ یعقوب کے ساتھ آتا تھا۔\n2۔ روبن، شمعون، لیوی اور یہوداہ،\n3۔ اساکر، زبولون، اور بنیمن،\n4۔ ڈین، اور نفتالی، گاد، اور آشر۔\n5۔ اور یعقوب کی کمر سے نکلنے والی تمام روحیں ستر روحیں تھیں: کیونکہ یوسف پہلے ہی مصر میں تھا۔ {لوئنز: عبرانی۔ ران}\n6۔ اور یوسف مر گیا، اس کے تمام بھائیوں کو، اور وہ تمام نسل۔\n7۔ اور بنی اسرائیل نے پھلدار کیا، کثرت سے بڑھے، کثرت سے بڑھے، اور بے حد طاقتور ہوئے؛ اور زمین ان سے بھر گئی۔\n8۔ اب مصر پر ایک نیا بادشاہ ابھرا، جو یوسف کو نہیں جانتا تھا۔\n9۔ اور اس نے اپنی قوم سے کہا، دیکھو، بنی اسرائیل کی قوم ہم سے زیادہ اور طاقتور ہے:\n10۔ آؤ، آئیے ان کے ساتھ دانشمندی سے نمٹیں؛ کہیں وہ بڑھ نہ جائیں، اور ایسا ہو جائے کہ جب کوئی جنگ چھڑ جائے تو وہ بھی ہمارے دشمنوں کے ساتھ مل جائیں، اور ہمارے خلاف لڑیں، اور {یوں} انہیں زمین سے نکال دیں۔\n11۔ اسی لیے انہوں نے اپنے اوپر ذمہ داروں کو مقرر کیا تاکہ ان پر بوجھ ڈالیں۔ اور انہوں نے فرعون کے لیے خزانے کے شہر بنائے، پیتھوم اور رامسس۔\n12. لیکن جتنا زیادہ وہ انہیں تکلیف دیتے، اتنے ہی زیادہ بڑھتے اور بڑھتے گئے۔ اور وہ اسرائیل کے بچوں کی وجہ سے غمگین ہوئے۔ {لیکن...: عبرانی۔ اور جیسے وہ ان پر ظلم کرتے تھے، ویسے ہی وہ بڑھتے گئے، وغیرہ۔\n13۔ اور مصریوں نے بنی اسرائیل کو سختی سے خدمت کرنے پر مجبور کیا:\n14۔ اور انہوں نے اپنی زندگیوں کو سخت غلامی، گتل، اینٹوں اور میدان میں ہر قسم کی خدمت سے تلخ بنا دیا: ان کی تمام خدمت، جس میں انہوں نے انہیں خدمت دی، {سختی} کے ساتھ کی گئی۔\n15۔ اور مصر کے بادشاہ نے عبرانی دائیوں سے کہا، جن میں سے ایک کا نام شفرا اور دوسری پوآہ کا نام تھا:\n16۔ اور اس نے کہا، جب تم عبرانی عورتوں کے لیے دائی کا کام کرو، اور انہیں اسٹول پر دیکھو؛ اگر وہ بیٹا ہو تو تم اسے مار دو گے؛ لیکن اگر وہ بیٹی ہو تو وہ زندہ رہے گی۔\n17۔ لیکن دائیوں نے خدا سے ڈرنا شروع کیا، اور جیسا کہ مصر کے بادشاہ نے حکم دیا ویسا نہیں کیا، بلکہ مردوں کے بچوں کو زندہ بچایا۔\n18۔ اور مصر کے بادشاہ نے دائیوں کو بلایا اور ان سے کہا، تم نے یہ سب کیوں کیا اور مردوں کے بچوں کو زندہ کیوں بچایا؟\n19۔ اور دائیوں نے فرعون سے کہا، کیونکہ عبرانی عورتیں مصری عورتوں جیسی نہیں ہیں؛ کیونکہ وہ زندہ دل ہیں، اور دائیوں کے آنے سے پہلے ہی پیدا کر دی جاتی ہیں۔\n20۔ اسی لیے خدا نے دائیوں کے ساتھ اچھا سلوک کیا: اور لوگ بڑھے اور بہت طاقتور ہو گئے۔\n21۔ اور ایسا ہوا کہ دائیوں نے خدا سے ڈرتے ہوئے انہیں گھر بنایا۔\n22۔ اور فرعون نے اپنے تمام لوگوں کو حکم دیا، کہا کہ جو بھی بیٹا پیدا ہوگا اسے دریا میں پھینک دو، اور ہر بیٹی کو زندہ بچاؤ۔","1۔ اور وہاں لاوی خاندان کا ایک آدمی گیا، اور اس نے لاوی کی بیٹی سے شادی کر لی۔\n2۔ اور عورت حاملہ ہوئی اور ایک بیٹا پیدا ہوا: اور جب اس نے اسے دیکھا کہ وہ ایک اچھا {بچہ} ہے، تو اس نے اسے تین ماہ چھپا لیا۔\n3۔ اور جب وہ اسے چھپا نہ سکی، تو اس نے اس کے لیے بلرش کا ایک صندوق لیا، اس پر کیچڑ اور گلے سے لگا دیا، اور بچے کو اس میں ڈال دیا؛ اور اس نے دریا کے کنارے جھنڈوں میں رکھا۔\n4۔ اور اس کی بہن دور کھڑی تھی، یعنی اس کے ساتھ کیا ہوگا۔\n5۔ اور فرعون کی بیٹی دریا کے کنارے خود کو دھونے کے لیے نیچے آئی؛ اور اس کی لڑکیاں دریا کے کنارے چلتی رہیں؛ اور جب اس نے جھنڈوں کے درمیان صندوق دیکھا، تو اس نے اپنی خادمہ کو اسے لانے بھیجا۔\n6۔ اور جب اس نے اسے کھولا، تو اس نے بچے کو دیکھا: اور دیکھو، بچہ رو پڑا۔ اور اس نے اس پر رحم کیا، اور کہا، یہ عبرانیوں کے بچوں میں سے ایک ہے۔\n7۔ پھر اس کی بہن نے فرعون کی بیٹی سے کہا، کیا میں تمہارے پاس جا کر عبرانی عورتوں کی ایک آیا کو بلاؤں تاکہ وہ تمہارے لیے بچے کی دیکھ بھال کرے؟\n8۔ اور فرعون کی بیٹی نے اس سے کہا، جاؤ۔ اور نوکرانی نے جا کر بچے کی ماں کو بلایا۔\n9۔ اور فرعون کی بیٹی نے اس سے کہا، اس بچے کو لے جاؤ، اور میرے لیے دودھ پلا لو، اور میں تمہیں تمہاری اجرت دوں گا۔ اور عورت نے بچے کو لیا اور دودھ پلایا۔\n10۔ اور بچہ بڑا ہوا، اور وہ اسے فرعون کی بیٹی کے پاس لے آئی، اور وہ اس کا بیٹا بن گیا۔ اور اس نے اس کا نام موسیٰ کہا: اور کہا، کیونکہ میں نے اسے پانی سے نکالا۔ {موسیٰ: یعنی، ڈرا آؤٹ}\n11۔ اور ان دنوں جب موسیٰ بڑا ہوا، وہ اپنے بھائیوں کے پاس گیا اور ان کے بوجھ کو دیکھا: اور اس نے ایک مصری کو ایک عبرانی کو مارتے ہوئے دیکھا، جو اس کے بھائی میں سے ایک تھا۔\n12۔ اور اس نے ادھر ادھر دیکھا، اور جب اس نے دیکھا کہ وہاں کوئی آدمی نہیں ہے، تو اس نے مصری کو مار ڈالا اور ریت میں چھپا دیا۔\n13۔ اور جب وہ دوسرے دن باہر نکلا، دیکھو، عبرانیوں کے دو آدمی اکٹھے لڑ رہے تھے: اور اس نے اس سے کہا جس نے ظلم کیا، تو اپنے ساتھی کو کیوں مسکرا رہے ہو؟\n14۔ اور اس نے کہا، کس نے تمہیں ہم پر شہزادہ اور قاضی بنایا؟ کیا تم مجھے مارنے کا ارادہ رکھتے ہو، جیسے تم نے مصری کو مارا؟ اور موسیٰ ڈر گیا، اور کہا، یقینا یہ چیز معلوم ہے۔ {ایک شہزادہ: عبرانی۔ ایک آدمی، ایک شہزادہ}\n15۔ جب فرعون نے یہ بات سنی، تو اس نے موسیٰ کو قتل کرنے کی کوشش کی۔ لیکن موسیٰ فرعون کے سامنے سے بھاگ گیا، اور مدین کی سرزمین میں بسنے لگا، اور وہ ایک کنویں کے پاس بیٹھ گیا۔\n16۔ اب مدیان کے پادری کی سات بیٹیاں تھیں: اور وہ آئیں اور پانی نکالا، اور اپنے والد کے ریوڑ کو پانی دینے کے لیے نالی بھر دی۔ {پادری: یا، شہزادہ}\n17۔ اور چرواہے آئے اور انہیں بھگا دیا، لیکن موسیٰ کھڑے ہو کر ان کی مدد کی، اور ان کے ریوڑ کو پانی دیا۔\n18۔ اور جب وہ اپنے والد رئیول کے پاس آئے، تو اس نے کہا، تم اتنی جلدی کیسے آ گئے؟ {رئوئل: جسے یتھرو یا یتھر بھی کہا جاتا ہے}\n19۔ اور انہوں نے کہا، ایک مصری نے ہمیں چرواہوں کے ہاتھوں سے آزاد کرایا، اور ہمارے لیے کافی پانی بھی نکالا، اور ریوڑ کو پانی دیا۔\n20۔ اور اس نے اپنی بیٹیوں سے کہا، اور وہ کہاں ہے؟ یہ کیوں ہے کہ تم نے اس آدمی کو چھوڑ دیا؟ اسے بلاؤ، تاکہ وہ روٹی کھا سکے۔\n21۔ اور موسیٰ اس آدمی کے ساتھ رہنے پر راضی تھا: اور اس نے موسیٰ زپورہ کو اپنی بیٹی دی۔\n22۔ اور اس نے ایک بیٹا پیدا کیا، اور اس نے اپنا نام گرشوم رکھا: کیونکہ اس نے کہا، میں اجنبی زمین میں اجنبی رہا ہوں۔ {گرشوم: یعنی، یہاں ایک اجنبی}\n23۔ اور وقت کے ساتھ ایسا ہوا کہ مصر کا بادشاہ مر گیا: اور بنی اسرائیل نے غلامی کی وجہ سے آہ بھری، رونے لگے، اور ان کی پکار بندھن کی وجہ سے خدا تک پہنچی۔\n24۔ اور خدا نے ان کی کراہیں سنی، اور خدا نے ابراہیم، اسحاق اور یعقوب کے ساتھ اپنا عہد یاد کیا۔\n25۔ اور خدا نے بنی اسرائیل کو دیکھا، اور خدا نے ان کا احترام کیا۔ {تھا...: عبرانی جانتا تھا}","1۔ اب موسیٰ نے اپنے سسر، مدیان کے کاہن، یتھرو کے ریوڑ کو سنبھالا، اور اس نے ریوڑ کو صحرا کے پچھلے حصے تک لے جایا، اور خدا کے پہاڑ تک پہنچا، حتیٰ کہ حوریب بھی۔\n2۔ اور خداوند کا فرشتہ اس کے سامنے جھاڑی کے بیچ سے آگ کی آگ میں نمودار ہوا، اور اس نے دیکھا، اور دیکھو، جھاڑی آگ سے جل گئی، اور جھاڑی جل نہیں گئی۔\n3۔ اور موسیٰ نے کہا، اب میں مڑ کر یہ عظیم منظر دیکھوں گا کہ جھاڑی کیوں نہیں جلی۔\n4۔ اور جب خداوند نے دیکھا کہ وہ دیکھنے کے لیے مڑ گیا، تو خدا نے جھاڑیوں کے بیچ سے اسے بلایا اور کہا، موسیٰ، موسیٰ۔ اور اس نے کہا، یہاں {میں} ہوں۔\n5۔ اور اس نے کہا، یہاں مت آؤ، اپنے جوتے اپنے پیروں سے اتارو، کیونکہ جس جگہ پر تم کھڑے ہو وہ مقدس زمین ہے۔\n6۔ مزید اس نے کہا، میں تمہارے باپ کا خدا ہوں، ابراہیم کا خدا، اسحاق کا خدا، اور یعقوب کا خدا ہوں۔ اور موسیٰ نے اپنا چہرہ چھپا لیا؛ کیونکہ وہ خدا کو دیکھنے سے ڈرتا تھا۔\n7۔ اور خداوند نے فرمایا، میں نے یقینا اپنے لوگوں کی مصیبت دیکھی ہے جو مصر میں ہیں، اور ان کی پکار ان کے ذمہ داروں کی وجہ سے سنی ہے؛ کیونکہ میں ان کے غم جانتا ہوں؛\n8۔ اور میں نیچے آیا ہوں تاکہ انہیں مصریوں کے ہاتھوں سے آزاد کروں، اور انہیں اس زمین سے ایک اچھی اور بڑی زمین پر لے جاؤں جو دودھ اور شہد سے بہتی ہے؛ کنعانیوں کی جگہ، حتیوں، اموریوں، پریزیوں، حویوں، اور جبوسیوں کی جگہ۔\n9۔ اب دیکھو، بنی اسرائیل کی پکار میرے پاس آئی ہے: اور میں نے یہ بھی دیکھا ہے کہ مصریوں نے ان پر ظلم کیا ہے۔\n10۔ اب آؤ، اور میں تمہیں فرعون کے پاس بھیجوں گا، تاکہ تم میرے لوگوں کو مصر سے بنی اسرائیل کو باہر نکالو۔\n11۔ اور موسیٰ نے خدا سے کہا، میں کون ہوں، کہ میں فرعون کے پاس جاؤں، اور بنی اسرائیل کو مصر سے نکالوں؟\n12۔ اور اس نے کہا، یقینا میں تمہارے ساتھ ہوں گا؛ اور یہ تمہارے لیے ایک نشانی ہوگی، جو میں نے تمہیں بھیجا ہے: جب تم لوگوں کو مصر سے نکالو گے، تو تم اس پہاڑ پر خدا کی عبادت کرو گے۔\n13۔ اور موسیٰ نے خدا سے کہا، دیکھو، {جب} میں بنی اسرائیل کے پاس آؤں گا، اور انہیں کہوں گا، تمہارے باپ اجداد کے خدا نے مجھے تمہارے پاس بھیجا ہے؛ اور وہ مجھ سے کہیں گے، اس کا نام کیا ہے؟ میں ان سے کیا کہوں؟\n14۔ اور خدا نے موسیٰ سے کہا، میں وہی ہوں جو میں ہوں، اور اس نے کہا، تو یوں بنی اسرائیل سے کہو گے، میں نے خود کو تمہارے پاس بھیجا ہے۔\n15۔ اور خدا نے موسیٰ سے مزید کہا، یوں تو بنی اسرائیل سے کہے گا، خداوند خدا، ابراہیم کا خدا، اسحاق کا خدا، اور یعقوب کا خدا، مجھے تمہارے پاس بھیجا ہے: یہ میرا نام ہمیشہ کے لیے ہے، اور یہ میری یادگار ہے تمام نسلوں کے لیے۔\n16۔ جاؤ، اور اسرائیل کے بزرگوں کو اکٹھا کرو، اور ان سے کہو، تمہارے آباؤ اجداد کا خداوند خدا، ابراہیم، اسحاق اور یعقوب کا خدا، میرے سامنے ظاہر ہوا اور کہا، میں نے یقینا تم سے ملاقات کی ہے، اور مصر میں تمہارے ساتھ جو کچھ ہوا ہے اسے دیکھا ہے:\n17۔ اور میں نے کہا ہے، میں تمہیں مصر کی مصیبت سے نکال کر کنعانیوں اور حتیوں، اموریوں، پریزیوں، حویوں، اور یبوسیوں کی سرزمین پر لے جاؤں گا، جہاں دودھ اور شہد بہتا ہے۔\n18۔ اور وہ تمہاری آواز سنیں گے: اور تم اور اسرائیل کے بزرگوں کو مصر کے بادشاہ کے پاس آؤ گے، اور تم اسے کہو گے، عبرانیوں کے خداوند خدا نے ہم سے ملاقات کی ہے: اور اب ہم تین دن کے سفر پر جنگل میں چلیں تاکہ ہم اپنے خداوند خدا کے لیے قربانی دیں۔\n19۔ اور مجھے یقین ہے کہ مصر کا بادشاہ تمہیں جانے نہیں دے گا، نہیں، کسی طاقتور ہاتھ سے نہیں۔ {نہیں...: یا، لیکن مضبوط ہاتھ سے}\n20۔ اور میں اپنا ہاتھ بڑھاؤں گا، اور مصر کو اپنی تمام عجائبات سے ماروں گا جو میں ان کے درمیان کروں گا: اور اس کے بعد وہ تمہیں جانے دے گا۔\n21۔ اور میں اس قوم کو مصریوں کی نظر میں عنایت دوں گا: اور ایسا ہوگا کہ جب تم جاؤ گے تو خالی نہیں جاؤ گے:\n22۔ لیکن ہر عورت اپنے پڑوسی اور اپنے گھر میں رہنے والی عورت سے چاندی کے زیورات، سونے کے زیورات اور کپڑے ادھار لے گی، اور تم انہیں اپنے بیٹوں اور اپنی بیٹیوں پر پہناؤ گے؛ اور تم مصریوں کو بگاڑ دو گے۔ {مصری: یا، مصر}","1۔ اور موسیٰ نے جواب دیا اور کہا، لیکن دیکھو، وہ مجھ پر یقین نہیں کریں گے، نہ میری آواز سنیں گے، کیونکہ وہ کہیں گے، خداوند نے تمہیں ظاہر نہیں کیا۔\n2۔ اور خداوند نے اس سے کہا، یہ تمہارے ہاتھ میں کیا ہے؟ اور اس نے کہا، ایک راڈ۔\n3۔ اور اس نے کہا، اسے زمین پر پھینکو۔ اور اس نے اسے زمین پر پھینکا، اور وہ سانپ بن گیا؛ اور موسیٰ اس کے سامنے سے بھاگ گیا۔\n4۔ اور خداوند نے موسیٰ سے کہا، اپنا ہاتھ آگے بڑھاؤ اور دم سے پکڑو۔ اور اس نے اپنا ہاتھ آگے بڑھایا، اسے پکڑ لیا، اور وہ اس کے ہاتھ میں ایک چھڑی بن گیا:\n5۔ تاکہ وہ یقین کریں کہ ان کے باپ اجداد کا خداوند خدا، ابراہیم کا خدا، اسحاق کا خدا، اور یعقوب کا خدا آپ پر ظاہر ہوا ہے۔\n6۔ اور خداوند نے اس سے مزید کہا، اب اپنا ہاتھ اپنے سینے میں رکھو۔ اور اس نے اپنا ہاتھ اپنے سینے میں رکھا: اور جب اس نے اسے نکالا، تو دیکھو، اس کا ہاتھ برف کی طرح کوڑھ تھا۔\n7۔ اور اس نے کہا، اپنا ہاتھ دوبارہ اپنے سینے میں رکھو۔ اور اس نے دوبارہ اپنا ہاتھ سینے میں ڈال دیا؛ اور اسے اپنے سینے سے نکالا، اور دیکھو، وہ دوبارہ اس کے {دوسرے} گوشت کی طرح پلٹ گیا۔\n8۔ اور اگر وہ تم پر یقین نہ کریں، یا پہلی نشانی کی آواز نہ سنیں، تو وہ دوسرے نشان کی آواز پر یقین کریں گے۔\n9۔ اور اگر وہ بھی ان دونوں نشانیوں پر یقین نہ کریں اور نہ ہی آپ کی آواز سنیں، تو یہ ہو جائے گا کہ تم دریا کے پانی سے لے کر خشک زمین پر بہا دو، اور جو پانی تم دریا سے نکالو گے وہ خشک زمین پر خون بن جائے گا۔ {بن جائے گا: عبرانی۔ ہو جائے گا اور ہوگا}\n10۔ اور موسیٰ نے خداوند سے کہا، اے میرے رب، میں فصیح نہیں ہوں، نہ اب تک، نہ اس سے پہلے اور نہ ہی جب سے تو نے اپنے بندے سے بات کی ہے، بلکہ میں آہستہ بولنے والا اور آہستہ زبان والا ہوں۔ {فصاحت: عبوری۔ الفاظ کا آدمی} {اب تک: عبرانی۔ کل سے، نہ ہی تیسرے دن سے}\n11۔ اور خداوند نے اس سے کہا، انسان کا منہ کس نے بنایا؟ یا کون گونگے، بہرا، دیکھنے والے کو، یا اندھے کو بناتا ہے؟ کیا میں خداوند نہیں ہوں؟\n12۔ اب جاؤ، اور میں تمہارے منہ کے ساتھ ہوں گا، اور تمہیں سکھاؤں گا کہ تم کیا کہو گے۔\n13۔ اور اس نے کہا، اے میرے رب، میں دعا کرتا ہوں کہ بھیج دے، اس کے ہاتھ سے {جسے تم بھیجنا چاہو}۔ {ولٹ: یا، ہونا چاہیے}\n14۔ اور خداوند کا غصہ موسیٰ کے خلاف بھڑک اٹھا، اور اس نے کہا، {کیا} ہارون لاوی تمہارا بھائی نہیں ہے؟ مجھے معلوم ہے کہ وہ اچھی بات کر سکتا ہے۔ اور دیکھو، وہ تم سے ملنے آتا ہے: اور جب وہ تمہیں دیکھے گا تو دل سے خوش ہوگا۔\n15۔ اور تم اس سے بات کرو گے، اور اس کے منہ میں الفاظ ڈالو گے، اور میں تمہارے منہ کے ساتھ رہوں گا، اور اس کے منہ کے ساتھ ہوں گا، اور تمہیں سکھاؤں گا کہ تم کیا کرو گے۔\n16۔ اور وہ لوگوں کے لیے تمہارا ترجمان ہوگا: اور وہ تمہارے لیے ہوگا، منہ کی بجائے تمہارے لیے ہوگا، اور تم خدا کی جگہ اس کے لیے ہو گے۔\n17۔ اور تم یہ چھڑی اپنے ہاتھ میں پکڑو گے، جس سے تم اشارے کرو گے۔\n18۔ اور موسیٰ گیا اور اپنے سسر یثرو کے پاس واپس آیا، اور اس سے کہا، میں دعا کرتا ہوں کہ مجھے جانے دو، اور میرے ان بھائیوں کے پاس واپس جاؤ جو مصر میں ہیں، اور دیکھو کہ کیا وہ زندہ ہیں۔ اور یثرو نے موسیٰ سے کہا، امن سے جاؤ۔ {جیتھرو: عبرانی۔ جیتھر}\n19۔ اور خداوند نے مدین میں موسیٰ سے کہا، جاؤ، مصر میں واپس آؤ، کیونکہ وہ سب لوگ مر چکے ہیں جنہوں نے تیری زندگی کی تلاش کی۔\n20۔ اور موسیٰ نے اپنی بیوی اور بیٹوں کو لے کر گدھے پر بٹھایا، اور وہ مصر کی سرزمین واپس آیا: اور موسیٰ نے خدا کی چھڑی اپنے ہاتھ میں لے لی۔\n21۔ اور خداوند نے موسیٰ سے کہا، جب تم مصر واپس جاؤ تو دیکھو کہ فرعون کے سامنے وہ تمام معجزے کرو، جو میں نے تمہارے ہاتھ میں دیے ہیں، لیکن میں اس کا دل سخت کر دوں گا، تاکہ وہ لوگوں کو جانے نہ دے۔\n22۔ اور تم فرعون سے کہو گے، خداوند یوں فرماتا ہے، اسرائیل میرا بیٹا ہے، میرا پہلا بیٹا بھی:\n23۔ اور میں تم سے کہتا ہوں، میرے بیٹے کو جانے دو، تاکہ وہ میری خدمت کرے: اور اگر تم اسے جانے سے انکار کرو گے، تو دیکھو، میں تمہارے بیٹے کو، حتیٰ کہ تمہارے پہلے بیٹے کو بھی مار ڈالوں گا۔\n24۔ اور سرائے میں راستے سے ایسا ہوا کہ خداوند نے اس سے ملاقات کی اور اسے مارنے کی کوشش کی۔\n25۔ پھر زپورہ نے ایک تیز پتھر لیا، اپنے بیٹے کی کھال کاٹ دی، اور اس کے قدموں میں پھینک دیا، اور کہا، یقینا تم میرے لیے خونخوار شوہر ہو۔ {تیز...: یا، چاقو} {کاسٹ...: عبوری۔ اسے چھونے پر مجبور کیا}\n26۔ تو اس نے اسے جانے دیا: پھر اس نے کہا، خونخوار شوہر {تم ہو}، ختنہ کی وجہ سے۔\n27۔ اور خداوند نے ہارون سے کہا، موسیٰ سے ملنے کے لیے بیابان میں جاؤ۔ اور وہ گیا، اور خدا کے پہاڑ میں اس سے ملا، اور اسے بوسہ دیا۔\n28۔ اور موسیٰ نے ہارون کو خداوند کے تمام الفاظ سنائے جس نے اسے بھیجا تھا، اور وہ تمام علامات جو اس نے حکم دی تھیں۔\n29۔ اور موسیٰ اور ہارون گئے اور بنی اسرائیل کے تمام بزرگوں کو اکٹھا کیا:\n30۔ اور ہارون نے وہ تمام الفاظ کہے جو خداوند نے موسیٰ سے کہے تھے، اور لوگوں کے سامنے نشانیاں دکھائیں۔\n31۔ اور لوگوں نے ایمان لایا: اور جب انہوں نے سنا کہ خداوند نے بنی اسرائیل سے ملاقات کی ہے اور ان کی مصیبت دیکھی ہے، تو انہوں نے سر جھکا کر عبادت کی۔","1۔ اور اس کے بعد موسیٰ اور ہارون اندر گئے اور فرعون سے کہا، خداوند اسرائیل کہتا ہے، میرے لوگوں کو جانے دو، تاکہ وہ میرے لیے صحرا میں دعوت منائیں۔\n2۔ اور فرعون نے کہا، خداوند کون ہے، کہ میں اس کی آواز مانوں تاکہ اسرائیل کو جانے دوں؟ میں خدا کو نہیں جانتا، نہ ہی میں اسرائیل کو جانے دوں گا۔\n3۔ اور انہوں نے کہا، عبرانیوں کے خدا نے ہم سے ملاقات کی ہے: ہم دعا کرتے ہیں کہ ہم تین دن کے سفر پر صحرا میں جائیں، اور خداوند ہمارے خدا کو قربانی دیں؛ کہیں وہ ہم پر وبا یا تلوار سے نہ آ جائے۔\n4۔ اور مصر کے بادشاہ نے ان سے کہا، موسیٰ اور ہارون، تم لوگوں کو اپنے اعمال سے کیوں محروم کرتے ہو؟ تمہیں تمہارے بوجھوں سے اتارنا۔\n5۔ اور فرعون نے کہا، دیکھو، اب زمین کے لوگ بہت ہیں، اور تم انہیں ان کے بوجھ سے آرام دیتے ہو۔\n6۔ اور فرعون نے اسی دن لوگوں کے ذمہ داروں اور ان کے افسران کو حکم دیا، کہا،\n7۔ اب آپ لوگوں کو اینٹ بنانے کے لیے تنکا نہیں دیں گے، جیسا کہ پہلے تھا: انہیں جانے دو اور اپنے لیے تنکا جمع کریں۔\n8۔ اور اینٹوں کی کہانی، جو انہوں نے پہلے بنائی تھیں، تم ان پر رکھو گے؛ تم اس میں کمی نہیں کرو گے: کیونکہ وہ بیکار ہیں؛ اسی لیے وہ پکار رہے ہیں، کہتے ہیں، آؤ ہم جائیں اور اپنے خدا کے لیے قربانی دیں۔\n9۔ مردوں پر زیادہ کام کیا جائے تاکہ وہ اس میں محنت کر سکیں؛ اور وہ فضول باتوں کو نہ سمجھیں۔ {چھوڑ دو...: عبرانی۔ کام مردوں پر بھاری ہو}\n10۔ اور لوگوں کے ذمہ دار باہر نکلے، اور ان کے افسران بھی، اور لوگوں سے بات کرنے لگے، \"فرعون کہتا ہے، میں تمہیں تنکا نہیں دوں گا۔\n11. جاؤ، جہاں تمہیں تنکا ملے وہاں لے جاؤ: پھر بھی تمہارا کام کم نہیں ہونا چاہیے۔\n12۔ یوں لوگ پورے مصر کی سرزمین میں بکھر گئے تاکہ بھوسہ کی جگہ داڑھی جمع کی جا سکے۔\n13۔ اور ذمہ داروں نے جلدی میں کہا، اپنے کام اور روزمرہ کے کام انجام دو، جیسے بھوسہ ہو۔ {آپ کا روزنامہ...: عبرانی یہ اس کے دن کے ایک دن کا معاملہ تھا}\n14۔ اور بنی اسرائیل کے وہ افسران، جنہیں فرعون کے ذمہ داروں نے ان پر مقرر کیا تھا، مارا پیٹا گیا، {اور} پوچھا، کیوں تم نے کل اور آج بھی اینٹ بنانے کا کام کیوں نہیں کیا، جیسا کہ پہلے بھی تھا؟\n15۔ پھر بنی اسرائیل کے افسران آئے اور فرعون سے پکارا، کہا کہ تم اپنے بندوں کے ساتھ ایسا کیوں کرتے ہو؟\n16۔ تمہارے بندوں کو کوئی تنکا نہیں دیا جاتا، اور وہ ہم سے کہتے ہیں، اینٹ بناؤ: اور دیکھو، تمہارے بندے مارا جاتے ہیں؛ لیکن قصور {ہے} تمہارے اپنے لوگوں کا۔\n17۔ لیکن اس نے کہا، تم سست ہو، تم سست ہو، اس لیے تم کہتے ہو، چلو ہم جا کر خداوند کے لیے قربانی دیں۔\n18. اب جاؤ، {اور} کام کرو؛ کیونکہ تمہیں کوئی تنکا نہیں دیا جائے گا، پھر بھی تم اینٹوں کی کہانی سناؤ گے۔\n19۔ اور بنی اسرائیل کے افسران نے دیکھا کہ وہ برائی میں ہیں، جب کہا گیا، تم اپنے روزمرہ کے کام کی اینٹوں سے نہ نکالو۔\n20۔ اور وہ موسیٰ اور ہارون سے ملے، جو راستے میں کھڑے تھے، جب وہ فرعون سے باہر آئے:\n21۔ اور انہوں نے ان سے کہا، خداوند تمہیں دیکھے اور فیصلہ کرے؛ کیونکہ تم نے ہمارے ذائقے کو فرعون کی نظر میں اور اس کے بندوں کی نظر میں نفرت انگیز بنا دیا ہے، تاکہ ان کے ہاتھ میں تلوار رکھ کر ہمیں مار ڈالیں۔ {ہونے والا...: عببرانی۔ تو اسٹنک}\n22۔ اور موسیٰ خداوند کے پاس واپس آیا اور کہا، اے خداوند، تو نے اس قوم پر اتنا برا کیوں بھلا کہا؟ یہ کیوں {ہے} کہ تم نے مجھے بھیجا ہے؟\n23۔ کیونکہ جب سے میں فرعون کے پاس تمہارے نام پر بات کرنے آیا ہوں، اس نے اس قوم کے ساتھ برا کیا ہے؛ نہ ہی تم نے اپنے لوگوں کو بچایا ہے۔ {نہ ہی...: عبرانی تم نے پہنچایا نہیں}","1۔ پھر خداوند نے موسیٰ سے کہا، اب دیکھو میں فرعون کے ساتھ کیا کروں گا، کیونکہ وہ مضبوط ہاتھ سے انہیں جانے دے گا، اور مضبوط ہاتھ سے انہیں اپنی سرزمین سے نکال دے گا۔\n2۔ اور خدا نے موسیٰ سے کہا، اور کہا، میں {ہوں} خداوند ہوں: {خداوند: یا، یہووا}\n3۔ اور میں ابراہیم، اسحاق اور یعقوب کے سامنے ظاہر ہوا، {خدا قادر مطلق کے نام سے}، لیکن میرے نام یہوواہ سے میں ان کے لیے نہیں جانتا تھا۔\n4۔ اور میں نے ان کے ساتھ اپنا عہد بھی قائم کیا ہے کہ انہیں کنعان کی سرزمین دوں، ان کی زیارت کی زمین، جہاں وہ اجنبی تھے۔\n5۔ اور میں نے بنی اسرائیل کی کراہت بھی سنی ہے، جنہیں مصری غلامی میں رکھتے ہیں؛ اور میں نے اپنا عہد یاد کر لیا ہے۔\n6۔ لہٰذا بنی اسرائیل سے کہو، میں خداوند ہوں، اور میں تمہیں مصریوں کے بوجھ سے نکالوں گا، اور تمہیں ان کی غلامی سے آزاد کروں گا، اور تمہیں پھیلائے ہوئے بازو اور بڑے فیصلوں سے نجات دوں گا:\n7۔ اور میں تمہیں اپنی قوم کے طور پر قبول کروں گا، اور تمہارے لیے خدا بنوں گا: اور تم جان لو گے کہ میں تمہارا خداوند خدا ہوں، جو تمہیں مصریوں کے بوجھ سے نکالتا ہے۔\n8۔ اور میں تمہیں اس زمین میں لے آؤں گا جس کے بارے میں میں نے قسم کھائی تھی کہ اسے ابراہیم، اسحاق اور یعقوب کو دوں گا؛ اور میں اسے آپ کو وراثت کے طور پر دوں گا: میں خداوند ہوں۔ {قسم کھاتا ہے: عبرانی۔ میرا ہاتھ اٹھاؤ}\n9۔ اور موسیٰ نے بنی اسرائیل سے یہی کہا: لیکن انہوں نے موسیٰ کی بات روح کی اذیت اور ظالمانہ غلامی کے لیے نہیں سنی۔ {اذیت: عبرانی۔ مختصر، یا، سختی\n10۔ اور خداوند نے موسیٰ سے کہا،\n11۔ اندر جاؤ، مصر کے بادشاہ فرعون سے بات کرو کہ اس نے بنی اسرائیل کو اپنی سرزمین سے باہر جانے دیا۔\n12۔ اور موسیٰ نے خداوند کے سامنے کہا، \"دیکھو، بنی اسرائیل نے میری بات نہیں مانی؛ تو فرعون مجھے کیسے سنے گا، جو {میں} غیر ختنہ شدہ ہونٹوں والا ہوں؟\n13۔ اور خداوند نے موسیٰ اور ہارون سے کہا، اور انہیں بنی اسرائیل اور مصر کے بادشاہ فرعون کو حکم دیا کہ وہ بنی اسرائیل کو مصر کی سرزمین سے نکالیں۔\n14۔ یہ ان کے باپ اجداد کے خاندانوں کے سربراہ ہیں: اسرائیل کے پہلے بیٹے روبن کے بیٹے؛ حنوخ، اور پالو، ہیزرون، اور کارمی: یہ {ہیں} روبن کے خاندان۔\n15۔ اور شمعون کے بیٹے؛ جیموئیل، اور یمین، اور اوہد، اور یخین، اور زوہار، اور شاؤل، جو ایک کنعانی عورت کا بیٹا تھا: یہ سیمعون کے خاندان ہیں۔\n16۔ اور یہ لاوی کے بیٹوں کے نام ہیں جو ان کی نسلوں کے مطابق ہیں؛ گرشون، کوہات، اور میراری: اور لاوی کی زندگی کے سال سو تیس سات سال تھے۔\n17۔ گرشون کے بیٹے؛ لبنی اور شیمی، ان کے خاندانوں کے مطابق۔\n18۔ اور کوہات کے بیٹے؛ عمرم، اور اظہار، اور حبرون، اور عزیل: اور کوہات کی زندگی کے سال ایک سو تیس تین سال تھے۔\n19۔ اور مراری کے بیٹے؛ مہالی اور موشی: یہ اپنی نسلوں کے مطابق لاوی کے خاندان ہیں۔\n20۔ اور امرام نے اسے اپنے والد کی بہن یوکبید کی بیوی بنا لی؛ اور اس نے اسے ہارون اور موسیٰ جنم دیا: اور عمرم کی زندگی کے سال ایک سو تیس سات سال تھے۔\n21۔ اور ازہر کے بیٹے؛ کورہ، نیفیگ، اور زکری۔\n22۔ اور عزئیل کے بیٹے؛ مشائل، اور الزفان، اور زیتھری۔\n23۔ اور ہارون نے اسے الیشبع، امیناداب کی بیٹی اور نعشون کی بہن کو بیوی بنایا؛ اور اس نے اسے نداب، ابیہو، الیعازر اور ایثمار کو جنم دیا۔\n24۔ اور قورح کے بیٹے؛ آسیر، الکانہ، اور ابیاصف: یہ {ہیں} کورہیوں کے خاندان۔\n25۔ اور الیعازر ہارون کے بیٹے نے اسے پوتیئل کی بیٹیوں میں سے ایک کی شادی کر لی؛ اور اس نے اسے فینحاس پیدا کیا: یہ لاویوں کے باپوں کے سربراہ ہیں ان کے خاندانوں کے مطابق۔\n26۔ یہ وہ ہیں جو ہارون اور موسیٰ نے فرمایا، جن سے خداوند نے فرمایا، بنی اسرائیل کو ان کی فوجوں کے مطابق مصر کی سرزمین سے نکالو۔\n27۔ یہ وہ لوگ ہیں جنہوں نے مصر کے بادشاہ فرعون سے بات کی کہ وہ اسرائیل کے بچوں کو مصر سے نکالے: یہ وہ موسیٰ اور ہارون ہیں۔\n28۔ اور یہ اس دن ہوا جب {جب} خداوند نے مصر کی سرزمین میں موسیٰ سے فرمایا،\n29۔ کہ خداوند نے موسیٰ سے کہا، میں {ہوں} خداوند ہوں: تو فرعون بادشاہ مصر سے جو کچھ میں کہتا ہوں وہ سب کہہ دو۔\n30۔ اور موسیٰ نے خداوند کے سامنے کہا، دیکھو، میں غیر ختنہ شدہ ہونٹوں سے ہوں، اور فرعون میری بات کیسے سنے گا؟","1۔ اور خداوند نے موسیٰ سے کہا، دیکھو، میں نے تمہیں فرعون کا خدا بنایا ہے: اور ہارون تمہارا بھائی تمہارا نبی ہوگا۔\n2۔ تم وہ سب کچھ کہو جو میں تمہیں حکم دیتا ہوں: اور ہارون تمہارا بھائی فرعون سے کہے گا کہ وہ بنی اسرائیل کو اپنی سرزمین سے نکال دے۔\n3۔ اور میں فرعون کے دل کو سخت کروں گا، اور اپنے نشانات اور عجائبات کو مصر کی سرزمین میں بڑھاؤں گا۔\n4۔ لیکن فرعون تمہاری بات نہیں سنے گا کہ میں مصر پر ہاتھ اٹھا کر اپنی فوجیں اور اپنی قوم بنی اسرائیل کو عظیم فیصلوں کے ذریعے مصر کی سرزمین سے نکالوں۔\n5۔ اور مصری جان جائیں گے کہ میں خداوند ہوں، جب میں اپنا ہاتھ مصر پر بڑھاؤں گا، اور ان میں سے بنی اسرائیل کو نکالوں گا۔\n6۔ اور موسیٰ اور ہارون نے خداوند کے حکم کے مطابق کیا، تو انہوں نے بھی ایسا ہی کیا۔\n7۔ اور موسیٰ {چالیس سالہ} تھا، اور ہارون چالیس اور تین سال کا، جب انہوں نے فرعون سے بات کی۔\n8۔ اور خداوند نے موسیٰ اور ہارون سے کہا،\n9۔ جب فرعون تم سے کہے گا، کہے گا، تمہارے لیے کوئی معجزہ دکھاؤ، تب تم ہارون سے کہو گے، اپنی چھڑی لے لو، اور فرعون کے سامنے پھینک دو، اور وہ سانپ بن جائے گا۔\n10۔ اور موسیٰ اور ہارون فرعون کے پاس گئے، اور جیسا کہ خداوند نے حکم دیا تھا ویسا ہی کیا: اور ہارون نے اپنی لاٹھی فرعون اور اس کے بندوں کے سامنے پھینکی، اور وہ سانپ بن گیا۔\n11۔ پھر فرعون نے دانا اور جادوگر بھی بلائے: اب مصر کے جادوگر بھی اپنے جادو کے ساتھ ایسا ہی کرتے تھے۔\n12۔ کیونکہ انہوں نے ہر آدمی کو اس کی چھڑی پھینک دی، اور وہ سانپ بن گئے: لیکن ہارون کی چھڑی نے ان کی چھڑیاں نگل لیں۔\n13۔ اور اس نے فرعون کے دل کو سخت کر دیا، کہ اس نے ان کی بات نہ مانی؛ جیسا کہ خداوند نے فرمایا۔\n14۔ اور خداوند نے موسیٰ سے کہا، فرعون کا دل سخت ہو گیا ہے، وہ لوگوں کو جانے نہیں دیتا۔\n15۔ صبح فرعون کے پاس چلے جاؤ؛ دیکھو، وہ پانی کی طرف جاتا ہے؛ اور تم دریا کے کنارے اس کے آنے کے خلاف کھڑے رہو گے؛ اور وہ چھڑی جو سانپ کی شکل اختیار کی گئی تھی، اسے تم اپنے ہاتھ میں لے لو گی۔\n16۔ اور تم اسے کہو گے، عبرانیوں کے خداوند خدا نے مجھے تمہارے پاس بھیجا ہے، کہہ رہا ہوں، میرے لوگوں کو جانے دو، تاکہ وہ بیابان میں میری خدمت کریں، اور دیکھو، اب تک تم سننا نہیں چاہتے۔\n17۔ خداوند یہ فرماتا ہے، اس میں تم جان لو گے کہ میں خداوند ہوں: دیکھو، میں اس چھڑی سے جو میرے ہاتھ میں ہے، دریا میں موجود پانیوں پر وار کروں گا، اور وہ خون میں بدل جائیں گے۔\n18۔ اور جو مچھلی دریا میں ہے وہ مر جائے گی، اور دریا بدبو دار کرے گا؛ اور مصری دریا کے پانی سے پینے سے نفرت کریں گے۔\n19۔ اور خداوند نے موسیٰ سے کہا، ہارون سے فرماو، اپنا عصا لے لو، اور اپنا ہاتھ مصر کے پانیوں پر، ان کی ندیوں پر، ان کے تالابوں پر، ان کے تالابوں پر، اور ان کے تمام تالابوں پر پھیلاؤ، تاکہ وہ خون بن جائیں؛ اور {کہ} پورے مصر کی سرزمین میں خون ہو سکتا ہے، چاہے وہ لکڑی کے برتنوں میں ہو یا پتھر کے برتنوں میں۔ {پولز...: عببرانی۔ اپنے پانیوں کا جمع کرنا}\n20۔ اور موسیٰ اور ہارون نے خداوند کے حکم کے مطابق ایسا کیا؛ اور اس نے چھڑی اٹھائی، اور دریا میں موجود پانیوں کو مارا جو فرعون کے سامنے اور اپنے خادموں کی نظر میں تھے؛ اور دریا میں موجود تمام پانی خون میں بدل گئے۔\n21۔ اور وہ مچھلی جو دریا میں تھی مر گئی؛ اور دریا بدبو دار تھا، اور مصری دریا کے پانی سے پانی نہیں پی سکتے تھے؛ اور پورے مصر کی سرزمین میں خون بہہ گیا۔\n22۔ اور مصر کے جادوگروں نے اپنے جادو سے ایسا کیا: اور فرعون کا دل سخت ہو گیا، نہ ہی اس نے ان کی بات مانی؛ جیسا کہ خداوند نے فرمایا۔\n23۔ اور فرعون مڑا اور اپنے گھر گیا، اور اس نے اس پر بھی دل نہیں لگایا۔\n24۔ اور تمام مصریوں نے پانی کے لیے دریا کے ارد گرد کھود کر پانی تلاش کیا؛ کیونکہ وہ دریا کے پانی سے نہیں پی سکتے تھے۔\n25۔ اور سات دن مکمل ہوئے، اس کے بعد خداوند نے دریا کو مارا۔","1۔ اور خداوند نے موسیٰ سے کہا، فرعون کے پاس جاؤ اور اسے کہے، خداوند یوں فرماتا ہے، میرے لوگوں کو جانے دو تاکہ وہ میری خدمت کریں۔\n2۔ اور اگر تم انہیں جانے دینے سے انکار کرو گے، دیکھو، میں تمہارے تمام سرحدوں کو مینڈکوں سے مار دوں گا:\n3۔ اور دریا بہت سے مینڈک نکالے گا، جو اوپر جائیں گے اور تمہارے گھر میں، تمہارے بستر میں، تمہارے بستر پر، تمہارے خادموں کے گھر، تمہارے لوگوں پر، تمہارے تندور میں، اور تمہارے گوندھنے کے خانے میں: {گوندھنے کے خانے یا، آٹا}\n4۔ اور مینڈک تم پر، تمہارے لوگوں پر، اور تمہارے تمام بندوں پر آ جائیں گے۔\n5۔ اور خداوند نے موسیٰ سے کہا، ہارون سے فرماو، اپنی چھڑی سے اپنا ہاتھ نالوں، دریاؤں اور تالابوں پر پھیلا دے، اور مینڈکوں کو مصر کی سرزمین پر لے آؤ۔\n6۔ اور ہارون نے مصر کے پانیوں پر اپنا ہاتھ بڑھایا؛ اور مینڈک اوپر آئے، اور مصر کی سرزمین کو ڈھانپ لیا۔\n7۔ اور جادوگروں نے اپنے جادوؤں سے ایسا کیا، اور مصر کی سرزمین پر مینڈک پیدا کیے۔\n8۔ پھر فرعون نے موسیٰ اور ہارون کو بلایا اور کہا، خداوند سے دعا گو کہ وہ مینڈک مجھ سے اور میرے لوگوں سے چھین لے؛ اور میں لوگوں کو جانے دوں گا، تاکہ وہ خداوند کے لیے قربانی دیں۔\n9۔ اور موسیٰ نے فرعون سے کہا، مجھ پر جلال: میں کب تمہارے لیے، تمہارے بندوں اور تمہارے لوگوں کے لیے دعا کروں گا کہ تم اور تمہارے گھروں سے مینڈک ختم کر دوں، تاکہ وہ صرف دریا میں رہ سکیں؟ {جلال...: یا، یہ عزت مجھ پر رکھو، وغیرہ} {جب: یا، کب کے خلاف} {تباہ کرنے کے لیے: عبرانی۔ کٹ آف کرنے کے لیے}\n10۔ اور اس نے کہا، کل۔ اور اس نے کہا، {ہو جائے} تیری بات کے مطابق: تاکہ تم جان سکو کہ خداوند ہمارے خدا جیسا کوئی نہیں۔ {کل کے لیے: یا، کل کے خلاف}\n11۔ اور مینڈک تم سے، تمہارے گھروں سے، تمہارے خادموں، اور تمہارے لوگوں سے چلے جائیں گے؛ وہ صرف دریا میں ہی رہیں گے۔\n12۔ اور موسیٰ اور ہارون فرعون سے باہر نکلے: اور موسیٰ نے خداوند سے دعا کی کیونکہ اس نے فرعون کے خلاف مینڈک لائے تھے۔\n13۔ اور خداوند نے موسیٰ کے کلام کے مطابق کیا؛ اور مینڈک گھروں سے، دیہاتوں اور کھیتوں سے مر گئے۔\n14۔ اور انہوں نے انہیں ڈھیر کی صورت میں جمع کیا: اور زمین بدبو دار تھی۔\n15۔ لیکن جب فرعون نے دیکھا کہ آرام ہے، تو اس نے اپنا دل سخت کر لیا اور ان کی بات نہیں مانی؛ جیسا کہ خداوند نے فرمایا۔\n16۔ اور خداوند نے موسیٰ سے کہا، ہارون سے کہو، اپنی چھڑی پھیلا کر زمین کی خاک کو مار ڈال تاکہ وہ پورے مصر کی زمین میں جوئیں بن جائے۔\n17۔ اور انہوں نے ایسا کیا؛ کیونکہ ہارون نے اپنی چھڑی سے اپنا ہاتھ بڑھایا، اور زمین کی خاک کو مارا اور وہ انسان اور جانور میں جوئیں بن گئی؛ زمین کی ساری خاک پورے مصر کی سرزمین میں جوئیں بن گئی۔\n18۔ اور جادوگروں نے اپنے جادو سے جوئیں نکالنے کے لیے ایسا کیا، لیکن وہ نہیں کر سکے: یوں جوئیں انسان پر اور جانور پر بھی۔\n19۔ پھر جادوگروں نے فرعون سے کہا، یہ خدا کی انگلی ہے: اور فرعون کا دل سخت ہو گیا، اور اس نے ان کی بات نہیں مانی؛ جیسا کہ خداوند نے فرمایا۔\n20۔ اور خداوند نے موسیٰ سے کہا، صبح سویرے اٹھو اور فرعون کے سامنے کھڑے ہو جا؛ دیکھو، وہ پانی کی طرف آتا ہے؛ اور اس سے کہوں، خداوند یوں فرماتا ہے، میرے لوگوں کو جانے دو، تاکہ وہ میری خدمت کریں۔\n21۔ ورنہ، اگر تم میرے لوگوں کو جانے نہیں دیتے، تو میں تم پر، تمہارے غلاموں، تمہارے لوگوں پر، اور تمہارے گھروں پر مکھیوں کے جھنڈ بھیجوں گا، اور مصریوں کے گھر مکھیوں کے جھنڈ سے بھر جائیں گے، اور اس زمین سے بھی، جس پر وہ [ہیں}۔ {جھنڈ...: یا، شور مچانے والے جانوروں کا مرکب وغیرہ}\n22۔ اور میں اسی دن گوشن کی سرزمین کو کاٹ دوں گا، جہاں میرے لوگ رہتے ہیں، تاکہ وہاں مکھیوں کے جھنڈ نہ ہوں؛ آخر تک تم جان سکتے ہو کہ میں زمین کے بیچ میں خداوند ہوں۔\n23۔ اور میں اپنی قوم اور تمہارے لوگوں کے درمیان تقسیم کروں گا: کل یہ نشانی ہوگی۔ {a تقسیم: عبرانی۔ ایک نجات} {کل کے لیے: یا، کل کے لیے}\n24۔ اور خداوند نے ایسا کیا؛ اور ایک خوفناک جھنڈ {مکھیوں کا} فرعون کے گھر، اس کے نوکروں کے گھروں میں، اور پورے مصر کی سرزمین میں داخل ہوا: زمین مکھیوں کے جھنڈ کی وجہ سے خراب ہو گئی۔ {خراب شدہ: یا، تباہ شدہ}\n25۔ اور فرعون نے موسیٰ اور ہارون کو بلایا اور کہا، \"جاؤ، زمین میں اپنے خدا کے لیے قربانی دو۔\n26۔ اور موسیٰ نے کہا، ایسا کرنا مناسب نہیں؛ کیونکہ ہم مصریوں کی مکروہ قربانی خداوند اپنے خدا کے سامنے قربان کریں گے: کیا ہم مصریوں کی مکروہ چیز کو ان کی آنکھوں کے سامنے قربان کریں گے، اور کیا وہ ہمیں پتھر نہیں ماریں گے؟\n27. ہم تین دن کا سفر صحرا میں جائیں گے، اور خداوند ہمارے خدا کو قربانی دیں گے، جیسا کہ وہ ہمیں حکم دے گا۔\n28۔ اور فرعون نے کہا، میں تمہیں جانے دوں گا تاکہ تم بیابان میں اپنے خداوند خدا کے سامنے قربانی دو؛ صرف تم زیادہ دور نہیں جاؤ گے: میرے لیے التجا کرو۔\n29۔ اور موسیٰ نے کہا، دیکھو، میں تم سے نکل رہا ہوں، اور خداوند سے درخواست کرتا ہوں کہ مکھیوں کے جھنڈ فرعون، اس کے بندوں اور اس کے لوگوں سے کل روانہ ہو جائیں: لیکن فرعون مزید دھوکہ نہ دے کہ لوگ خدا کے لیے قربانی دینے نہ جائیں۔\n30۔ اور موسیٰ فرعون سے باہر نکلا، اور خداوند سے دعا کی۔\n31۔ اور خداوند نے موسیٰ کے کلام کے مطابق کیا؛ اور اس نے فرعون، اپنے خادموں، اور اپنے لوگوں سے مکھیوں کے جھنڈ نکال دیے؛ کوئی بھی باقی نہیں رہا۔\n32۔ اور فرعون نے اس وقت بھی اپنا دل سخت کر لیا، نہ ہی اس نے لوگوں کو جانے دیا۔","1۔ پھر خداوند نے موسیٰ سے کہا، فرعون کے پاس جاؤ اور اسے کہو، یوں عبرانیوں کے خداوند خدا نے فرمایا، میرے لوگوں کو جانے دو تاکہ وہ میری خدمت کریں۔\n2۔ کیونکہ اگر تم انہیں چھوڑنے سے انکار کرو گے، اور انہیں روک لو گے،\n3۔ دیکھو، خداوند کا ہاتھ تمہارے مویشیوں پر ہے جو کھیت میں، گھوڑوں پر، گدھوں پر، اونٹوں، بیلوں اور بھیڑوں پر ہے: وہاں بہت شدید بارش ہوگی۔\n4۔ اور خداوند اسرائیل کے مویشیوں اور مصر کے مویشیوں کے درمیان کاٹ دے گا: اور اسرائیل کے تمام اولاد میں سے کوئی نہیں مرے گا۔\n5۔ اور خداوند نے ایک مقررہ وقت مقرر کیا، کہا، کل خداوند یہ کام زمین میں کرے گا۔\n6۔ اور خداوند نے وہ کام کل کیا، اور مصر کے تمام مویشی مر گئے، لیکن بنی اسرائیل کے مویشیوں میں سے ایک بھی نہیں مرا۔\n7۔ اور فرعون نے بھیجا، اور دیکھتے ہی بنی اسرائیل کے مویشیوں میں سے ایک بھی مردہ نہیں رہا۔ اور فرعون کا دل سخت ہو گیا، اور اس نے لوگوں کو جانے نہیں دیا۔\n8۔ اور خداوند نے موسیٰ اور ہارون سے کہا، اپنے پاس بھٹی کی راکھ کے مٹھی بھر لو، اور موسیٰ اسے فرعون کے سامنے آسمان کی طرف چھڑکنے دو۔\n9۔ اور یہ پورے مصر کی سرزمین میں چھوٹا سا غبار بن جائے گا، اور ایک پھوڑا بن جائے گا جو انسان اور جانور پر پورے مصر کی سرزمین پر پھوٹے گا۔\n10۔ اور انہوں نے بھٹی کی راکھ لی اور فرعون کے سامنے کھڑے ہو گئے؛ اور موسیٰ نے اسے آسمان کی طرف چھڑکا؛ اور وہ ایک پھوڑا بن گیا جو انسان اور جانور پر پھوٹ پڑا۔\n11۔ اور جادوگر موسیٰ کے سامنے کھڑے نہ ہو سکے کیونکہ پھوڑے تھے؛ کیونکہ پھوڑا جادوگروں اور تمام مصریوں پر تھا۔\n12۔ اور خداوند نے فرعون کے دل کو سخت کیا، اور اس نے ان کی بات نہیں مانی؛ جیسا کہ خداوند نے موسیٰ سے کہا تھا۔\n13۔ اور خداوند نے موسیٰ سے کہا، صبح سویرے اٹھو، اور فرعون کے سامنے کھڑے ہو جاؤ اور اس سے کہو، یوں عبرانیوں کے خداوند خدا نے فرمایا، میرے لوگ جانے دو، تاکہ وہ میری خدمت کریں۔\n14۔ کیونکہ اس وقت میں اپنی تمام آفات تیرے دل، تمہارے بندوں اور تمہارے لوگوں پر بھیجوں گا؛ تاکہ تم جان سکو کہ زمین پر میرے جیسا کوئی نہیں۔\n15۔ اب میں اپنا ہاتھ بڑھاؤں گا، تاکہ تمہیں اور تمہارے لوگوں کو وبا سے مار سکوں؛ اور تم زمین سے جدا ہو جاؤ گے۔\n16۔ اور اسی مقصد کے لیے میں نے تمہیں اٹھایا ہے، تاکہ تمہیں اپنی طاقت دکھاؤں؛ اور تاکہ میرا نام پوری زمین پر اعلان کیا جائے۔ {اٹھا ہوا...: عببرانی۔ تمہیں کھڑا کیا}\n17. کیا تم ابھی تک اپنے آپ کو میرے لوگوں کے خلاف بلند کر رہے ہو، کہ تم انہیں جانے نہیں دو گے؟\n18۔ دیکھو، کل اس وقت کے قریب میں ایک بہت شدید اولے برساؤں گا، جو مصر کی بنیاد سے اب تک نہیں ہوئی۔\n19۔ تو اب بھیجو، {اور} اپنے مویشی اور جو کچھ تمہارے کھیت میں ہے جمع کرو؛ {کیونکہ} ہر انسان اور جانور جو میدان میں ملے گا اور گھر واپس نہیں آئے گا، ان پر اولے برسیں گے اور وہ مر جائیں گے۔\n20۔ جو فرعون کے خادموں میں خداوند کے کلام سے ڈرتا تھا، اس نے اپنے خادموں اور مویشیوں کو گھروں میں بھاگنے پر مجبور کیا:\n21۔ اور جو خدا کے کلام کو نہ سمجھتا تھا، اس نے اپنے خادموں اور مویشیوں کو کھیت میں چھوڑ دیا۔ {غور کیا گیا...: عبرانی۔ اس کا دل مت رکھو}\n22۔ اور خداوند نے موسیٰ سے فرمایا، اپنا ہاتھ آسمان کی طرف بڑھاؤ، تاکہ مصر کی پوری سرزمین پر، انسانوں پر، جانور پر، اور کھیت کی ہر جڑی بوٹی پر اولے پڑ جائیں۔\n23۔ اور موسیٰ نے اپنی چھڑی آسمان کی طرف بڑھائی، اور خداوند نے گرج اور اولے بھیجے، اور آگ زمین پر بہنے لگی؛ اور خداوند نے مصر کی زمین پر اولے برسائے۔\n24۔ تو اولے اور آگ اولے کے ساتھ مل گئی، جو بہت شدید تھی، جیسے مصر کی سرزمین میں اس جیسی کوئی نہیں تھی جب سے وہ قوم بنی تھی۔\n25۔ اور اولے نے پورے مصر کی زمین پر جو کچھ بھی میدان میں تھا، انسان اور جانور دونوں پر برسا؛ اور اولے نے کھیت کی ہر جڑی بوٹی کو گرایا، اور میدان کے ہر درخت کو توڑ دیا۔\n26۔ صرف گوشن کی سرزمین میں، جہاں بنی اسرائیل تھے، کوئی اولے نہیں تھا۔\n27۔ اور فرعون نے بھیجا، اور موسیٰ اور ہارون کو بلایا، اور ان سے کہا، اس بار میں نے گناہ کیا ہے: خداوند راستباز ہے، اور میں اور میرے لوگ بدکار ہیں۔\n28۔ خداوند سے دعا کرو (کیونکہ {یہ} کافی ہے) کہ مزید کوئی زبردست گرج اور اولے نہ ہوں؛ اور میں تمہیں جانے دوں گا، اور تم مزید نہیں رہو گے۔ {mighty...: عبرانی خدا کی آوازیں}\n29۔ اور موسیٰ نے اس سے کہا، جیسے ہی میں شہر سے نکل جاؤں گا، میں اپنے ہاتھ خداوند کے سامنے پھیلاؤں گا؛ {اور} گرج رک جائے گی، نہ ہی مزید اولے ہوں گے؛ تاکہ تم جان سکو کہ زمین خدا کی ہے۔\n30۔ لیکن جہاں تک تم اور تمہارے بندوں کا تعلق ہے، میں جانتا ہوں کہ تم ابھی خداوند خدا سے نہیں ڈرو گے۔\n31۔ اور فلیکس اور جو کو پسند آ گیا: کیونکہ جو کان میں تھا، اور فلیکس {بولڈ} ہو گیا۔\n32۔ لیکن گندم اور ریہ اس پر فدا نہیں ہوئے: کیونکہ وہ بالغ نہیں ہوئے تھے۔ {غیر بالغ...: عبرانی۔ چھپا ہوا یا تاریک}\n33۔ اور موسیٰ فرعون سے شہر سے باہر نکلا اور اپنے ہاتھ خداوند کے سامنے پھیلائے، اور گرج اور اولے رک گئے، اور بارش زمین پر نہ برسی۔\n34۔ اور جب فرعون نے دیکھا کہ بارش، اولے اور گرج رک گئی ہیں، تو اس نے مزید گناہ کیا، اور اپنے دل، وہ اور اس کے خادموں کو سخت کر دیا۔\n35۔ اور فرعون کا دل سخت ہو گیا، نہ ہی اس نے بنی اسرائیل کو جانے دیا؛ جیسا کہ خداوند نے موسیٰ کے ذریعے فرمایا۔ {از موسیٰ: عبرانی۔ موسیٰ کے ہاتھ سے}","1۔ اور خداوند نے موسیٰ سے کہا، فرعون کے پاس جاؤ، کیونکہ میں نے اس کے دل اور اس کے بندوں کے دل کو سخت کر دیا ہے، تاکہ میں اپنے نشانات اس کے سامنے دکھا سکوں:\n2۔ اور تاکہ تم اپنے بیٹے اور اپنے بیٹے کے بیٹے کے کانوں میں بتا سکو کہ میں نے مصر میں کیا کچھ کیا اور میرے نشانات جو میں نے ان کے درمیان کیے ہیں؛ تاکہ تم جان سکو کہ میں خداوند ہوں۔\n3۔ اور موسیٰ اور ہارون فرعون کے پاس آئے اور اس سے کہا، عبرانیوں کے خداوند خدا نے یوں فرمایا، کتنی دیر تک تم میرے سامنے عاجزی نہیں کرو گے؟ میرے لوگوں کو جانے دو، تاکہ وہ میری خدمت کر سکیں۔\n4۔ ورنہ، اگر تم میرے لوگوں کو جانے نہیں دیتے، تو دیکھو، کل میں ٹڈی دل تمہارے ساحل پر لے آؤں گا:\n5۔ اور وہ زمین کے چہرے کو ڈھانپ دیں گے تاکہ کوئی زمین کو نہ دیکھ سکے: اور وہ جو باقی رہ گیا ہے اس کا باقیات جو تمہیں اولے سے بچ گیا ہے کھائیں گے، اور ہر وہ درخت کھائیں گے جو تمہارے لیے کھیت سے اگتا ہے: {چہرہ: عبرانی۔ آنکھ}\n6۔ اور وہ تمہارے گھروں کو، تمہارے تمام خادموں کے گھروں اور تمام مصریوں کے گھروں کو بھر دیں گے؛ جو نہ تمہارے باپ اجداد نے دیکھی ہے، نہ تمہارے باپ اجداد نے اس دن سے جب وہ زمین پر تھے اور آج تک۔ اور اس نے خود کو موڑ لیا، اور فرعون سے باہر نکل گیا۔\n7۔ اور فرعون کے خادموں نے اس سے کہا، یہ آدمی کب تک ہمارے لیے جال رہے گا؟ مردوں کو جانے دو، تاکہ وہ خداوند اپنے خدا کی عبادت کریں: کیا تم ابھی تک نہیں جانتے کہ مصر تباہ ہو چکا ہے؟\n8۔ اور موسیٰ اور ہارون کو فرعون کے پاس واپس لایا گیا، اور اس نے ان سے کہا، جاؤ، اپنے خداوند خدا کی عبادت کرو: {لیکن} وہ کون ہیں جو جائیں گے؟ {کون...: عبرانی۔ کون اور کون، وغیرہ}\n9۔ اور موسیٰ نے کہا، ہم اپنے بچوں اور بوڑھوں کے ساتھ، اپنے بیٹوں اور بیٹیوں کے ساتھ، اپنے ریوڑ اور اپنے ریوڑ کے ساتھ جائیں گے؛ کیونکہ ہمیں خداوند کے لیے دعوت منانی ہے۔\n10۔ اور اس نے ان سے کہا، خداوند تمہارے ساتھ ایسا ہی ہو، جیسے میں تمہیں اور تمہارے چھوٹے بچوں کو جانے دوں گا: اس کی طرف دیکھو؛ کیونکہ برائی تمہارے سامنے ہے۔\n11. ایسا نہیں: اب جاؤ اے لوگ اور خدا کی عبادت کرو؛ اسی کے لیے تم چاہتے تھے۔ اور وہ فرعون کی موجودگی سے نکال دیے گئے۔\n12۔ اور خداوند نے موسیٰ سے فرمایا، اپنا ہاتھ مصر کی زمین پر ٹڈی دل کے لیے بڑھاؤ، تاکہ وہ مصر کی زمین پر آ کر زمین کی ہر جڑی بوٹی کھائیں، {حتیٰ کہ} کہ جو اولے بچا ہے۔\n13۔ اور موسیٰ نے اپنی لاٹھی مصر کی سرزمین پر پھیلائی، اور خداوند نے اس پورے دن اور پوری رات زمین پر مشرق کی ہوا لے آیا؛ {اور} جب صبح ہوئی، مشرقی ہوا نے ٹڈی دل لے آئے۔\n14۔ اور ٹڈی دل پورے مصر کی سرزمین پر چڑھ گئے، اور مصر کے تمام ساحلوں پر آرام کرنے لگے: بہت تکلیف دہ تھے؛ ان کے سامنے ایسے ٹڈی دل نہیں تھے، اور نہ ہی ان کے بعد ایسا ہوں گے۔\n15۔ کیونکہ انہوں نے پوری زمین کو ڈھانپ لیا تھا، یہاں تک کہ زمین تاریک ہو گئی؛ اور انہوں نے زمین کی ہر جڑی بوٹی اور اولے کے چھوڑے ہوئے درختوں کے تمام پھل کھائے: اور درختوں میں یا کھیت کی جڑی بوٹیوں میں کوئی سبز چیز باقی نہ رہی، پورے مصر کی سرزمین میں۔\n16۔ پھر فرعون نے جلدی سے موسیٰ اور ہارون کو بلایا؛ اور اس نے کہا، میں نے خداوند تیرے خدا کے خلاف اور تمہارے خلاف گناہ کیا ہے۔ {پکارا: عبوری۔ جلدی سے کال کی}\n17۔ اب میں تم سے صرف اسی بار اپنے گناہ کو معاف کر دے، اور خداوند تمہارے خدا سے درخواست کرو کہ وہ مجھ سے صرف یہ موت چھین لے۔\n18۔ اور وہ فرعون سے باہر نکلا اور خداوند سے دعا کی۔\n19۔ اور خداوند نے ایک زبردست مغربی ہوا چلائی، جس نے ٹڈی دل کو اٹھا کر بحیرہ احمر میں پھینک دیا؛ مصر کے تمام ساحلوں میں ایک بھی ٹڈی دل باقی نہیں رہا۔ {کاسٹ: عبوری۔ بند}\n20۔ لیکن خداوند نے فرعون کے دل کو سخت کر دیا، تاکہ وہ بنی اسرائیل کو جانے نہ دے۔\n21۔ اور خداوند نے موسیٰ سے کہا، اپنا ہاتھ آسمان کی طرف بڑھاؤ، تاکہ مصر کی سرزمین پر اندھیرا چھا جائے، حتیٰ کہ اندھیرا بھی محسوس ہو۔ {حتیٰ کہ...: عبرانی۔ تاکہ کوئی اندھیرا محسوس کر سکے}\n22۔ اور موسیٰ نے اپنا ہاتھ آسمان کی طرف بڑھایا؛ اور پورے مصر کی سرزمین پر تین دن گہری تاریکی چھائی ہوئی تھی:\n23۔ انہوں نے ایک دوسرے کو نہ دیکھا، نہ ہی تین دن تک اس کی جگہ سے اٹھا، لیکن تمام بنی اسرائیل کے گھروں میں روشنی تھی۔\n24۔ اور فرعون نے موسیٰ کو پکارا اور کہا، جاؤ، خداوند کی عبادت کرو؛ صرف اپنے ریوڑ اور ریوڑ کو روک دو: اپنے چھوٹے بچوں کو بھی اپنے ساتھ لے جاؤ۔\n25۔ اور موسیٰ نے کہا، تو ہمیں قربانیاں اور سلائی کی قربانیاں بھی دینی چاہئیں، تاکہ ہم خداوند اپنے خدا کو قربانی دے سکیں۔ {ہم: عبرانی۔ ہمارے ہاتھوں میں}\n26۔ ہمارے مویشی بھی ہمارے ساتھ جائیں گے؛ کوئی کھر پیچھے نہیں چھوڑے گا؛ کیونکہ اسی لیے ہمیں خداوند اپنے خدا کی خدمت کرنی چاہیے؛ اور ہم نہیں جانتے کہ ہمیں خداوند کی خدمت کس چیز سے کرنی ہے، جب تک کہ ہم وہاں نہ پہنچ جائیں۔\n27. لیکن خداوند نے فرعون کے دل کو سخت کر دیا، اور وہ انہیں جانے نہیں دیا۔\n28۔ اور فرعون نے اس سے کہا، مجھ سے دور ہو جاؤ، اپنا خیال رکھو، میرا چہرہ دوبارہ نہ دیکھو؛ کیونکہ اسی دن تم میرا چہرہ دیکھو گے تو مر جاؤ گے۔\n29۔ اور موسیٰ نے کہا، تو نے اچھی بات کی ہے، میں تمہارا چہرہ دوبارہ نہیں دیکھوں گا۔","1۔ اور خداوند نے موسیٰ سے کہا، پھر بھی میں فرعون اور مصر پر ایک اور وبا لاؤں گا؛ بعد میں وہ تمہیں جانے دے گا: جب وہ تمہیں چھوڑے گا، تو وہ تمہیں مکمل طور پر یہاں سے نکال دے گا۔\n2۔ اب لوگوں کے کانوں میں بات کرو، اور ہر مرد اپنے پڑوسی اور اس کی پڑوسی کی ہر عورت سے چاندی کے زیورات اور سونے کے جواہرات ادھار لے لے۔\n3۔ اور خداوند نے لوگوں کو مصریوں کی نظر میں عنایت دی۔ مزید برآں، موسیٰ مصر کی سرزمین میں، فرعون کے خادموں کی نظر میں، اور لوگوں کی نظر میں بہت عظیم تھا۔\n4۔ اور موسیٰ نے کہا، خداوند نے یوں فرمایا، تقریبا آدھی رات کو میں مصر کے بیچ میں جاؤں گا:\n5۔ اور مصر کی سرزمین میں سب سے بڑا بچہ مر جائے گا، فرعون کے پہلے بیٹے سے لے کر جو اس کے تخت پر بیٹھا ہے، یہاں تک کہ اس کنواری کے پہلے بچے تک جو چکی کے پیچھے ہے؛ اور تمام جانوروں کے پہلے بیٹے۔\n6۔ اور پورے مصر کی سرزمین میں ایک بڑا نعرہ ہوگا، جیسا کہ اس جیسا کوئی نہیں تھا، اور نہ ہی ہوگا۔\n7۔ لیکن بنی اسرائیل میں سے کسی کے خلاف کوئی کتا اپنی زبان نہیں ہلائے گا، نہ انسان کے خلاف نہ جانور کے خلاف، تاکہ تم جان سکو کہ خداوند مصریوں اور اسرائیل کے درمیان فرق کرتا ہے۔\n8۔ اور یہ سب تمہارے خادم میرے پاس آئیں گے، اور میرے سامنے سجدہ کریں گے اور کہیں گے، نکل جاؤ، اور تمہارے ساتھ چلنے والے سب لوگ، اور اس کے بعد میں نکل جاؤں گا۔ اور وہ غصے میں فرعون سے باہر نکلا۔ {جو اس کے بعد ہے...: عبرانی۔ جو تمہارے قدموں میں ہے} {ایک عظیم...: عبرانی غصے کی گرمی}\n9۔ اور خداوند نے موسیٰ سے کہا، فرعون تمہاری بات نہیں سنے گا؛ تاکہ میرے عجائبات مصر کی سرزمین میں کئی گنا بڑھ جائیں۔\n10۔ اور موسیٰ اور ہارون نے یہ سب عجائبات فرعون کے سامنے کیے: اور خداوند نے فرعون کے دل کو سخت کر دیا، تاکہ وہ بنی اسرائیل کو اپنی سرزمین سے باہر نہ جانے دے۔","1۔ اور خداوند نے مصر کی سرزمین میں موسیٰ اور ہارون سے کہا،\n2. یہ مہینہ آپ کے لیے مہینوں کا آغاز ہوگا: یہ آپ کے لیے سال کا پہلا مہینہ ہوگا۔\n3۔ تم سب اسرائیل کی جماعت سے بات کرو، کہو، اس مہینے کی دسویں {دن} کو وہ ہر آدمی کے لیے ایک بکرا لے کر جائیں گے، جیسا کہ ان کے باپ کے گھر کے مطابق، ایک بکرا گھر کے لیے: {بھیڑ: یا، بچہ}\n4۔ اور اگر گھر کا بچہ بکری کے لیے چھوٹا ہو تو وہ اور اس کا پڑوسی جو اس کے گھر کے پاس ہے، جانوں کی تعداد کے مطابق لے لیں؛ ہر آدمی اپنی خوراک کے مطابق بھیڑ کے لیے گنتی کرے گا۔\n5۔ تمہارا برہ بغیر کسی داغ کے، پہلا سال کا نر ہوگا: تم بھیڑ یا بکریوں سے نکالو گے: {of...: عبرانی۔ سال کا بیٹا}\n6۔ اور تم اسے اسی مہینے کی چودہویں تاریخ تک جاری رکھو گے: اور اسرائیل کی جماعت کی پوری جماعت شام کو اسے ختم کر دے گی۔ {میں...: عبرانی دونوں شاموں کے درمیان}\n7۔ اور وہ خون سے لیں گے، اور گھروں کے دو اطراف کے ستونوں اور اوپری دروازے کے ستون پر ماریں گے، جہاں وہ اسے کھائیں گے۔\n8۔ اور وہ اس رات گوشت کھائیں گے، آگ میں بھنے گا، اور بغیر خمیر کے روٹی کے ساتھ بھنا جائے گا؛ {اور}کڑوی جڑی بوٹیوں کے ساتھ وہ اسے کھائیں گے۔\n9۔ اسے کچا نہ کھاؤ، نہ ہی پانی میں بھیگو، بلکہ آگ کے ساتھ بھنا کرو؛ اس کا سر اس کی ٹانگوں کے ساتھ، اور اس کی خوبصورتی کے ساتھ۔\n10۔ اور تم اس میں سے کچھ بھی صبح تک باقی نہ رکھو؛ اور جو کچھ اس میں سے بچا ہے وہ صبح تک تم آگ میں جلو گے۔\n11۔ اور یوں تم اسے کھاؤ گے؛ {تمہاری کمر بندھے ہوئے، جوتے پاؤں میں، اور چھڑی ہاتھ میں؛ اور تم اسے جلدی میں کھاؤ گے: یہ خداوند کا عید فسح ہے۔\n12۔ کیونکہ میں آج رات مصر کی سرزمین سے گزروں گا، اور مصر کی سرزمین کے تمام پہلوے، انسان اور جانور دونوں کو شکست دوں گا؛ اور مصر کے تمام دیوتاؤں کے خلاف میں فیصلہ کروں گا: میں خداوند ہوں۔ {دیوتا: یا، شہزادے}\n13۔ اور خون تمہارے لیے ہوگا ان گھروں پر نشان کے طور پر جہاں تم ہو: اور جب میں خون دیکھوں گا، میں تم پر سے گزر جاؤں گا، اور جب میں مصر کی سرزمین کو تباہ کروں گا تو طاعون تم پر نہیں آئے گا کہ تمہیں تباہ کر دوں۔ {تباہ کرنے کے لیے...: عبرانی۔ تباہی کے لیے}\n14۔ اور آج کا دن آپ کے لیے یادگار ہوگا؛ اور تم اسے اپنی نسلوں تک خداوند کے لیے دعوت کے طور پر مناؤ گے؛ تم اسے ہمیشہ کے لیے ایک آرڈیننس کے ذریعے دعوت کے طور پر رکھو گے۔\n15۔ سات دن تم بغیر خمیر کی روٹی کھاؤ گے؛ پہلے دن بھی تم اپنے گھروں سے خمیر نکالو گے: کیونکہ جو بھی پہلے دن سے ساتویں دن تک خمیر شدہ روٹی کھائے گا، وہ روح اسرائیل سے کٹ جائے گی۔\n16۔ اور پہلے دن ایک مقدس اجلاس ہوگا، اور ساتویں دن آپ کے لیے مقدس اجلاس ہوگا؛ ان میں کوئی کام نہیں کیا جائے گا، سوائے اس کے جو ہر انسان کو کھانا چاہیے، جو صرف آپ کے لیے کیا جا سکتا ہے۔ {آدمی: عبرانی۔ روح}\n17. اور تم بغیر خمیر کی روٹی کی عید مناؤ گے؛ کیونکہ اسی دن میں نے تمہاری فوجیں مصر کی سرزمین سے نکالی ہیں: اس لیے تم اپنی نسلوں میں یہ دن ہمیشہ کے لیے ایک حکم کے ذریعے مناؤ گے۔\n18۔ پہلے مہینے میں، مہینے کی چودہویں تاریخ کو ایون پر، آپ بغیر خمیر کی روٹی کھائیں گے، یہاں تک کہ مہینے کے ایک اور بیس دن کو ایون۔\n19۔ سات دن تک تمہارے گھروں میں خمیر نہیں ملے گا: کیونکہ جو بھی خمیر کھاتا ہے، وہ بھی اسرائیل کی جماعت سے کٹ جائے گا، چاہے وہ اجنبی ہو یا زمین میں پیدا ہوا ہو۔\n20۔ تم خمیر شدہ کچھ نہیں کھاؤ گے؛ تم اپنی تمام رہائش گاہوں میں بغیر خمیر کی روٹی کھاؤ گے۔\n21۔ پھر موسیٰ نے اسرائیل کے تمام بزرگوں کو بلایا اور کہا، اپنے خاندانوں کے مطابق ایک برہ نکالو اور لو، اور فسح کو قتل کرو۔ {لیمب: یا، بچے}\n22۔ اور تم ایک گچھا ہیسوپ لے کر اسے اس خون میں ڈبو دو جو بیسن میں ہے، اور لینٹل اور دونوں اطراف کے ستونوں کو اس خون سے مارو جو بیسن میں ہے؛ اور تم میں سے کوئی بھی صبح تک اس کے گھر کے دروازے پر نہیں جائے گا۔\n23. کیونکہ خداوند مصریوں کو سزا دینے کے لیے گزرے گا؛ اور جب وہ لینٹل اور دونوں طرف کے ستونوں پر خون دیکھے گا، تو خداوند دروازے کے اوپر سے گزرے گا، اور تباہ کرنے والے کو تمہارے گھروں میں آ کر تمہیں مارنے نہیں دے گا۔\n24۔ اور تم اس عمل کی پابندی کرو گے، جو تمہارے اور تمہارے بیٹوں کے لیے ہمیشہ کے لیے ہے۔\n25۔ اور جب تم اس زمین پر آؤ گے جسے خداوند تمہیں دے گا، جیسا کہ اس نے وعدہ کیا ہے، تو تم یہ خدمت نبھاؤ گے۔\n26. اور یہ تب ہوگا جب تمہارے بچے تم سے کہیں گے، تم اس خدمت سے کیا مراد لیتے ہو؟\n27۔ کہ تم کہو گے، یہ خداوند کے پاس کی قربانی ہے، جو مصر میں بنی اسرائیل کے گھروں کے اوپر سے گزرا، جب اس نے مصریوں کو مارا اور ہمارے گھروں کو نجات دی۔ اور لوگ سر جھکا کر عبادت کرتے تھے۔\n28۔ اور بنی اسرائیل چلے گئے، اور وہی کیا جو خداوند نے موسیٰ اور ہارون کو حکم دیا تھا، انہوں نے بھی۔\n29۔ اور ایسا ہوا کہ آدھی رات کو خداوند نے مصر کی سرزمین کے تمام پہلے بچوں کو مار ڈالا، فرعون کے پہلے بچے سے لے کر قیدی کے پہلے بچے تک جو قید خانے میں تھا؛ اور تمام مویشیوں کے پہلے بچے۔ {تہہ خانہ: عبرانی۔ ہاؤس آف دی پٹ}\n30۔ اور فرعون رات کو اٹھا، وہ، اس کے تمام خادم، اور تمام مصری؛ اور مصر میں ایک بڑی پکار ہوئی؛ کیونکہ {وہاں کوئی گھر نہیں تھا} جہاں {کہاں} ایک بھی مردہ نہ ہو۔\n31۔ اور اس نے رات کو موسیٰ اور ہارون کو بلایا اور کہا، اٹھو، {اور} اپنے آپ کو میری قوم سے نکالو، تم اور بنی اسرائیل دونوں؛ اور جاؤ، خداوند کی خدمت کرو، جیسا کہ تم نے کہا ہے۔\n32۔ اپنے ریوڑ اور ریوڑ بھی، جیسا کہ آپ نے کہا، لے کر چلے جاؤ؛ اور مجھے بھی برکت دے۔\n33۔ اور مصریوں نے لوگوں پر فوری کارروائی کی کہ انہیں جلدی سے زمین سے نکال دیں؛ کیونکہ انہوں نے کہا، ہم سب مردہ {انسان} ہیں۔\n34۔ اور لوگوں نے اپنا آٹا اس سے پہلے لیا کہ وہ خمیر ہوتا، ان کے گوندھنے والے کپڑوں میں کندھوں پر بندھ دیے جاتے۔ {گوندھنے کی آواز: یا، آٹا}\n35۔ اور بنی اسرائیل نے موسیٰ کے کلام کے مطابق کیا؛ اور انہوں نے مصریوں سے چاندی کے جواہرات، سونے کے جواہرات اور لباس ادھار لیے:\n36۔ اور خداوند نے لوگوں کو مصریوں کی نظر میں عنایت دی، تاکہ انہوں نے انہیں وہ چیزیں دیں جو انہوں نے مانگی۔ اور انہوں نے مصریوں کو بگاڑ دیا۔\n37۔ اور بنی اسرائیل رامسیس سے سکوت تک روانہ ہوئے، تقریبا چھ لاکھ پیدل، جو بچوں کے ساتھ تھے۔\n38۔ اور ایک مخلوط ہجوم بھی ان کے ساتھ اوپر گیا؛ اور ریوڑ، ریوڑ، {حتیٰ کہ} بہت زیادہ مویشی۔ {ایک مخلوط لہجہ...: عبوری۔ زبردست امتزاج}\n39۔ اور انہوں نے اس آٹے کے بغیر خمیر کے کیک بنائے جو انہوں نے مصر سے نکالا تھا، کیونکہ وہ خمیر نہیں تھا؛ کیونکہ انہیں مصر سے نکال دیا گیا تھا اور وہ ٹھہر نہیں سکتے تھے، نہ ہی انہوں نے اپنے لیے کوئی خوراک تیار کی تھی۔\n40۔ اب مصر میں رہنے والے بنی اسرائیل کا قیام چار سو تیس سال تھا۔\n41۔ اور چار سو تیس سال کے آخر میں، حتیٰ کہ اسی دن بھی ایسا ہوا، کہ خداوند کی تمام فوجیں مصر کی سرزمین سے نکل گئیں۔\n42. یہ وہ رات ہے جو خداوند کے لیے بہت زیادہ یاد رکھی جائے گی کیونکہ اس نے انہیں مصر کی سرزمین سے نکالا: یہ وہ رات ہے جو بنی اسرائیل کی تمام نسلوں میں منائی جائے گی۔ {ایک رات...: عبرانی۔ مشاہدات کی ایک رات}\n43۔ اور خداوند نے موسیٰ اور ہارون سے کہا، یہ فسح کا حکم ہے: کوئی اجنبی اس میں سے نہیں کھائے گا:\n44۔ لیکن ہر آدمی کا خادم جو پیسے کے بدلے خریدا جاتا ہے، جب تم نے اسے ختنہ کر لیا ہے، تو وہ اس میں سے کھائے گا۔\n45۔ غیر ملکی اور کرائے کا خادم اس میں سے نہیں کھائیں گے۔\n46۔ ایک گھر میں کھایا جائے گا؛ تم گوشت کو گھر سے باہر نہیں لے جاؤ گے؛ نہ ہی تم اس کی ہڈی توڑو گے۔\n47۔ اسرائیل کی تمام جماعت اسے برقرار رکھے گی۔ {برقرار رکھو...: عبوری۔ کرو}\n48۔ اور جب کوئی اجنبی تمہارے ساتھ ٹھہرے اور خداوند کے پاس فسح منائے، تو اس کے تمام مردوں کا ختنہ ہو جائے، پھر وہ قریب آ کر ختنہ کرے؛ اور وہ زمین میں پیدا ہونے والے کی طرح ہوگا: کیونکہ کوئی غیر ختنہ شدہ شخص اس میں سے نہیں کھائے گا۔\n49۔ ایک قانون اس کے لیے ہوگا جو گھر پر پیدا ہوا ہے، اور اس اجنبی کے لیے جو آپ کے درمیان رہتا ہے۔\n50۔ اسی طرح تمام بنی اسرائیل نے کیا؛ جیسے خداوند نے موسیٰ اور ہارون کو حکم دیا، ویسے ہی انہوں نے بھی۔\n51۔ اور اسی دن ہوا، {کہ} خداوند نے بنی اسرائیل کو ان کی فوجوں کے ذریعے مصر کی سرزمین سے نکالا۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2. میرے لیے تمام پہلے بچوں، جو کچھ بھی بنی اسرائیل کے رحم کو کھولتا ہے، {انسانوں اور جانوروں کے} کے لیے مقدس فرما: وہ {میرا} ہے۔\n3۔ اور موسیٰ نے لوگوں سے کہا، اس دن کو یاد کرو جب تم مصر سے غلامی کے گھر سے باہر آئے؛ کیونکہ ہاتھ کی طاقت سے خداوند نے تمہیں اس {جگہ} سے نکالا: یہاں خمیر شدہ روٹی نہیں کھائی جائے گی۔ {بانڈج: عبرانی۔ خادم}\n4۔ یہ دن آپ کے مہینے ابیب میں آیا۔\n5۔ اور جب خداوند تمہیں کنعانیوں، حتیوں، اموریوں، حویوں، اور یبوسائیوں کی سرزمین میں لے جائے گا، جسے اس نے تمہارے آباؤ اجداد سے قسم کھائی ہے کہ وہ تمہیں دودھ اور شہد سے بہتی ہوئی زمین دے گا، تو تم اس مہینے میں یہ خدمت انجام دو گے۔\n6۔ سات دن تم بغیر خمیر کی روٹی کھاؤ گے، اور ساتویں دن خداوند کے لیے دعوت ہوگی۔\n7۔ بغیر خمیر کی روٹی سات دن کھائی جائے گی؛ اور تمہارے ساتھ کوئی خمیر روٹی نظر نہیں آئے گی، نہ ہی تمہارے ہر حصے میں خمیر نظر آئے گا۔\n8۔ اور تم اس دن اپنے بیٹے کو دکھاؤ گے، کہہ دو، {یہ ہو گیا} اس {جو} خداوند نے میرے ساتھ کیا جب میں مصر سے باہر آیا۔\n9۔ اور یہ تمہارے لیے تمہارے ہاتھ پر ایک نشانی ہوگی، اور تمہاری آنکھوں کے درمیان ایک یادگار کے لیے، تاکہ خداوند کا قانون تمہارے منہ میں ہو: کیونکہ خداوند نے ایک مضبوط ہاتھ سے تمہیں مصر سے نکالا ہے۔\n10۔ لہٰذا اس فرمان کو سال بہ سال اس کے موسم میں رکھنا۔\n11۔ اور جب خداوند تمہیں کنعانیوں کی سرزمین میں لے آئے گا، جیسا کہ اس نے تم سے اور تمہارے باپ اجداد سے قسم کھائی ہے، اور تمہیں دے گا،\n12۔ کہ تم خداوند کے سامنے وہ سب کچھ رکھ دو جو میٹرکس کھولتا ہے، اور ہر وہ فرسٹ جو اس جانور سے آتا ہے جو تمہارے پاس ہے؛ مرد خدا کے ہوں گے۔ {سیٹ...: عبوری۔ وجہ کہ گزر جائے}\n13۔ اور ہر گدھے کے پہلے بچے کو تم ایک بکری سے نجات دو گے؛ اور اگر تم اسے نجات نہیں دینا چاہتے، تو تم اس کی گردن توڑ دو گے: اور تمہارے بچوں میں سے تمام پہلے والے انسان کو تم نجات دو گے۔ {لیمب: یا، بچے}\n14۔ اور جب تمہارا بیٹا تم سے پوچھے گا کہ یہ کیا ہے؟ جو تم اسے کہو گے، خداوند نے ہاتھ کی طاقت سے ہمیں مصر سے، غلامی کے گھر سے نکالا: {میں...: عبرانی۔ مورو کے لیے}\n15۔ اور ایسا ہوا، جب فرعون ہمیں جانے نہیں دے رہا تھا، کہ خداوند نے مصر کی سرزمین کے تمام پہلونے کو مار ڈالا، چاہے وہ انسان کے پہلوبڑے ہوں یا جانور کے پہلوے: اس لیے میں خداوند کے لیے وہ سب قربان کرتا ہوں جو اس کے دروازے کو کھولتا ہے، جو مرد ہیں؛ لیکن اپنے تمام بچوں کے پہلے بچے کو میں نجات دیتا ہوں۔\n16۔ اور یہ تمہارے ہاتھ پر ایک نشان اور تمہاری آنکھوں کے درمیان نشان کے لیے ہوگا، کیونکہ خداوند نے ہاتھ کی طاقت سے ہمیں مصر سے نکالا۔\n17۔ اور جب فرعون نے لوگوں کو جانے دیا، تو خدا نے انہیں فلسطینیوں کی سرزمین کے راستے پر نہ لے جایا، حالانکہ وہ قریب تھا؛ کیونکہ خدا نے فرمایا، تاکہ لوگ جنگ دیکھ کر توبہ نہ کریں اور مصر واپس جائیں:\n18۔ لیکن خدا نے لوگوں کو بحر احمر کے بیابان کے راستے سے رہنمائی کی: اور بنی اسرائیل مصر کی سرزمین سے ہارس لے کر اوپر گئے۔ {ہارنسڈ: یا، ایک قطار میں پانچ کے ذریعے}\n19۔ اور موسیٰ نے یوسف کی ہڈیاں اپنے ساتھ لے گئیں، کیونکہ اس نے بنی اسرائیل سے سختی سے قسم کھائی تھی، کہا تھا، خدا تم سے ضرور آئے گا؛ اور تم میری ہڈیاں اپنے ساتھ لے جاؤ گے۔\n20۔ اور وہ سکوتھ سے روانہ ہوئے اور ایتھم میں، جنگل کے کنارے پر خیمہ زن ہوئے۔\n21۔ اور خداوند دن کے وقت بادل کے ستون میں ان کے سامنے گیا، تاکہ انہیں راستہ دکھائے؛ اور رات کو آگ کے ستون میں، انہیں روشنی دینے کے لیے؛ دن اور رات کے حساب سے:\n22۔ اس نے دن میں بادل کا ستون نہیں ہٹایا، نہ رات کو آگ کا ستون، {سے} لوگوں کے سامنے۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ بنی اسرائیل سے کہو کہ وہ مڑ کر پیہاہیروت کے سامنے، میگدول اور سمندر کے درمیان، بعلزیفون کے خلاف خیمہ زن بناؤ: اس سے پہلے کہ تم سمندر کے کنارے خیمہ زن ہو۔\n3۔ کیونکہ فرعون بنی اسرائیل کے بارے میں کہے گا، وہ زمین میں الجھے ہوئے ہیں، بیابان نے انہیں بند کر دیا ہے۔\n4۔ اور میں فرعون کا دل سخت کروں گا تاکہ وہ ان کے پیچھے چلے؛ اور میں فرعون اور اس کے تمام لشکر کی عزت کروں گا؛ تاکہ مصری جان سکیں کہ میں خداوند ہوں۔ اور انہوں نے ایسا ہی کیا۔\n5۔ اور مصر کے بادشاہ کو بتایا گیا کہ لوگ بھاگ گئے: اور فرعون اور اس کے خادموں کا دل لوگوں کے خلاف ہو گیا، اور انہوں نے کہا، ہم نے یہ کیوں کیا، کہ ہم نے اسرائیل کو اپنی خدمت سے آزاد کر دیا؟\n6۔ اور اس نے اپنی رتھ تیار کی، اور اپنے لوگوں کو ساتھ لے گیا:\n7۔ اور اس نے چھ سو منتخب رتھیں، اور مصر کے تمام رتھ اور ہر ایک کے کپتان لے لیے۔\n8۔ اور خداوند نے مصر کے بادشاہ فرعون کے دل کو سخت کیا، اور وہ بنی اسرائیل کے پیچھے دوڑا، اور بنی اسرائیل نے زور سے باہر نکل گئے۔\n9۔ لیکن مصریوں نے ان کا پیچھا کیا، فرعون کے تمام گھوڑے اور رتھیں، اس کے سواروں اور اس کی فوج، اور سمندر کے کنارے، پیہاہیروت کے پاس، بعلزیفون کے سامنے خیمہ زن انہیں پکڑ لیا۔\n10۔ اور جب فرعون قریب پہنچا، بنی اسرائیل نے اپنی آنکھیں اٹھائیں، اور دیکھتے ہی مصری ان کے پیچھے دوڑے؛ اور وہ شدید خوفزدہ تھے: اور بنی اسرائیل نے خداوند سے پکارا۔\n11۔ اور انہوں نے موسیٰ سے کہا، چونکہ مصر میں کوئی قبر نہیں تھی، کیا تم نے ہمیں ویرانے میں مرنے کے لیے لے جایا ہے؟ تو تم نے ہمارے ساتھ ایسا کیوں کیا، ہمیں مصر سے باہر نکالنے کے لیے؟\n12. کیا یہ وہ لفظ نہیں جو ہم نے مصر میں تمہیں بتایا تھا، کہ ہمیں چھوڑ دو تاکہ ہم مصریوں کی خدمت کر سکیں؟ کیونکہ ہمارے لیے مصریوں کی خدمت کرنا بہتر تھا، بجائے اس کے کہ ہم ویرانے میں مر جائیں۔\n13۔ اور موسیٰ نے لوگوں سے کہا، \"ڈرو مت، رک جاؤ، اور خداوند کی نجات دیکھو، جو وہ آج تمہیں دکھائے گا: کیونکہ وہ مصریوں جنہیں تم نے آج دیکھا ہے، تم انہیں ہمیشہ کے لیے دوبارہ نہیں دیکھو گے۔ {اس کے لیے...: یا، کیونکہ تم نے آج مصریوں کو دیکھا ہے}\n14۔ خداوند تمہارے لیے لڑے گا، اور تم خاموش رہو گے۔\n15۔ اور خداوند نے موسیٰ سے کہا، تم مجھ سے کیوں پکار رہے ہو؟ بنی اسرائیل سے کہو کہ وہ آگے بڑھیں:\n16۔ لیکن اپنی چھڑی اٹھاؤ، اور اپنا ہاتھ سمندر پر پھیلاؤ، اور اسے تقسیم کرو: اور بنی اسرائیل سمندر کے بیچ خشک زمین پر جائیں گے۔\n17۔ اور میں، دیکھو، مصریوں کے دلوں کو سخت کروں گا، اور وہ ان کی پیروی کریں گے: اور میں فرعون، اس کے تمام لشکروں، اس کے رتھوں اور اس کے سواروں پر عزت حاصل کروں گا۔\n18۔ اور مصری جان جائیں گے کہ میں خداوند ہوں، جب میں فرعون، اس کے رتھوں اور اس کے سواروں پر عزت حاصل کروں گا۔\n19۔ اور خدا کا فرشتہ، جو اسرائیل کے کیمپ کے سامنے گیا، ہٹا کر ان کے پیچھے چلا گیا؛ اور بادل کا ستون ان کے چہرے کے سامنے سے چلا گیا، اور ان کے پیچھے کھڑا ہو گیا:\n20۔ اور یہ مصریوں کے قافلے اور اسرائیل کے کیمپ کے درمیان آ گیا؛ اور یہ ان کے لیے ایک بادل اور تاریکی تھی، لیکن رات کو روشنی دیتی تھی {ان کو} تاکہ ایک دوسرے کے قریب نہ آ سکے ساری رات۔\n21۔ اور موسیٰ نے اپنا ہاتھ سمندر پر بڑھایا؛ اور خداوند نے اس رات ایک تیز مشرقی ہوا سے سمندر کو واپس دھکیل دیا، اور سمندر کو خشک کر دیا، اور پانی تقسیم ہو گئے۔\n22۔ اور بنی اسرائیل سمندر کے بیچ خشک زمین پر چلے گئے: اور پانی ان کے دائیں اور بائیں طرف دیوار بن گیا۔\n23۔ اور مصریوں نے ان کا پیچھا کیا اور ان کے پیچھے سمندر کے بیچ تک پہنچے، {حتیٰ کہ} فرعون کے تمام گھوڑے، اس کے رتھ اور اس کے سواروں کو بھی۔\n24۔ اور ایسا ہوا کہ صبح کے وقت خداوند نے آگ اور بادل کے ستون کے ذریعے مصریوں کے لشکر کو دیکھا، اور مصریوں کے لشکر کو پریشان کیا،\n25۔ اور انہوں نے اپنے رتھ کے پہیے اتار دیے، انہیں بھاری دھکیلنے لگے: یہاں تک کہ مصریوں نے کہا، آؤ اسرائیل کے چہرے سے بھاگ جائیں؛ کیونکہ خداوند ان کے لیے مصریوں کے خلاف لڑتا ہے۔ {کہ وہ...: یا، اور انہیں بھاری کر دیا}\n26۔ اور خداوند نے موسیٰ سے کہا، اپنا ہاتھ سمندر پر پھیلاؤ، تاکہ پانی مصریوں پر، ان کے رتھوں اور ان کے سواروں پر دوبارہ آ جائے۔\n27۔ اور موسیٰ نے اپنا ہاتھ سمندر پر بڑھایا، اور جب صبح ہوئی تو سمندر اس کی طاقت میں واپس آ گیا؛ اور مصری اس کے خلاف بھاگ گئے؛ اور خداوند نے سمندر کے بیچ میں مصریوں کو گرا دیا۔ {الٹا: عبرانی۔ جھٹک دیا}\n28۔ اور پانی واپس آیا، اور رتھوں اور گھڑ سواروں کو، اور فرعون کے تمام لشکر کو ڈھانپ لیا جو ان کے بعد سمندر میں آیا؛ ان میں سے ایک بھی باقی نہیں رہا۔\n29۔ لیکن بنی اسرائیل سمندر کے بیچ خشک زمین پر چلتے رہے؛ اور پانی ان کے دائیں اور بائیں طرف ایک دیوار تھا۔\n30۔ یوں خداوند نے اس دن اسرائیل کو مصریوں کے ہاتھوں سے بچایا؛ اور اسرائیل نے مصریوں کو سمندر کے کنارے مردہ دیکھا۔\n31۔ اور اسرائیل نے وہ عظیم کام دیکھا جو خداوند نے مصریوں پر کیا: اور لوگ خدا سے ڈرے، اور خداوند اور اس کے بندے موسیٰ پر ایمان لائیں۔ {کام: عبرانی۔ ہاتھ}","1۔ پھر موسیٰ اور بنی اسرائیل نے خداوند کے لیے یہ گیت گایا اور کہا، میں خداوند کو گاؤں گا، کیونکہ اس نے جلال سے فتح حاصل کی ہے: گھوڑا اور اس کے سوار کو سمندر میں پھینک دیا گیا۔\n2. خداوند میری طاقت اور گیت ہے، اور وہ میری نجات بن چکا ہے: وہ میرا خدا ہے، اور میں اس کے لیے رہائش گاہ تیار کروں گا؛ میرے والد کا خدا، اور میں اسے بلند کروں گا۔\n3. خداوند {ہے} جنگ کا آدمی: خداوند {ہے} اس کا نام۔\n4۔ فرعون کی رتھ اور اس کی فوج نے سمندر میں پھینک دی: اس کے منتخب کپتان بھی بحیرہ احمر میں ڈوب گئے۔\n5۔ گہرائیوں نے انہیں ڈھانپ لیا ہے: وہ پتھر کی طرح نیچے جا رہے ہیں۔\n6۔ اے خداوند، تیرا دایاں ہاتھ، طاقتور ہو گیا ہے: اے خداوند، تیرا دایاں ہاتھ، دشمن کو ٹکڑوں میں توڑ چکا ہے۔\n7۔ اور اپنی عظمت میں تم نے ان لوگوں کو شکست دی جو تمہارے خلاف اٹھے: تم نے اپنا غصہ نکالا، {جس نے} انہیں داڑھی کی طرح کھا لیا۔\n8۔ اور تیرے نتھنوں کے دھماکے کے ساتھ پانی اکٹھا ہو گیا، سیلاب ایک ڈھیر کی طرح کھڑا ہو گیا، {اور} گہرائیاں سمندر کے دل میں جم گئیں۔\n9۔ دشمن نے کہا، میں پیچھا کروں گا، میں پکڑوں گا، میں مال تقسیم کروں گا؛ میری ہوس ان پر پوری ہو جائے گی؛ میں اپنی تلوار نکالوں گا، میرا ہاتھ انہیں تباہ کر دے گا۔ {تباہ کرو: یا، قبضہ کرو}\n10۔ تو نے اپنی ہوا سے چلائی، سمندر نے انہیں ڈھانپ لیا: وہ طاقتور پانیوں میں سیسہ کی طرح ڈوب گئے۔\n11. اے خداوند، دیوتاؤں میں تیرے جیسا کون ہے؟ کون ہے جو آپ جیسا ہے، پاکیزگی میں جلال، خوفزدہ تعریفوں میں، معجزے کرنے والا؟ {خدا: یا، طاقتور والے؟}\n12۔ تو نے اپنا دایاں ہاتھ بڑھایا، زمین نے انہیں نگل لیا۔\n13۔ تم نے اپنی رحمت میں ان لوگوں کی رہنمائی کی جنہیں تم نے نجات دی: تم نے اپنی طاقت میں انہیں اپنے مقدس گھر کی طرف رہنمائی کی۔\n14۔ لوگ سنیں گے، {اور} ڈریں گے: فلسطین کے باشندوں پر غم چھا جائے گا۔\n15۔ پھر ایڈوم کے ڈیوک حیران رہ جائیں گے؛ موآب کے طاقتور لوگ، کانپتے ہوئے، ان پر قبضہ کر لیں گے؛ کنعان کے تمام باشندے پگھل جائیں گے۔\n16۔ ان پر خوف اور خوف چھا جائے گا؛ تمہارے بازو کی عظمت سے وہ پتھر کی طرح ساکت ہوں گے؛ جب تک تیرے لوگ رخصت نہ ہو جائیں، اے خداوند، جب تک لوگ گزر نہ جائیں، {جو} تو نے خریدے ہیں۔\n17. تو انہیں اپنے وراثت کے پہاڑ میں لاؤ گے، {اے، اے خداوند، {یکی} جہاں تم نے اپنے لیے رہائش کے لیے بنایا ہے، {یہاں} مقدس مقام میں، اے خداوند، {جو تمہارے ہاتھوں نے قائم کی ہے}۔\n18۔ خداوند ہمیشہ ہمیشہ کے لیے حکمرانی کرے گا۔\n19۔ کیونکہ فرعون کا گھوڑا اپنے رتھ اور اپنے سواروں کے ساتھ سمندر میں گیا، اور خداوند نے سمندر کے پانی کو دوبارہ ان پر لایا ہے؛ لیکن بنی اسرائیل سمندر کے بیچ خشکی پر چلے گئے۔\n20۔ اور مریم نبی، ہارون کی بہن، نے اپنے ہاتھ میں ایک ٹمبرل پکڑا؛ اور تمام عورتیں اس کے پیچھے ٹمبرل اور رقص کے ساتھ باہر نکلیں۔\n21۔ اور مریم نے ان کا جواب دیا، خداوند کو گاؤ، کیونکہ اس نے جلال سے فتح حاصل کی ہے؛ گھوڑے اور اس کے سوار کو اس نے سمندر میں پھینک دیا۔\n22۔ تو موسیٰ نے بحیرہ احمر سے اسرائیل کو لایا، اور وہ شور کے بیابان میں نکل گئے؛ اور وہ تین دن جنگل میں گئے، اور پانی نہ پایا۔\n23. اور جب وہ مارا پہنچے تو وہ ماراہ کے پانی سے نہیں پی سکتے تھے، کیونکہ وہ کڑوا تھے، اسی لیے اس کا نام ماراہ رکھا گیا۔ {مارہ: یہ تلخی ہے}\n24۔ اور لوگوں نے موسیٰ کے خلاف سرگوشی کی، کہنے لگے، ہم کیا پئیں؟\n25۔ اور اس نے خداوند سے پکارا؛ اور خداوند نے اسے ایک درخت دکھایا، {جو} جب اس نے پانی میں ڈالا تو پانی میٹھا ہو گیا: وہاں اس نے ان کے لیے ایک قانون اور حکم بنایا، اور وہاں اس نے انہیں ثابت کیا،\n26۔ اور کہا، اگر تم خداوند اپنے خدا کی آواز کو محنت سے سنو، اور جو اس کی نظر میں درست ہے وہ کرو گے، اس کے احکامات سنو گے، اور اس کے تمام قوانین کی پاسداری کرو گے، تو میں تم پر یہ بیماریاں نہیں ڈالوں گا جو میں نے مصریوں پر لائی ہیں: کیونکہ میں وہ خداوند ہوں جو تمہیں شفا دیتا ہے۔\n27۔ اور وہ ایلیم پہنچے، جہاں بارہ پانی کے کنویں اور تیس اور دس کھجور کے درخت تھے، اور وہاں پانی کے کنارے خیمہ زن ہو گئے۔","1۔ اور وہ ایلیم سے روانہ ہوئے، اور بنی اسرائیل کی تمام جماعت دوسرے مہینے کے پندرہویں دن مصر کی سرزمین سے روانہ ہونے کے بعد سین کے بیابان میں آ گئی، جو ایلیم اور سینا کے درمیان واقع ہے۔\n2۔ اور بنی اسرائیل کی پوری جماعت موسیٰ اور ہارون کے خلاف ویرانے میں سرگوشی کرنے لگی:\n3۔ اور بنی اسرائیل نے ان سے کہا، کاش ہم خدا کے ہاتھوں مصر کی سرزمین میں مرتے، جب ہم گوشت کے برتنوں کے پاس بیٹھے تھے، {اور} جب ہم نے بھرپور روٹی کھائی؛ کیونکہ تم نے ہمیں اس ویرانے میں نکالا ہے، تاکہ اس پورے مجمع کو بھوک سے مار ڈال سکو۔\n4۔ پھر خداوند نے موسیٰ سے کہا، دیکھو، میں تمہارے لیے آسمان سے روٹی برساؤں گا؛ اور لوگ روزانہ ایک مخصوص رقم جمع کریں گے، تاکہ میں انہیں ثابت کر سکوں، چاہے وہ میرے قانون کے مطابق چلیں یا نہیں۔ {ایک خاص...: عبرانی۔ اپنے دن کے ایک حصے کے لیے}\n5۔ اور یہ ہوگا کہ چھٹے دن وہ تیار کریں گے جو وہ لائیں گے؛ اور یہ ان کی روزانہ جمع ہونے والی رقم سے دوگنا ہوگا۔\n6۔ اور موسیٰ اور ہارون نے تمام بنی اسرائیل سے کہا، پھر تم جان لو گے کہ خداوند نے تمہیں مصر کی سرزمین سے نکالا ہے:\n7۔ اور صبح کے وقت، پھر تم خداوند کی شان دیکھو گے؛ کیونکہ وہ تمہاری سرگوشیاں سن رہا ہے جو خداوند کے خلاف ہیں: اور ہم کیا ہیں جو تم ہمارے خلاف سرگوشیاں کرتے ہو؟\n8۔ اور موسیٰ نے کہا، {یہ} ہوگا، جب خداوند تمہیں شام میں گوشت اور صبح کو بھرپور روٹی دے گا؛ کیونکہ خداوند تمہاری سرگوشیاں سنتا ہے جو تم اس کے خلاف سرگوشی کرتے ہو: اور ہم کیا ہیں؟ تمہاری سرگوشیاں ہمارے خلاف نہیں، بلکہ خداوند کے خلاف ہیں۔\n9۔ اور موسیٰ نے ہارون سے کہا، بنی اسرائیل کی تمام جماعت سے کہو، خداوند کے قریب آؤ، کیونکہ اس نے تمہاری سرگوشیاں سن لی ہیں۔\n10۔ اور ایسا ہوا، جیسا کہ ہارون نے بنی اسرائیل کی پوری جماعت سے کہا، کہ انہوں نے بیابان کی طرف دیکھا، اور دیکھتے ہی خداوند کی شان بادلوں میں ظاہر ہوئی۔\n11۔ اور خداوند نے موسیٰ سے کہا،\n12۔ میں نے بنی اسرائیل کی سرگوشیاں سنی ہیں: ان سے بات کرو، کہو، تم بھی گوشت کھاؤ گے، اور صبح تم روٹی سے بھر جاؤ گے؛ اور تم جان لو گے کہ میں تمہارا خداوند خدا ہوں۔\n13۔ اور ایسا ہوا کہ یہاں تک کہ بٹیر بھی اوپر آ گئے اور کیمپ کو ڈھانپ لیا: اور صبح شبنم لشکر کے ارد گرد پھیل گئی۔\n14۔ اور جب شبنم اوپر چلی گئی، دیکھو، بیابان کے چہرے پر ایک چھوٹا گول چیز پڑا تھا، {جتنی چھوٹی} زمین پر پڑی برف کی سردی۔\n15۔ اور جب بنی اسرائیل نے اسے دیکھا، تو انہوں نے ایک دوسرے سے کہا، یہ {ہے} منٰ، کیونکہ وہ نہیں جانتے کہ یہ کیا تھا۔ اور موسیٰ نے ان سے کہا، یہ وہ روٹی ہے جو خداوند نے تمہیں کھانے کے لیے دی ہے۔ {یہ ہے...: یا، یہ کیا ہے؟ یا، یہ ایک حصہ ہے}\n16. یہ وہ چیز ہے جس کا خداوند نے حکم دیا ہے، ہر انسان کو اس کے کھانے کے مطابق جمع کرو، ہر انسان کے لیے ایک اومر، تمہارے جانوں کی تعداد کے مطابق؛ تم ہر آدمی کو ان کے لیے سمجھو جو اس کے خیموں میں ہیں۔ {ہر کے لیے...: عبرانی۔ پول کے ذریعے، یا، سربراہ} {افراد: عبرانی۔ روحیں}\n17۔ اور بنی اسرائیل نے ایسا کیا، اور کچھ زیادہ اور کچھ کم جمع کیے۔\n18۔ اور جب انہوں نے اومر سے ملاقات کی، تو جو زیادہ جمع کرتا تھا اس کے پاس کچھ نہیں ہوتا تھا، اور جو کم جمع کرتا تھا اس میں کوئی کمی نہیں تھی؛ انہوں نے ہر آدمی کو اس کے کھانے کے مطابق جمع کیا۔\n19۔ اور موسیٰ نے کہا، کوئی اسے صبح تک نہ چھوڑے۔\n20۔ اگرچہ انہوں نے موسیٰ کی بات نہیں مانی؛ لیکن ان میں سے کچھ نے اسے صبح تک چھوڑ دیا، اور اس نے کیڑے پیدا کیے، اور بدبو دار تھی: اور موسیٰ ان پر غصہ ہوا۔\n21۔ اور وہ ہر صبح اسے جمع کرتے، ہر آدمی اپنی خوراک کے مطابق: اور جب سورج گرم ہوتا تو وہ پگھل جاتا۔\n22۔ اور ایسا ہوا، {کہ} چھٹے دن انہوں نے دوگنا روٹی جمع کی، ایک آدمی کے لیے دو عمر: اور جماعت کے تمام حکمران آئے اور موسیٰ کو بتایا۔\n23۔ اور اس نے ان سے کہا، یہ وہی ہے جو خداوند نے فرمایا، کل مقدس سبت کے باقی دن خداوند کے لیے ہے: جو تم آج پکاؤ گے، اور جو تم بھڑکاؤ گے؛ اور جو کچھ بچا ہے وہ تمہارے لیے صبح تک رکھنا ہے۔\n24۔ اور انہوں نے اسے صبح تک رکھا، جیسا کہ موسیٰ نے کہا تھا: اور اس میں بدبو نہیں تھی، نہ ہی کوئی کیڑا تھا۔\n25۔ اور موسیٰ نے کہا، آج یہ کھاؤ؛ کیونکہ آج خداوند کا سبت ہے: آج تم اسے میدان میں نہیں پاؤ گے۔\n26. چھ دن تم اسے جمع کرو گے؛ لیکن ساتویں دن، جو کہ سبت ہے، اس میں کوئی نہیں ہوگا۔\n27۔ اور ایسا ہوا، {کہ} ساتویں دن کچھ لوگ جمع ہونے کے لیے باہر نکلے، اور انہیں کوئی نہ ملا۔\n28۔ اور خداوند نے موسیٰ سے کہا، تم کتنے عرصے تک میرے احکامات اور قوانین پر عمل کرنے سے انکار کرتے ہو؟\n29۔ دیکھو، کیونکہ خداوند نے تمہیں سبت دیا ہے، اسی لیے وہ تمہیں چھٹے دن دو دن کی روٹی دیتا ہے؛ ہر آدمی اپنی جگہ پر قائم رہو، ساتویں دن کوئی شخص اپنی جگہ سے نہ نکلے۔\n30۔ تو لوگوں نے ساتویں دن آرام کیا۔\n31۔ اور اسرائیل کے گھر نے اس کا نام منا رکھا: اور وہ دھنیا کے بیج کی طرح سفید تھا؛ اور اس کا ذائقہ {شہد سے بنے ہوئے ویفرز} کی طرح تھا۔\n32۔ اور موسیٰ نے کہا، یہ وہ چیز ہے جس کا خداوند حکم دیتا ہے، اس میں سے ایک اومر بھر دو تاکہ اپنی نسلوں کے لیے رکھ سکے؛ تاکہ وہ وہ روٹی دیکھ سکیں جس سے میں نے تمہیں بیابان میں کھلایا، جب میں نے تمہیں مصر کی سرزمین سے نکالا۔\n33۔ اور موسیٰ نے ہارون سے کہا، ایک برتن لے لو، اور اس میں ایک اومر منا ڈال کر اسے خداوند کے سامنے رکھ دو، تاکہ تمہاری نسلوں کے لیے رکھا جائے۔\n34۔ جیسا کہ خداوند نے موسیٰ کو حکم دیا، اسی طرح ہارون نے اسے گواہی کے سامنے رکھ دیا، تاکہ اسے رکھا جائے۔\n35۔ اور بنی اسرائیل نے چالیس سال تک منا کھایا، یہاں تک کہ وہ ایک آباد زمین پر پہنچے؛ انہوں نے منا کھایا، یہاں تک کہ وہ کنعان کی سرزمین کی سرحدوں تک پہنچ گئے۔\n36. اب اومر {ہے} ایفا کا دسواں {حصہ}۔","1۔ اور بنی اسرائیل کی تمام جماعت اپنے سفر کے بعد گناہ کے بیابان سے نکلی، خداوند کے حکم کے مطابق، اور رفیدیم میں رفیدم میں رکھا: اور لوگوں کے لیے پینے کے لیے پانی نہیں تھا۔\n2۔ اسی لیے لوگوں نے موسیٰ کو ملامت کی اور کہا، ہمیں پانی دو تاکہ ہم پی سکیں۔ اور موسیٰ نے ان سے کہا، تم میرے ساتھ کیوں ڈانٹتے ہو؟ تم خداوند کو کیوں آزماتے ہو؟\n3۔ اور لوگ وہاں پانی کے پیاسے تھے؛ اور لوگوں نے موسیٰ کے خلاف سرگوشیاں کیں اور کہا، یہ وہ کیوں ہے جو تم نے ہمیں مصر سے نکالا ہے، تاکہ ہمیں، ہمارے بچوں اور ہمارے مویشیوں کو پیاس سے مار ڈالے؟\n4۔ اور موسیٰ نے خداوند سے پکارا، کہا، میں اس قوم کے ساتھ کیا کروں؟ وہ تقریبا مجھے سنگسار کرنے کے لیے تیار ہیں۔\n5۔ اور خداوند نے موسیٰ سے کہا، لوگوں کے سامنے جاؤ اور اپنے ساتھ اسرائیل کے بزرگوں کو لے جا؛ اور اپنی چھڑی، جس سے تم دریا کو مارتے ہو، اپنے ہاتھ میں لے لو، اور چلے جاؤ۔\n6۔ دیکھو، میں تمہارے سامنے ہورب کی چٹان پر کھڑا ہوں گا؛ اور تم اس پتھر کو مارو گے، اور اس سے پانی نکلے گا، تاکہ لوگ پی سکیں۔ اور موسیٰ نے اسرائیل کے بزرگوں کی نظر میں ایسا کیا۔\n7۔ اور اس نے اس جگہ کا نام ماسہ اور میریبہ رکھا، کیونکہ بنی اسرائیل نے ڈانٹ دی، اور اس لیے کہ انہوں نے خداوند کو آزمائش میں ڈالا، یہ کہتے ہوئے، کیا خداوند ہمارے درمیان ہے یا نہیں؟ {مساہ: یعنی، لالچ} {میریبا: یعنی، سرزنش، یا، جھگڑ}\n8۔ پھر عمالیق آیا، اور رفیدیم میں اسرائیل کے ساتھ لڑا۔\n9۔ اور موسیٰ نے یشوع سے کہا، ہمیں سب سے نکال کر اور نکل کر عمالیق سے لڑو: کل میں پہاڑی کی چوٹی پر خدا کی چھڑی ہاتھ میں لیے کھڑا رہوں گا۔ {یشوع: جسے یسوع کہا جاتا ہے}\n10۔ تو یشوع نے جیسا موسیٰ نے کہا ویسا ہی کیا، اور عمالیق سے لڑا: اور موسیٰ، ہارون اور ہور پہاڑی کی چوٹی پر چلے گئے۔\n11۔ اور ایسا ہوا جب موسیٰ نے اپنا ہاتھ اٹھایا، تو اسرائیل غالب آ گیا؛ اور جب اس نے اپنا ہاتھ چھوڑا تو عمالیق غالب آ گیا۔\n12۔ لیکن موسیٰ کے ہاتھ بھاری تھے؛ اور انہوں نے ایک پتھر لیا، اسے اس کے نیچے رکھا، اور وہ اس پر بیٹھ گیا؛ اور ہارون اور ہور اس کے ہاتھ اوپر ہی رہے، ایک طرف اور دوسری طرف؛ اور اس کے ہاتھ سورج غروب ہونے تک مستحکم رہے۔\n13۔ اور یشوع نے عملیق اور اس کے لوگوں کو تلوار کی نوک سے پریشان کر دیا۔\n14۔ اور خداوند نے موسیٰ سے کہا، یہ {کیونکہ } ایک کتاب میں یادگار لکھو، اور یشوع کے کانوں میں اسے دہرا دو، کیونکہ میں مکمل طور پر عملیک کی یاد کو آسمان کے نیچے سے ختم کر دوں گا۔\n15۔ اور موسیٰ نے ایک قربان گاہ بنائی، اور اس کا نام یہوواہنیسی رکھا: {یہوواہنیسی: یعنی خداوند میرا جھنڈ}\n16۔ کیونکہ اس نے کہا، کیونکہ خداوند نے قسم کھائی ہے کہ خداوند نسل در نسل عمالیق سے جنگ کرے گا۔ {کیونکہ...: یا، کیونکہ عمالیق کا ہاتھ خداوند کے تخت کے خلاف ہے، لہٰذا، وغیرہ} {خداوند نے...: عبرانی زبان۔ خداوند کے تخت پر ہاتھ","1۔ جب جیتھرو، جو مدیان کا پادری تھا، موسیٰ کے سسر، نے سنا کہ خدا نے موسیٰ اور اس کے قوم اسرائیل کے لیے کیا کچھ کیا، {اور} کہ خداوند نے اسرائیل کو مصر سے نکالا ہے؛\n2۔ پھر یتھرو، موسیٰ کے سسر، نے زپورا، موسیٰ کی بیوی کو لے لیا، جب اس نے اسے واپس بھیج دیا،\n3۔ اور اس کے دو بیٹے؛ جس میں سے ایک کا نام {تھا} گرشوم؛ کیونکہ اس نے کہا، میں ایک اجنبی زمین میں ایک اجنبی رہا ہوں: {گرشوم: وہ وہاں ایک اجنبی ہے}\n4۔ اور دوسرے {تھا} کا نام الیعزر تھا؛ کیونکہ میرے باپ کے خدا، {اس نے کہا} میرا مددگار تھا، اور مجھے فرعون کی تلوار سے بچایا: {الیعزر: یعنی، میرا خدا مددگار ہے}\n5۔ اور یتھرو، موسیٰ کا سسر، اپنے بیٹوں اور بیوی کے ساتھ موسیٰ کے پاس بیابان میں آیا، جہاں وہ خدا کے پہاڑ پر خیمہ زن رہا:\n6۔ اور اس نے موسیٰ سے کہا، میں تمہارا سسر یتھرو تمہارے پاس آیا ہوں، اور تمہاری بیوی اور اس کے دو بیٹے اس کے ساتھ ہیں۔\n7۔ اور موسیٰ اپنے سسر سے ملنے باہر گیا، سجدہ کیا اور اسے بوسہ دیا؛ اور انہوں نے ایک دوسرے سے اپنی فلاح و بہبود کے بارے میں پوچھا؛ اور وہ خیمے میں آ گئے۔ {ویلفیئر: ہیب۔ امن}\n8۔ اور موسیٰ نے اپنے سسر کو وہ سب کچھ بتایا جو خداوند نے فرعون اور مصریوں کے ساتھ اسرائیل کی خاطر کیا، {اور} ان پر آنے والی تمام مشکلات جو راستے میں آئیں، اور {کیسے} خداوند نے انہیں نجات دی۔ {آؤ...: عبرانی۔ مل گئے}\n9۔ اور یترو نے اس تمام بھلائی پر خوشی منائی جو خداوند نے اسرائیل کے ساتھ کی، جسے اس نے مصریوں کے ہاتھوں سے آزاد کرایا تھا۔\n10۔ اور یٹھرو نے کہا، مبارک ہو خداوند جس نے تمہیں مصریوں کے ہاتھوں اور فرعون کے ہاتھوں سے نجات دی، جس نے لوگوں کو مصریوں کے ہاتھوں سے نجات دی۔\n11۔ اب میں جانتا ہوں کہ خداوند {ہے} تمام دیوتاؤں سے عظیم: کیونکہ جس چیز میں انہوں نے فخر سے کیا {وہ ان سے اوپر تھا}۔\n12۔ اور یتھرو، موسیٰ کے سسر، نے خدا کے لیے سلائی اور قربانی لی: اور ہارون اور اسرائیل کے تمام بزرگ خدا کے سامنے موسیٰ کے سسر کے ساتھ روٹی کھانے آئے۔\n13۔ اور کل ایسا ہوا کہ موسیٰ لوگوں کا فیصلہ کرنے بیٹھا، اور لوگ صبح سے شام تک موسیٰ کے ساتھ کھڑے رہے۔\n14۔ اور جب موسیٰ کے سسر نے دیکھا کہ اس نے لوگوں کے ساتھ کیا کیا، تو اس نے کہا، یہ کیا ہے جو تم لوگوں کے ساتھ کرتے ہو؟ تم اکیلے کیوں بیٹھے ہو، اور سب لوگ صبح سے شام تک تمہارے ساتھ کھڑے رہتے ہیں؟\n15۔ اور موسیٰ نے اپنے سسر سے کہا، کیونکہ لوگ میرے پاس خدا سے پوچھنے آتے ہیں:\n16۔ جب ان کے پاس کوئی معاملہ ہوتا ہے، تو وہ میرے پاس آتے ہیں؛ اور میں ایک اور دوسرے کے درمیان فیصلہ کرتا ہوں، اور میں انہیں خدا کے قوانین اور اس کے قوانین سے آگاہ کرتا ہوں۔ {ایک...: عبرانی۔ ایک آدمی اور اس کا ساتھی}\n17۔ اور موسیٰ کے سسر نے اس سے کہا، جو تم کرتے ہو وہ اچھا نہیں ہے۔\n18۔ تم یقینا تھک جاؤ گے، تم، اور اس قوم کو جو {تمہارے} کے ساتھ ہے: کیونکہ یہ چیز {تمہارے} کے لیے بہت بھاری ہے؛ تم اکیلے اسے انجام نہیں دے سکتے۔ {تم چاہو گے...: عبرانی۔ تم مدھم ہو جاؤ گے}\n19۔ اب میری آواز سنو، میں تمہیں نصیحت دوں گا، اور خدا تمہارے ساتھ ہوگا: لوگوں کے لیے خدا کی طرف رہو، تاکہ تم خدا کے لیے وجوہات لے آؤ:\n20۔ اور تم انہیں احکامات اور قوانین سکھاؤ گے، اور انہیں راستہ دکھاؤ گے جس میں انہیں چلنا ہے، اور وہ کام جو انہیں کرنا ہے۔\n21۔ مزید برآں، تم تمام لوگوں میں سے قابل لوگوں کو فراہم کرو گے، جو خدا سے ڈرتے ہیں، سچے لوگ، جو لالچ سے نفرت کرتے ہیں؛ اور ان پر {ایسا} رکھیں، {جو ہزاروں کے حکمران ہوں}، {اور} سینکڑوں کے حکمران، پچاس کی دہائی کے حکمران، اور دہائیوں کے حکمران بنیں:\n22۔ اور وہ ہر وقت لوگوں کا فیصلہ کریں: اور یہ ہوگا کہ وہ ہر بڑا معاملہ تمہارے پاس لائیں گے، لیکن ہر چھوٹے معاملے کا فیصلہ کریں گے: یوں یہ تمہارے لیے آسان ہوگا، اور وہ تمہارے ساتھ بوجھ اٹھائیں گے۔\n23۔ اگر تم یہ کام کرو، اور خدا تمہیں حکم دے، تو تم برداشت کر سکو گے، اور یہ سب لوگ بھی سکون سے اپنی جگہ واپس جائیں گے۔\n24۔ تو موسیٰ نے اپنے سسر کی آواز سنی اور وہ سب کچھ کیا جو اس نے کہا تھا۔\n25۔ اور موسیٰ نے تمام اسرائیلیوں میں سے قابل مردوں کا انتخاب کیا، اور انہیں لوگوں پر حکمران بنایا، ہزاروں کے حکمران، سینکڑوں کے حکمران، پچاس کی دہائی کے حکمران، اور دس کے حکمران۔\n26۔ اور انہوں نے لوگوں کا ہر وقت فیصلہ کیا: وہ سخت وجوہات جو انہوں نے موسیٰ کے لیے لائے تھے، لیکن ہر چھوٹے معاملے کا وہ خود فیصلہ کرتے تھے۔\n27۔ اور موسیٰ نے اپنے سسر کو جانے دیا؛ اور وہ اپنی ہی زمین میں داخل ہو گیا۔","1۔ تیسرے مہینے میں، جب بنی اسرائیل مصر کی سرزمین سے نکلے، اسی دن وہ سینا کے بیابان میں داخل ہوئے۔\n2۔ کیونکہ وہ ریفیدیم سے روانہ ہو چکے تھے، اور سینا کے صحرا میں آئے تھے، اور بیابان میں پھینک چکے تھے؛ اور وہاں اسرائیل نے پہاڑ کے سامنے کیمپ لگایا۔\n3۔ اور موسیٰ خدا کے پاس گیا، اور خداوند نے اسے پہاڑ سے پکارا اور کہا، \"تو یعقوب کے گھر سے ایسا کہو اور بنی اسرائیل کو بتاؤ؛\n4۔ تم نے دیکھا کہ میں نے مصریوں کے ساتھ کیا کیا، اور {کیسے} میں نے تمہیں عقاب کے پروں پر اٹھایا اور تمہیں اپنے پاس لایا۔\n5۔ اب اگر تم واقعی میری آواز مانو گے، اور میرا عہد نبھاؤ گے، تو تم میرے لیے تمام لوگوں سے بڑھ کر ایک خاص خزانہ بنو گے: کیونکہ ساری زمین {میری} ہے:\n6۔ اور تم میرے لیے پادریوں کی بادشاہت اور مقدس قوم بنو گے۔ یہ وہ الفاظ ہیں جو تم بنی اسرائیل سے کہے گا۔\n7۔ اور موسیٰ آیا اور لوگوں کے بزرگوں کو بلایا، اور ان کے سامنے وہ تمام الفاظ رکھے جو خداوند نے اسے حکم دیے۔\n8۔ اور سب لوگوں نے مل کر جواب دیا اور کہا، خداوند نے جو کچھ کہا ہے وہ ہم کریں گے۔ اور موسیٰ نے لوگوں کے کلام خداوند کو واپس کر دیے۔\n9۔ اور خداوند نے موسیٰ سے کہا، دیکھو، میں تمہارے پاس گھنے بادل میں آیا ہوں، تاکہ لوگ سن سکیں جب میں تم سے بات کروں، اور ہمیشہ کے لیے تم پر ایمان لائیں۔ اور موسیٰ نے لوگوں کے کلام خداوند کو سنائے تھے۔\n10۔ اور خداوند نے موسیٰ سے کہا، لوگوں کے پاس جاؤ، اور انہیں دن اور کل تک پاک رکھ، اور انہیں اپنے کپڑے دھونے دو،\n11۔ اور تیسرے دن کے لیے تیار رہو: تیسرے دن خداوند سب لوگوں کے سامنے کوہ سینا پر اترے گا۔\n12۔ اور تم اردگرد کے لوگوں کے ساتھ حدیں مقرر کرو اور کہو، ہوشیار رہو، {کہاں} پہاڑ پر نہ جاؤ، نہ اس کے کنارے کو چھوؤ، جو بھی پہاڑ کو چھوئے گا اسے ضرور مار دیا جائے گا:\n13۔ کوئی ہاتھ اسے نہیں چھوئے گا، لیکن اسے ضرور سنگسار کیا جائے گا، یا گولی مار دی جائے گی؛ چاہے وہ جانور ہو یا انسان، وہ زندہ نہیں رہے گا: جب ترمپٹ کی آواز بلند ہوگی، وہ پہاڑ پر چڑھیں گے۔ {ٹرمپٹ: اور، کارنیٹ}\n14۔ اور موسیٰ پہاڑ سے لوگوں کے پاس اترا اور لوگوں کو پاک کیا؛ اور انہوں نے اپنے کپڑے دھوئے۔\n15۔ اور اس نے لوگوں سے کہا، تیسرے دن کے لیے تیار رہو: اپنی بیویوں پر مت آؤ۔\n16۔ اور صبح کے تیسرے دن ایسا ہوا کہ گرج چمک اور بجلی چمک رہی تھی، پہاڑ پر ایک گھنا بادل تھا، اور بگل کی آواز بہت بلند تھی؛ تاکہ کیمپ میں موجود تمام لوگ کانپ اٹھے۔\n17۔ اور موسیٰ نے لوگوں کو خدا سے ملنے کے لیے باہر نکالا؛ اور وہ پہاڑ کے نچلے حصے میں کھڑے تھے۔\n18۔ اور پہاڑ سینا مکمل طور پر دھوئیں پر تھا، کیونکہ خداوند نے آگ میں اس پر نازل ہوا: اور اس کا دھواں بھٹی کے دھوئیں کی طرح اوپر اٹھا، اور پورا پہاڑ زور سے لرز اٹھا۔\n19۔ اور جب ترمپٹ کی آواز لمبی اور تیز ہوتی گئی، موسیٰ نے بولا، اور خدا نے اسے ایک آواز سے جواب دیا۔\n20۔ اور خداوند پہاڑ سینا پر اترا، پہاڑ کی چوٹی پر: اور خداوند نے موسیٰ کو پہاڑ کی چوٹی پر بلایا؛ اور موسیٰ اوپر چلا گیا۔\n21۔ اور خداوند نے موسیٰ سے کہا، نیچے آؤ، لوگوں کو حکم دو، ورنہ وہ خداوند کے سامنے پہنچ کر دیکھیں، اور ان میں سے بہت سے ہلاک ہو جائیں گے۔ {چارج: عبوری۔ مقابلہ}\n22۔ اور وہ کاہن، جو خداوند کے قریب آتے ہیں، خود کو پاک کریں، ورنہ خداوند ان پر حملہ آور ہو جائے گا۔\n23۔ اور موسیٰ نے خداوند سے کہا، لوگ سینا کے پہاڑ پر نہیں آ سکتے، کیونکہ تو نے ہمیں حکم دیا ہے، کہہ کر کہ پہاڑ کے گرد حدود مقرر کرو اور اسے پاک کرو۔\n24۔ اور خداوند نے اس سے کہا، دور ہو جاؤ، نیچے اتر جاؤ، اور تم اور ہارون تمہارے ساتھ اوپر آؤ، لیکن کاہنوں اور لوگوں کو خدا کے پاس آنے نہ دو، ورنہ وہ ان پر حملہ آور ہو جائے گا۔\n25۔ تو موسیٰ لوگوں کے پاس نیچے گیا اور ان سے بات کی۔","1۔ اور خدا نے یہ سب الفاظ کہے، کہا،\n2. میں خداوند ہوں، تیرا خدا، جس نے تمہیں مصر کی سرزمین سے، غلامی کے گھر سے نکالا۔ {بانڈج: عبرانی۔ خادم}\n3۔ میرے علاوہ تمہارے اور کوئی خدا نہیں ہوں گے۔\n4۔ تم اپنے لیے کوئی کندہ شدہ مورت، یا کسی بھی چیز کی مشابہت نہیں بنا سکتے جو آسمان کے اوپر ہے، یا جو زمین کے نیچے ہے، یا جو زمین کے نیچے پانی میں ہے:\n5۔ تم ان کے سامنے سر نہ جھکاؤ اور نہ ہی ان کی عبادت کرو: کیونکہ میں، خداوند تیرا خدا، ایک حسد کرنے والا خدا ہوں، جو باپ و دادوں کی بدکاری بچوں پر نازل کرتا ہوں ان تیسری اور چوتھی نسلوں تک جو مجھ سے نفرت کرتے ہیں؛\n6۔ اور ہزاروں لوگوں پر رحم دکھاؤں جو مجھ سے محبت کرتے ہیں اور میرے احکامات کی پاسداری کرتے ہیں۔\n7۔ تم اپنے خدا خداوند کا نام بے مقصد مت لینا؛ کیونکہ خداوند اسے بے گناہ نہیں رکھے گا جو اس کا نام بے فائدہ لیتا ہے۔\n8۔ سبت کے دن کو یاد رکھو، تاکہ اسے مقدس رکھا جا سکے۔\n9۔ چھ دن محنت کرو گے، اور اپنا سارا کام کرو گے:\n10۔ لیکن ساتواں دن خداوند تمہارے خدا کا سبت ہے: اس میں تم کوئی کام نہیں کرو گے، نہ تمہارا بیٹا، نہ اپنی بیٹی، نہ تمہارا خادم، نہ تمہاری نوکری، نہ تمہاری مویشی، نہ تمہارا اجنبی جو تمہارے دروازوں کے اندر ہے:\n11۔ چھ دنوں میں خداوند نے آسمان، زمین، سمندر اور ان میں موجود سب کچھ بنایا اور ساتویں دن آرام کیا: اسی لیے خداوند نے سبت کے دن کو برکت دی اور اسے مقدس قرار دیا۔\n12۔ اپنے باپ اور ماں کی عزت کرو: تاکہ تمہارے دن اس زمین پر لمبے ہوں جو خداوند تیرا خدا تمہیں دیتا ہے۔\n13. تم قتل نہ کرو۔\n14. تم نہیں کرو گے۔\n15۔ تم چوری نہ کرو۔\n16۔ تم اپنے پڑوسی کے خلاف جھوٹی گواہی نہ دو۔\n17۔ تم اپنے پڑوسی کے گھر کی خواہش نہ کرو، نہ اپنے پڑوسی کی بیوی، نہ اس کے نوکر، نہ اس کی نوکرانی کی، نہ اس کے بیل، نہ اس کے گدھے کو، اور نہ ہی اپنے پڑوسی کی کسی بھی چیز کی خواہش کرو گے۔\n18۔ اور سب لوگوں نے گرج، بجلی، بگل کی آواز، اور پہاڑ کے دھوئیں کو دیکھا: اور جب لوگوں نے اسے دیکھا، تو وہ ہٹ گئے اور دور چلے گئے۔\n19۔ اور انہوں نے موسیٰ سے کہا، تو ہم سے بات کرو، ہم سنیں گے، لیکن خدا ہم سے بات نہ کرے، ورنہ ہم مر جائیں گے۔\n20۔ اور موسیٰ نے لوگوں سے کہا، خوف نہ کرو، کیونکہ خدا تمہیں آزمانے آیا ہے، اور تاکہ اس کا خوف تمہارے سامنے ہو، تاکہ تم گناہ نہ کرو۔\n21۔ اور لوگ دور کھڑے ہو گئے، اور موسیٰ اس گہرے اندھیرے کے قریب پہنچے جہاں خدا {تھا}۔\n22۔ اور خداوند نے موسیٰ سے فرمایا، یوں تو بنی اسرائیل سے کہے گا، تم نے دیکھا کہ میں نے آسمان سے تم سے بات کی ہے۔\n23۔ تم میرے ساتھ چاندی کے خدا نہیں بنا سکتے، نہ ہی اپنے لیے سونے کے خدا بناؤ گے۔\n24۔ تم میرے لیے زمین کا ایک قربان گاہ بناؤ گے، اور اس پر اپنی جلنے کی قربانیاں، اپنی امن کی قربانیاں، اپنی بھیڑیں، اور اپنے بیل قربان کرو گے: جہاں میں اپنا نام لکھوں گا وہاں میں تمہارے پاس آؤں گا، اور تمہیں برکت دوں گا۔\n25۔ اور اگر تم مجھے پتھر کا قربان گاہ بنانا چاہتے ہو، تو اسے تراشے ہوئے پتھر سے نہیں بناؤ گے، کیونکہ اگر تم اپنا آلہ اس پر اٹھاؤ گے تو تم نے اسے آلودہ کر دیا ہے۔ {build...: عبرانی انہیں ہائیونگ کے ساتھ بنائیں}\n26. نہ ہی تم سیڑھیوں سے میرے محراب تک چڑھو گے، تاکہ تمہاری برہنگی وہاں ظاہر نہ ہو۔","1۔ اب یہ وہ فیصلے ہیں جو تم ان کے سامنے رکھو گے۔\n2۔ اگر تم کوئی عبرانی نوکر خریدو تو وہ چھ سال خدمت کرے گا: اور ساتویں سال وہ بغیر کسی معاوضے کے آزاد جائے گا۔\n3۔ اگر وہ اکیلا آیا تو خود باہر جائے گا: اگر وہ شادی شدہ ہے تو اس کی بیوی اس کے ساتھ جائے گی۔ {اکیلے: عبرانی۔ اپنے جسم کے ساتھ}\n4۔ اگر اس کے مالک نے اسے بیوی دی ہو، اور اس نے اسے بیٹے یا بیٹیاں پیدا کیں؛ بیوی اور اس کے بچے اس کے مالک ہوں گے، اور وہ خود باہر جائے گا۔\n5۔ اور اگر خادم صاف کہے، میں اپنے آقا، اپنی بیوی اور بچوں سے محبت کرتا ہوں؛ میں آزاد نہیں جاؤں گا: {...: عبرانی۔ کہہ رہا ہوں گے کہ کہیں گے}\n6۔ پھر اس کا مالک اسے ججوں کے پاس لے جائے گا؛ وہ اسے دروازے یا دروازے کے کھمبے تک بھی لے جائے گا؛ اور اس کا آقا اس کے کان کو آؤل سے سوراخ کرے گا؛ اور وہ ہمیشہ اس کی خدمت کرے گا۔\n7۔ اور اگر کوئی آدمی اپنی بیٹی کو نوکرانی کے طور پر بیچ دے، تو وہ نوکروں کی طرح باہر نہیں جائے گی۔\n8۔ اگر وہ اپنے مالک کو پسند نہ کرے، جس نے اسے خود سے منگنی کی ہے، تو وہ اسے نجات دے گا: اسے اجنبی قوم کو بیچنے کے لیے اس کے پاس کوئی طاقت نہیں کیونکہ اس نے اس کے ساتھ دھوکہ دیا ہے۔ {براہ کرم...: عبرانی۔ ان کی نظر میں برائی ہو، وغیرہ}\n9۔ اور اگر اس نے اسے اپنے بیٹے سے منگنی کر دی ہے، تو وہ اس کے ساتھ بیٹیوں کی طرح سلوک کرے گا۔\n10۔ اگر وہ اس کے لیے کوئی اور {بیوی} لے لے؛ اس کا کھانا، اس کا لباس، اور اس کی شادی کی ذمہ داری، وہ کم نہیں کرے گا۔\n11۔ اور اگر وہ یہ تینوں اس کے ساتھ نہ کرے، تو وہ بغیر پیسے کے آزاد چلی جائے گی۔\n12۔ جو کسی کو مارے گا تاکہ وہ مر جائے، اسے ضرور قتل کر دیا جائے گا۔\n13۔ اور اگر کوئی شخص انتظار میں نہ ہو، بلکہ خدا اسے اس کے ہاتھ میں دے دے؛ پھر میں تمہیں وہ جگہ دوں گا جہاں وہ بھاگ جائے گا۔\n14۔ لیکن اگر کوئی شخص اپنے پڑوسی پر بے باکی سے حملہ کرے اور اسے چالاکی سے قتل کرے؛ تم اسے میری قربان گاہ سے لے جاؤ گے تاکہ وہ مر جائے۔\n15۔ اور جو اپنے والد یا ماں کو مارے گا، اسے ضرور قتل کر دیا جائے گا۔\n16۔ اور جو کسی آدمی کو چوری کرے اور بیچے، یا اگر اس کے ہاتھ میں پایا جائے تو اسے ضرور قتل کر دیا جائے گا۔\n17۔ اور جو اپنے والد یا ماں کو لعنت دے، اسے ضرور موت دی جائے گی۔ {لعنت: یا، نفرت کرنا}\n18۔ اور اگر لوگ مل کر کوشش کریں، اور ایک دوسرے کو پتھر یا مکے سے مارے، اور وہ نہ مرے، بلکہ اپنا بستر برقرار رکھے: {دوسرا: یا اپنے پڑوسی}\n19۔ اگر وہ دوبارہ اٹھے، اور اپنی چھڑی پر چلے جائیں، تو جس نے {اسے} کو مارا جائے گا، وہ آزاد ہوگا: صرف وہی اپنے وقت کے نقصان کی قیمت ادا کرے گا، اور {اسے} کو مکمل طور پر شفا دے گا۔ {دی لاس...: ہیب۔ اس کا خاتمہ}\n20۔ اور اگر کوئی آدمی اپنی نوکر یا نوکرانی کو لاٹھی سے مارے اور وہ اس کے ہاتھ سے مر جائے؛ اسے ضرور سزا دی جائے گی۔ {سزا دی گئی: ہیب۔ انتقام}\n21. اس کے باوجود، اگر وہ ایک یا دو دن جاری رہے تو اسے سزا نہیں دی جائے گی: کیونکہ وہ اس کا پیسہ ہے۔\n22۔ اگر مرد کوشش کریں اور کسی عورت کو نقصان پہنچائیں تاکہ اس کا پھل اس سے نکل جائے، اور پھر بھی کوئی شرارت نہ ہو، تو اسے ضرور سزا دی جائے گی، جیسا کہ عورت کا شوہر اس پر ڈالے گا؛ اور وہ ججوں کے فیصلے کے مطابق ادائیگی کرے گا۔\n23۔ اور اگر کوئی شرارت ہو، تو تم زندگی کے بدلے زندگی دو گے،\n24۔ آنکھ کے بدلے آنکھ، دانت کے بدلے دانت، ہاتھ کے بدلے ہاتھ، پاؤں کے بدلے پاؤں،\n25۔ جلنے کے بدلے جلانا، زخم کے بدلے زخم، دھاری بہ دھاری۔\n26۔ اور اگر کوئی آدمی اپنے نوکر کی آنکھ یا اس کی نوکرانی کی آنکھ کو مار دے، تو وہ مر جائے؛ وہ اسے اپنی آنکھ کے لیے آزاد کر دے گا۔\n27۔ اور اگر وہ اپنے نوکر یا نوکرانی کا دانت نکال دے؛ وہ اسے اس کے دانت کی خاطر آزاد کر دے گا۔\n28۔ اگر بیل کسی مرد یا عورت کو زخمی کرے تو وہ مر جائیں گے: تو بیل کو ضرور پتھر مار دیا جائے گا، اور اس کا گوشت نہیں کھایا جائے گا؛ لیکن بیل کا مالک چھوڑ دے گا۔\n29۔ لیکن اگر بیل ماضی میں اپنے سینگ سے دھکا دیتا تھا، اور اس کے مالک کو گواہی دی گئی ہو، اور اس نے اسے قید نہیں کیا بلکہ یہ کہا کہ اس نے ایک مرد یا عورت کو مارا ہے؛ بیل کو سنگسار کیا جائے گا، اور اس کے مالک کو بھی قتل کر دیا جائے گا۔\n30۔ اگر اس پر کوئی رقم عائد کی جائے تو وہ اپنی جان کی تاوان کے بدلے جو اس پر عائد کی جائے گی۔\n31۔ چاہے اس نے بیٹے کو زخمی کیا ہو یا بیٹی کو، اس فیصلے کے مطابق اس کے ساتھ کیا جائے گا۔\n32۔ اگر بیل کسی نوکر یا نوکرانی کو دھکا دے؛ وہ اپنے مالک کو تیس شیکل چاندی دے گا، اور بیل کو سنگسار کیا جائے گا۔\n33۔ اور اگر کوئی آدمی گڑھا کھولے، یا اگر آدمی گڑھا کھودے، اور اسے ڈھانپے نہیں، اور اس میں بیل یا گدھا گر جائے؛\n34۔ گڑھے کا مالک {اچھا} کرے گا، {اور} اس کے مالک کو پیسے دے گا؛ اور مردہ {درندہ} اس کا ہوگا۔\n35۔ اور اگر ایک آدمی کا بیل دوسرے کے بیل کو نقصان پہنچائے تو وہ مر جائے؛ پھر وہ زندہ بیل بیچیں گے، اور اس کا پیسہ تقسیم کریں گے؛ اور مردہ {بیل} بھی تقسیم کریں گے۔\n36۔ یا اگر یہ معلوم ہو کہ بیل ماضی میں دھکیلتا رہا ہے، اور اس کے مالک نے اسے اندر نہیں رکھا؛ وہ یقینی طور پر بیل کے بدلے بیل کا معاوضہ دے گا؛ اور مردے اس کے اپنے ہوں گے۔","1۔ اگر کوئی آدمی بیل یا بھیڑ چرا کر اسے مار دے یا بیچ دے؛ وہ ایک بیل کے بدلے پانچ بیل اور بھیڑ کے بدلے چار بھیڑیں بحال کرے گا۔ {یا بھیڑ: یا، یا بکری}\n2۔ اگر کوئی چور ٹوٹتا ہوا پایا جائے، اور اسے مار دیا جائے کہ وہ مر جائے، تو اس کے لیے خون نہیں بہایا جائے گا۔\n3۔ اگر سورج اس پر طلوع ہو جائے تو اس کے لیے خون بہایا جائے گا؛ {کیونکہ } اسے مکمل معاوضہ دینا چاہیے؛ اگر اس کے پاس کچھ نہیں ہے تو اسے چوری کے لیے بیچ دیا جائے گا۔\n4۔ اگر چوری یقینی طور پر اس کے ہاتھ میں زندہ پائی جائے، چاہے وہ بیل ہو، گدھا ہو یا بھیڑ؛ وہ دوگنا بحال کرے گا۔\n5۔ اگر کوئی آدمی کھیت یا انگور کے باغ کو کھا لے، اور اپنے جانور میں ڈالے، اور دوسرے شخص کے کھیت میں خوراک کھائے؛ اپنے کھیت کے بہترین اور اپنے انگور کے باغ کے بہترین سے وہ معاوضہ ادا کرے گا۔\n6۔ اگر آگ لگے، اور کانٹوں میں پھنس جائے، تاکہ اناج کے ڈھیر، یا کھڑا اناج یا کھیت جل جائیں {اس کے ساتھ}؛ جس نے آگ جلائی، وہ ضرور بدلہ دے گا۔\n7۔ اگر کوئی شخص اپنے پڑوسی کو رکھنے کے لیے پیسہ یا سامان دے اور وہ اس کے گھر سے چوری ہو جائے؛ اگر چور پکڑا گیا تو اسے دوگنا ادا کرنے دو۔\n8۔ اگر چور نہ ملے، تو گھر کے مالک کو ججوں کے پاس لایا جائے گا {تاکہ وہ دیکھ سکیں کہ آیا اس نے اپنے پڑوسی کی مال پر ہاتھ رکھا ہے یا نہیں۔\n9۔ کسی بھی قسم کی خلاف ورزی کے لیے، {چاہے وہ بیل کے لیے ہو}، گدھے کے لیے، بھیڑوں کے لیے، لباس کے لیے، {یا} کسی بھی قسم کی گمشدہ چیز کے لیے، جسے {کوئی اور} اس کی ملکیت قرار دے، دونوں فریقین کا مقدمہ ججوں کے سامنے آئے گا؛ {اور} جسے جج سزا دیں گے، وہ اپنے پڑوسی کو دوگنا ادا کرے گا۔\n10۔ اگر کوئی آدمی اپنے پڑوسی کو گدھا، بیل، بھیڑ، یا کوئی جانور دے تاکہ وہ رکھ سکے؛ اور وہ مر جاتا ہے، یا زخمی ہو جاتا ہے، یا دور بھگا دیا جاتا ہے، کوئی انسان اسے نہیں دیکھ پاتا:\n11۔ {پھر} ان دونوں کے درمیان خداوند کی قسم ہوگی کہ اس نے اپنے پڑوسی کے مال پر ہاتھ نہیں رکھا؛ اور اس کا مالک قبول کرے گا، اور وہ اسے اچھا نہیں بنائے گا۔\n12۔ اور اگر وہ اس سے چوری ہو جائے تو وہ اس کے مالک کو معاوضہ دے گا۔\n13۔ اگر یہ ٹکڑوں میں پھٹ جائے تو {تو} اسے گواہی کے طور پر پیش کرے، {اور} وہ جو پھٹا ہوا ہے اسے درست نہیں کرے گا۔\n14۔ اور اگر کوئی شخص اپنے پڑوسی سے {چاہیے} ادھار لے اور وہ زخمی ہو جائے یا مر جائے، اس کا مالک {جو اس کے ساتھ نہ ہو}، تو وہ یقینی طور پر اسے ٹھیک کرے گا۔\n15۔ {لیکن} اگر اس کا مالک {ہو} تو وہ اسے اچھا نہیں بنا سکتا: اگر وہ {کرائے کی چیز} ہو، تو وہ اس کی کرایہ پر آئی ہے۔\n16۔ اور اگر کوئی مرد کسی غیر منگیتر لڑکی کو بہکائے، اور اس کے ساتھ سوئے، تو وہ اسے اپنی بیوی کے طور پر عطا کرے گا۔\n17۔ اگر اس کے والد نے اسے دینے سے مکمل انکار کر دیا تو وہ کنواری عورتوں کے جہیز کے مطابق پیسے ادا کرے گا۔ {پے: عبوری۔ وزن کریں}\n18. تم جادوگرنی کو زندہ نہیں رہنے دینا۔\n19۔ جو بھی جانور کے ساتھ سوتا ہے اسے ضرور موت دی جائے گی۔\n20۔ جو کسی بھی خدا کے لیے قربانی دیتا ہے، سوائے خداوند کے، وہ مکمل طور پر تباہ ہو جائے گا۔\n21۔ تم کسی اجنبی کو پریشان نہ کرو اور نہ ہی اس پر ظلم کرو، کیونکہ تم مصر کی سرزمین میں اجنبی تھے۔\n22۔ آپ کسی بیوہ یا یتیم بچے کو تکلیف نہیں دیں گے۔\n23۔ اگر تم انہیں کسی بھی طرح تکلیف دو، اور وہ مجھ سے پکاریں، تو میں ضرور ان کی پکار سنوں گا؛\n24. اور میرا غصہ گرم ہو جائے گا، اور میں تمہیں تلوار سے مار ڈالوں گا؛ اور تمہاری بیویاں بیوہ ہوں گی، اور تمہارے بچے یتیم ہوں گے۔\n25۔ اگر تم میرے لوگوں میں سے کسی کو قرض دو جو تمہارے لیے غریب ہے، تو تم اس کے لیے سود خور نہیں بنو گے، نہ ہی اس پر سود ڈالو گے۔\n26۔ اگر تم اپنے پڑوسی کا لباس گروی رکھو، تو سورج کے غروب ہونے کے ذریعے اسے اس کے حوالے کرو گے:\n27. کیونکہ یہ صرف اس کا چادر ہے، یہ اس کی جلد کے لیے اس کا لباس ہے: وہ کہاں سوئے گا؟ اور جب وہ مجھ سے پکارے گا، تو میں سنوں گا؛ کیونکہ میں {مہربان} ہوں۔\n28۔ تم دیوتاؤں کی برا بھلا مت کہنا، نہ ہی اپنے لوگوں کے حکمران کو لعنت کرنا۔ {دیوتا: یا، ججز}\n29۔ تم اپنے پہلے پکے ہوئے پھل اور شراب پیش کرنے میں دیر نہ کرو: اپنے بیٹوں میں سے پہلا بیٹا مجھے دے گا۔ {پہلا...: عبرانی۔ تیری عظمت} {شراب: عبرانی۔ آنسو}\n30۔ اسی طرح تم اپنے بیلوں کے ساتھ بھی کرو گے، {اور} اپنی بھیڑوں کے ساتھ: سات دن اس کی ماں کے ساتھ ہوں گے؛ آٹھویں دن تم مجھے یہ دو گے۔\n31۔ اور تم میرے لیے مقدس لوگ بنو گے: نہ تم کھیت میں جانوروں سے پھٹے ہوئے گوشت کو کھاؤ گے؛ تم اسے کتوں پر پھینک دو گے۔","1۔ تم جھوٹی رپورٹ نہ اٹھاؤ: بدکاروں کے ساتھ ہاتھ نہ رکھو تاکہ وہ ناجائز گواہ بن جاؤ۔ {بڑھاؤ: یا، وصول کرو}\n2۔ تم لوگوں کی پیروی نہ کرو کہ وہ {برائی} کریں؛ نہ ہی تم اس وجہ سے بات کرو گے کہ بہت سے لوگوں کے بعد نیچا جائے {فیصلہ}: {بولو: عبرانی۔ جواب}\n3۔ نہ تو تم کسی غریب آدمی کو اس کے مقصد میں قبول کرو گے۔\n4۔ اگر تم اپنے دشمن کے بیل یا اس کے گدھے سے گمراہ ہو جاؤ، تو اسے ضرور واپس لے آؤ گے۔\n5۔ اگر تم دیکھو کہ جو تم سے نفرت کرتا ہے اس کا گدھا اس کے بوجھ تلے پڑا ہے، اور اس کی مدد کرنے سے گریز کرو، تو تم ضرور اس کی مدد کرو گے۔ {اور...: یا، کیا تم اس کی مدد کرنا بند کرو گے؟ یا، اور تم اپنا کاروبار اس کے لیے چھوڑنا چاہو گے: تم اسے ضرور چھوڑ کر اس کے ساتھ شامل ہو جاؤ گے}\n6۔ تم اپنے غریبوں کے فیصلے کو اس کے مقصد میں نہیں چھینو۔\n7۔ جھوٹے معاملے سے دور رہو؛ اور معصوم اور نیک لوگ قتل نہیں کرتے، کیونکہ میں بدکاروں کو جواز نہیں دوں گا۔\n8۔ اور تم کوئی تحفہ نہ لو، کیونکہ یہ تحفہ عقلمندوں کو اندھا کر دیتا ہے اور راستبازوں کے الفاظ کو بگاڑ دیتا ہے۔ {دانا: عبرانی۔ دی سیئنگ}\n9۔ اور تم کسی اجنبی پر ظلم نہ کرو گے: کیونکہ تم اجنبی کے دل کو جانتے ہو، کیونکہ تم مصر کی سرزمین میں اجنبی تھے۔ {دل: عبوری۔ روح}\n10۔ اور چھ سال تک تم اپنی زمین بوتو گے، اور اس کے پھل جمع کرو گے:\n11۔ لیکن ساتویں {سال} کو تو اسے آرام اور آرام کرنے دو؛ تاکہ تمہارے لوگوں کے غریب کھائیں: اور جو کچھ وہ چھوڑیں گے وہ کھیت کے جانور کھائیں گے۔ اسی طرح تم اپنے انگور کے باغ کا بھی معاملہ کرو گے، {اور} اپنے زیتونوں کے باغ کا بھی۔ {اولیو یارڈ: یا، زیتون کے درخت}\n12۔ چھ دن تم اپنا کام کرو گے، اور ساتویں دن آرام کرو گے: تاکہ تمہارا بیل اور تمہارا گدھا آرام کر سکیں، اور تمہاری نوکرانی کا بیٹا اور اجنبی تازہ دم ہو جائے۔\n13۔ اور جو کچھ میں نے تم سے کہا ہے اس میں محتاط رہو: اور دوسرے دیوتاؤں کے نام کا ذکر نہ کرنا، نہ اسے تمہارے منہ سے سننے دو۔\n14. سال میں تین بار میرے لیے دعوت منانا ہے۔\n15۔ تم بغیر خمیر کی روٹی کی عید مناؤ گے: (تم سات دن بغیر خمیر کی روٹی کھاؤ گے، جیسا کہ میں نے تمہیں حکم دیا تھا، مہینے ایب کے مقررہ وقت میں؛ کیونکہ اسی میں تم مصر سے نکلے ہو؛ اور کوئی میرے سامنے خالی نہیں آئے گا:)\n16۔ اور فصل کی تہوار، جو تمہاری محنت کے پہلے پھل ہیں، جو تم نے کھیت میں بوئے ہیں؛ اور جمع کرنے کی تہوار، جو سال کے آخر میں ہے، جب تم اپنی محنت سے کھیت سے جمع کرو گے۔\n17۔ سال میں تین بار تیرے تمام مرد خداوند خدا کے سامنے حاضر ہوں گے۔\n18۔ تم میری قربانی کا خون خمیر شدہ روٹی کے ساتھ پیش نہیں کرو گے؛ نہ ہی میری قربانی کی چربی صبح تک باقی رہے گی۔ {قربانی: یا، دعوت}\n19۔ اپنی زمین کے پہلے پھلوں میں سے پہلا تو اپنے خدا خداوند کے گھر میں لے آؤ گے۔ تم بچے کو اس کی ماں کے دودھ میں نہ اگلاؤ۔\n20۔ دیکھو، میں تمہارے سامنے ایک فرشتہ بھیجتا ہوں، تاکہ تمہیں راستے میں رکھے، اور تمہیں اس جگہ لے جائے جو میں نے تیار کی ہے۔\n21۔ اس سے ہوشیار رہو، اس کی آواز کی سنو، اسے اشتعال نہ دلو؛ کیونکہ وہ تمہاری غلطیوں کو معاف نہیں کرے گا: کیونکہ میرا نام {ہے} اس میں ہے۔\n22۔ لیکن اگر تم واقعی اس کی آواز مانو اور جو کچھ میں کہتا ہوں وہ کرو؛ پھر میں تمہارے دشمنوں کا دشمن بنوں گا، اور تمہارے دشمنوں کا بھی دشمن۔ {ایک مخالف...: یا، میں ان کو سزا دوں گا جو تمہیں تکلیف دیتے ہیں}\n23۔ کیونکہ میرا فرشتہ تمہارے سامنے جائے گا، اور تمہیں اموریوں، حتیوں، پرزیوں، کنعانیوں، حویوں، اور یبوسیوں کے پاس لے جائے گا: اور میں انہیں کاٹ دوں گا۔\n24۔ تم ان کے دیوتاؤں کے سامنے سر نہیں جھکاؤ گے، نہ ان کی عبادت کرو گے، نہ ان کے اعمال کے بعد کرو گے، بلکہ انہیں مکمل طور پر گرا دو گے، اور ان کی تصویریں مکمل طور پر توڑ دو گے۔\n25۔ اور تم خداوند اپنے خدا کی عبادت کرو گے، اور وہ تمہاری روٹی اور پانی کو برکت دے گا؛ اور میں تمہارے درمیان سے بیماری دور کر دوں گا۔\n26۔ تمہاری زمین میں ان کے بچے یا بانجھ نہیں ہوں گے: تمہارے دنوں کی تعداد میں پوری کروں گا۔\n27۔ میں اپنا خوف تمہارے سامنے بھیجوں گا، اور ان تمام لوگوں کو تباہ کر دوں گا جن کے پاس تم آؤ گے، اور میں تمہارے تمام دشمنوں کو تمہاری طرف پیٹھ موڑنے پر مجبور کروں گا۔ {پیچھے ہٹتے ہوئے: عبرانی۔ گردن}\n28۔ اور میں تمہارے سامنے کو بھیجوں گا، جو حوی، کنعانی، اور حیتی کو تمہارے سامنے سے نکال دیں گے۔\n29۔ میں انہیں ایک سال میں تیرے سامنے سے نہیں نکالوں گا؛ تاکہ زمین ویران نہ ہو جائے، اور میدان کا درندہ تمہارے خلاف بڑھ جائے۔\n30۔ آہستہ آہستہ میں انہیں تمہارے سامنے سے نکال دوں گا، جب تک تم بڑا نہ ہو جاؤ اور زمین کا وارث نہ بن جاؤ۔\n31۔ اور میں تمہاری سرحدیں بحیرہ احمر سے لے کر فلسطینیوں کے سمندر تک، اور صحرا سے دریا تک مقرر کروں گا: کیونکہ میں زمین کے باشندوں کو تمہارے ہاتھ میں چھوڑوں گا؛ اور تم انہیں اپنے سامنے نکالو گے۔\n32. تم ان سے یا ان کے دیوتاؤں سے کوئی عہد نہیں کرو گے۔\n33۔ وہ تمہارے ملک میں نہیں رہیں گے، ورنہ وہ تمہیں میرے خلاف گناہ کر دیں گے: کیونکہ اگر تم ان کے دیوتاؤں کی عبادت کرو گے تو یہ تمہارے لیے ایک جال ہوگا۔","1۔ اور اس نے موسیٰ سے کہا، خداوند کے پاس آؤ، تم، ہارون، ندب، ابیہو، اور اسرائیل کے ستر بزرگوں کے پاس؛ اور دور کہیں عبادت کرتے ہیں۔\n2۔ اور صرف موسیٰ ہی خداوند کے قریب آئے گا: لیکن وہ قریب نہیں آئیں گے؛ نہ ہی لوگ اس کے ساتھ جائیں گے۔\n3۔ اور موسیٰ آئے اور لوگوں کو خداوند کے تمام الفاظ اور تمام فیصلے سنائیں: اور سب لوگوں نے ایک آواز میں جواب دیا اور کہا، خداوند نے جو کچھ کہا ہے وہ ہم کریں گے۔\n4۔ اور موسیٰ نے خداوند کے تمام الفاظ لکھے، صبح سویرے اٹھا اور پہاڑی کے نیچے ایک قربان گاہ اور بارہ ستون تعمیر کیے، جیسا کہ اسرائیل کے بارہ قبائل کے مطابق ہیں۔\n5۔ اور اس نے بنی اسرائیل کے نوجوانوں کو بھیجا، جنہوں نے سلائی کی قربانیاں پیش کیں، اور خدا کے لیے بیلوں کی صلح کی قربانیاں قربان کیں۔\n6۔ اور موسیٰ نے آدھا خون لیا اور اسے حوضوں میں ڈال دیا؛ اور آدھا خون جو اس نے قربان گاہ پر چھڑکا۔\n7۔ اور اس نے عہد کی کتاب لی، اور لوگوں کے سامنے پڑھا: اور انہوں نے کہا، خداوند نے جو کچھ کہا ہے وہ سب ہم کریں گے اور فرمانبردار ہوں گے۔\n8۔ اور موسیٰ نے خون لیا اور لوگوں پر چھڑک دیا، اور کہا، دیکھو اس عہد کا خون جو خداوند نے تمہارے ساتھ ان تمام باتوں کے بارے میں کیا ہے۔\n9۔ پھر موسیٰ، ہارون، ندب، ابیہو اور اسرائیل کے ستر بزرگ اوپر گئے:\n10۔ اور انہوں نے اسرائیل کے خدا کو دیکھا: اور اس کے قدموں کے نیچے نیلم کے پتھر کی پکی ہوئی بنی ہوئی تھی، اور آسمان کا جسم اس کی صاف روشنی میں تھا۔\n11۔ اور بنی اسرائیل کے اشرافیہ پر اس نے اپنا ہاتھ نہیں اٹھایا: انہوں نے خدا کو دیکھا، اور کھایا اور پیا۔\n12۔ اور خداوند نے موسیٰ سے کہا، میرے پاس پہاڑ پر آؤ، اور وہاں آ جاؤ، اور میں تمہیں پتھر کی میزیں، ایک قانون اور احکام دوں گا جو میں نے لکھے ہیں؛ تاکہ تم انہیں سکھا سکو۔\n13۔ اور موسیٰ اٹھا، اور اس کا خادم یشوع: اور موسیٰ خدا کے پہاڑ پر چڑھ گیا۔\n14۔ اور اس نے بزرگوں سے کہا، یہاں ہمارے لیے رہو، جب تک ہم دوبارہ تمہارے پاس نہ آئیں: اور دیکھو، ہارون اور ہور تمہارے ساتھ ہیں: اگر کسی کو کوئی کام ہے تو وہ ان کے پاس آ جائے۔\n15۔ اور موسیٰ پہاڑ پر چڑھ گیا، اور پہاڑ پر بادل چھا گیا۔\n16۔ اور خداوند کی شان نے پہاڑ سینا پر قیام کیا، اور چھ دن بادل نے اسے ڈھانپ لیا؛ اور ساتویں دن اس نے موسیٰ کو بادلوں کے بیچ سے پکارا۔\n17۔ اور خداوند کی جلال کا منظر {تھا} جیسے بنی اسرائیل کی نظر میں پہاڑ کی چوٹی پر آگ کو جلا رہا ہو۔\n18۔ اور موسیٰ بادل کے بیچ گیا، اور اسے پہاڑ پر لے آیا: اور موسیٰ پہاڑ میں چالیس دن اور چالیس راتیں رہا۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ بنی اسرائیل سے کہو کہ وہ مجھے ایک قربانی دیں: جو بھی دل سے یہ پیشکش دے، اس میں سے تم میری قربانی قبول کرو۔ {مجھے لاؤ: عبوری۔ میرے لیے لو} {نذران: یا، نذرانہ اٹھاؤ}\n3۔ اور یہ وہ نذرانہ ہے جو تم ان سے لو گے؛ سونا، چاندی، اور پیتل، {نذران: یا، نذرانہ اٹھانا}\n4۔ اور نیلا، اور جامنی، اور سرخ رنگ، اور باریک کتان، اور بکریوں کے {بال}، {باریک...: یا، ریشم}\n5۔ اور مینڈوں کی کھالیں جو سرخ رنگی ہوئی تھیں، اور بیجر کی کھالیں اور شیٹم لکڑی،\n6۔ روشنی کے لیے تیل، مسح کے تیل کے لیے مصالحے، اور میٹھے لوبان کے لیے،\n7۔ اونکس پتھر، اور ایفود اور بریسٹ پلیٹ میں لگائے جانے والے پتھر۔\n8۔ اور وہ مجھے پناہ گاہ بنا دیں؛ تاکہ میں ان کے درمیان رہ سکوں۔\n9۔ جو کچھ میں تمہیں دکھاتا ہوں، خیمہ گاہ کے نمونے اور اس کے تمام آلات کے نمونے کے بعد، اسی طرح تم اسے بناؤ گے۔\n10۔ اور وہ شتیم لکڑی کی ایک صندوق بنائیں گے: دو کیوبٹ آدھا اس کی لمبائی، اس کی چوڑائی ڈیڑھ کیوبٹ ہوگی، اور اونچائی ڈیڑھ کیوبٹ ہوگی۔\n11۔ اور تم اسے خالص سونے سے ڈھانپنے دو، اندر اور باہر بھی، اور اس کے گرد سونے کا تاج بناؤ گے۔\n12۔ اور تم اس کے لیے چار سونے کی انگوٹھیاں ڈھالو، اور ان کے چاروں کونوں میں رکھو؛ اور اس کے ایک طرف دو حلقے ہوں گے، اور دوسری طرف دو حلقے۔\n13۔ اور تم شٹیم کی لکڑی کی لاٹھیاں بناؤ گے، اور ان پر سونا لگاؤ گے۔\n14۔ اور تم لاٹھیوں کو صندوق کے کناروں پر انگوٹھیوں میں ڈال دو تاکہ صندوق ان کے ساتھ اٹھا سکے۔\n15. لاٹھیاں صندوق کی انگوٹھیوں میں ہوں گی: انہیں اس سے نہیں نکالا جائے گا۔\n16۔ اور تم وہ گواہی جو میں تمہیں دوں گا، تابوت میں رکھو گے۔\n17۔ اور تم خالص سونے کی رحمت کی نشست بناؤ گے: دو ہاتھ اور آدھا اس کی لمبائی کے برابر اور اس کی چوڑائی کے برابر ایک کیوبٹ ڈیڑھ۔\n18۔ اور تم دو فرشتہ سونے کے بنو گے، اور انہیں مردی سیٹ کے دونوں سروں پر بنو گے۔\n19۔ ایک فرشتہ ایک سرے پر اور دوسرے کو دوسرے سرے پر کروب: {حتی} رحمت کی نشست کے دو سروں پر کروبی بناؤ۔ {کا...: یا، رحم کی نشست کے معاملے کی}\n20۔ اور کروبی اپنے پروں کو اونچا پھیلائیں گے، رحم کی نشست کو اپنے پروں سے ڈھانپیں گے، اور ان کے چہرے ایک دوسرے کی طرف دیکھیں گے؛ رحمت کی نشست کی طرف کروبیوں کے چہرے ہوں گے۔\n21۔ اور تم رحمت کی نشست کو صندوق پر رکھو گے؛ اور تابوت میں وہ گواہی رکھو گی جو میں تمہیں دوں گا۔\n22۔ اور وہاں میں تم سے ملاقات کروں گا، اور رحم کی نشست کے اوپر سے، دو فرشتے کے درمیان سے جو گواہی کے صندوق پر ہیں، ان تمام چیزوں سے جو میں تمہیں بنی اسرائیل کو حکم میں دوں گا۔\n23۔ تم شتیم لکڑی کی میز بھی بناؤ گے: اس کی لمبائی دو ہوت، چوڑائی کے برابر ایک کیوبٹ، اور اونچائی ڈیڑھ کون۔\n24۔ اور تم اسے خالص سونے سے ڈھانپاؤ گے، اور اس کے گرد سونے کا تاج بناؤ گے۔\n25۔ اور تم اس کے گرد ایک ہاتھ کی چوڑائی کی سرحد بناؤ گے، اور اس کے گرد سنہری تاج بناؤ گے۔\n26۔ اور اس کے لیے چار سونے کی انگوٹھیاں بناؤ، اور ان کے چار کونوں میں انگوٹھیاں رکھ دو جو اس کے چار فٹ پر ہیں۔\n27۔ کنارے کے ساتھ انگوٹھیاں لکڑیوں کی جگہوں کے لیے ہوں گی تاکہ میز رکھی جا سکے۔\n28۔ اور تم شتیم کی لکڑی کے لاٹھی کے ڈنڈے بناؤ گے، اور ان پر سونا ڈالو گے تاکہ میز ان کے ساتھ اٹھائی جا سکے۔\n29۔ اور تم اس کے برتن، چمچ، اور اس کے ڈھانپنے اور اس کے پیالے تیار کرو گے، تاکہ انہیں صاف سونے سے ڈھانپ سکو۔ {تو...: یا، بہنے کے لیے}\n30۔ اور تم ہمیشہ میرے سامنے روٹی دکھاؤ گے۔\n31۔ اور تم خالص سونے کا شمعدان بناؤ گے: موم بتی کا پھینٹا ہوا کام ہوگا: اس کا ڈنٹھل، اس کی شاخیں، اس کے پیالے اور اس کے پھول بھی ایک ہی ہوں گے۔\n32۔ اور اس کے کناروں سے چھ شاخیں نکلیں گی؛ ایک طرف سے موم بتی کی تین شاخیں، اور دوسری طرف سے موم بتی کی تین شاخیں:\n33۔ بادام کی طرح تین پیالے بنے، {ایک شاخ میں} ایک نوپ اور ایک پھول کے ساتھ؛ اور دوسری شاخ میں بادام کی طرح تین پیالے بنے ہیں، {ساتھ} ایک گٹھا اور ایک پھول: یعنی ان چھ شاخوں میں جو موم بتی سے نکلتی ہیں۔\n34۔ اور شمعدان میں چار پیالے ہوں گے جو بادام کی طرح بنے ہوں گے، جن کے نوک اور پھول ہوں گے۔\n35۔ اور {ایک ہی شاخوں کے نیچے ایک نوپ} ہوگی، اور ایک نوپ دو شاخوں کے نیچے، اور ایک نوپ دو شاخوں کے نیچے ہوگا، جیسا کہ شمعدان سے نکلنے والی چھ شاخوں کے مطابق ہوگا۔\n36۔ ان کے نوک اور شاخیں ایک جیسی ہوں گی: سب کچھ خالص سونے کا ایک ہی پھینٹا ہوا کام ہوگا۔\n37۔ اور تم اس کے سات چراغ بنانا، اور وہ اس کے چراغ روشن کریں گے تاکہ وہ اس پر روشنی ڈال سکیں۔ {روشنی آئے گی: یا، بلند ہو جائے گی} {it: عبرانی اس کا چہرہ}\n38۔ اور اس کے چمٹے اور اس کے سنف ڈشز خالص سونے کے ہوں گے۔\n39۔ {Of} خالص سونے کا ہنر بنائے گا، ان تمام برتنوں سے۔\n40۔ اور دیکھو کہ تم انہیں ان کے نقش و نگار کے مطابق بناتے ہو، جو تمہیں پہاڑ میں دکھایا گیا تھا۔ {جو کہ...: عبرانی جو تمہیں دکھایا گیا}","1۔ مزید برآں، تم خیمہ گاہ کو دس پردے {سے} باریک الجھے ہوئے کپڑوں سے، نیلا، جامنی اور سرخ بناؤ گے: {چالاکی سے} کروبی کے ساتھ انہیں بناؤ گے۔ {چالاکی سے...: عبرانی۔ ایک چالاک کاریگر یا کشیدہ کاری کرنے والے کا کام}\n2۔ ایک پردے کی لمبائی آٹھ اور بیس کیوبٹ ہوگی، اور ایک پردے کی چوڑائی چار کیوبٹ: اور ہر پردے کی ایک پیمائش ہوگی۔\n3۔ پانچ پردے ایک دوسرے سے جوڑے جائیں گے؛ اور {دیگر} پانچ پردے {جڑے ہوں گے} جو ایک دوسرے سے جڑے ہوں گے۔\n4۔ اور تم جوڑنے کے سیلویج سے ایک پردے کے کنارے پر نیلے رنگ کے حلقے بناؤ گے؛ اور اسی طرح تم {اور} پردے کے بالکل کنارے پر، دوسرے پردے کے جوڑ میں بناؤ گے۔ {سیلویج: کپڑے کا ایک کنارہ جو اتنا بنا ہوا ہے کہ وہ کھل نہیں سکتا}\n5. ایک پردے میں پچاس حلقے بنائیں گے، اور دوسرے پردے کے جوڑ میں پردے کے کنارے پر پچاس لوپ بنائیں گے؛ تاکہ یہ حلقے ایک دوسرے پر قابض ہو سکیں۔\n6۔ اور تم سونے کے پچاس ٹیچ بنو گے، اور پردوں کو ٹیچز کے ساتھ جوڑ دو: اور یہ ایک خیمہ ہوگا۔\n7. اور تم بکریوں کے بالوں کے پردے بنو گے تاکہ وہ خیمہ گاہ پر پردہ بن جائیں: گیارہ پردے بناؤ گے۔\n8۔ ایک پردے کی لمبائی تیس کیوبٹ ہوگی، اور ایک پردے کی چوڑائی چار کیوبٹ: اور گیارہ پردے {سب} ایک ہی پیمانے کے ہوں گے۔\n9۔ اور تم پانچ پردے اور چھ پردے الگ الگ جوڑو، اور خیمہ کے سامنے چھٹے پردے کو دوگنا کرو گے۔\n10۔ اور تم ایک پردے کے کنارے پر پچاس لوپ بناؤ گے، جو پردے کے کنارے سے باہر ہے، اور پردے کے کنارے پر پچاس لوپ بنائیں گے جو دوسرے کو جوڑیں گے۔\n11۔ اور تم پچاس پیتل کے ٹیچز بنو، اور انہیں لوپس میں رکھو، اور خیمے کو جوڑ دو تاکہ وہ ایک ہو جائے۔ {خیمہ: یا، ڈھانپنا}\n12۔ اور خیمے کے پردوں کا باقی ماندہ، آدھا پردہ جو باقی ہے، وہ خیمے کے پچھلے حصے پر لٹکا ہوگا۔\n13۔ اور خیمے کے پردوں کی لمبائی میں باقی رہ جانے والی چیز کے دوسری طرف ایک کیوبٹ، جو خیمے کے پردوں کی لمبائی میں باقی ہے، اس طرف اور اس طرف سے ایک ہاتھ لٹکا جائے گا تاکہ اسے ڈھانپ سکے۔ {اس سے...: عبرانی۔ باقی یا اضافی میں\n14۔ اور تم خیمے کے لیے سرخ رنگ کے مینڈوں کی کھال اور بیجر کی کھالوں کے اوپر ایک ڈھکن بناؤ گے۔\n15۔ اور تم کھڑے ہو کر خیمہ کے لیے تختیاں بناؤ گے۔\n16۔ دس ہاتھ ایک تختے کی لمبائی کے برابر ہوں گے، اور ایک ہاتھ اور آدھا ایک تختی کی چوڑائی کے برابر ہوگا۔\n17۔ ایک بورڈ میں دو ٹینن ہوں گے، جو ایک دوسرے کے خلاف ترتیب میں رکھے جائیں گے: یوں تم خیمہ کے تمام تختوں کے لیے تیار ہو گے۔ {ٹیننز: عبوری۔ ہاتھ}\n18۔ اور تم خیمہ کے لیے تختیاں بناؤ گے، جنوب کی طرف بیس تختے۔\n19۔ اور تم بیس تختوں کے نیچے چالیس چاندی کے ساکٹ بناؤ گے؛ ایک بورڈ کے نیچے دو ساکٹ اس کے دو ٹینن کے لیے، اور دو ساکٹس دوسرے بورڈ کے نیچے دو ساکٹس اس کے دو ٹینن کے لیے۔ {ٹیننز: عبوری۔ ہاتھ}\n20۔ اور خیمہ کی دوسری طرف شمالی جانب بیس تختے ہوں گے:\n21۔ اور ان کے چالیس ساکٹ چاندی کے؛ ایک بورڈ کے نیچے دو ساکٹ، اور دوسرے بورڈ کے نیچے دو ساکٹ۔\n22۔ اور خیمہ کے مغرب کی طرف کے اطراف کے لیے چھ تختے بناؤ گے۔\n23۔ اور تم دو تختیاں خیمہ کے دونوں اطراف کے کونوں کے لیے بناؤ گے۔\n24۔ اور وہ نیچے سے جڑے ہوں گے، اور سر کے اوپر ایک انگوٹھی میں جڑے جائیں گے: یہی ان دونوں کے لیے ہوگا؛ وہ دونوں کونوں کے لیے ہوں گے۔ {جوڑے ہوئے: عبرانی۔ جڑواں}\n25۔ اور یہ آٹھ تختے ہوں گے، اور ان کے ساکٹ چاندی کے ہوں گے، سولہ ساکٹ؛ ایک بورڈ کے نیچے دو ساکٹ، اور دوسرے بورڈ کے نیچے دو ساکٹ۔\n26. اور تم گندگی کی لکڑی کی سلاخیں بناؤ گے؛ ٹیبرنیکل کے ایک طرف کے تختوں کے لیے پانچ،\n27۔ اور ٹیبرنیکل کے دوسری طرف کے تختوں کے لیے پانچ بارز، اور ٹیبرنیکل کے کنارے کے تختوں کے لیے پانچ بارز، دونوں طرف مغرب کی طرف۔\n28۔ اور تختوں کے درمیان درمیانی بار ایک سرے سے دوسرے سرے تک جائے گی۔\n29۔ اور تم تختوں کو سونے سے ڈھانپیں گے، اور ان کی انگوٹھیاں سونے کی جگہوں کے لیے بنائیں گے، اور سلاخوں پر سونے کی جگہ رکھو۔\n30۔ اور تم خیمہ کو اس انداز کے مطابق اٹھاؤ گے جو تمہیں پہاڑ میں دکھایا گیا تھا۔\n31۔ اور تم نیلا، جامنی، سرخ اور باریک الجھا ہوا کپڑا چالاکی سے بنایا جائے گا: اسے فرشتے سے بنایا جائے گا:\n32۔ اور تم اسے چار ستونوں پر لٹکاؤ گے جو سونے سے ڈھکے ہوئے ہیں: ان کے کانٹے سونے کے ہوں گے، چار چاندی کے ساکٹوں پر۔\n33۔ اور تم چادر کو لٹکاؤ گے تاکہ تم پردے کے اندر گواہی کا صندوق لے آؤ: اور پردہ تم پر مقدس اور مقدس کے درمیان تقسیم ہو جائے گا۔\n34۔ اور تم گواہی کے صندوق پر رحم کی نشست سب سے مقدس {جگہ} پر رکھو گے۔\n35۔ اور تم میز بغیر پردے کے رکھو گے، اور شمعدان کو ٹیبرنیکل کے جنوب کی طرف میز کے ساتھ رکھو گے: اور تم میز کو شمال کی طرف رکھو گے۔\n36۔ اور تم خیمے کے دروازے کے لیے ایک لٹکاؤ بناؤ گے، نیلا، جامنی، سرخ اور باریک لپٹا ہوا کتان، جو سوئی سے بنا ہو۔\n37۔ اور تم لٹکتے ہوئے پانچ ستونوں کے لیے شتم {لکڑی} بناؤ گے، اور ان پر سونے کی طرح ڈھانپو گے، {اور} ان کے کانٹے سونے کے ہوں گے: اور تم ان کے لیے پانچ پیتل کے ساکٹ ڈھالو گے۔","1۔ اور تم شتیم لکڑی کا ایک قربان گاہ بناؤ گے، جو پانچ ہاتھ لمبا اور پانچ ہاتھ چوڑا ہو؛ قربان گاہ چار مربع ہوگی: اور اس کی اونچائی تین کیوبٹ ہوگی۔\n2۔ اور تم اس کے چاروں کونوں پر اس کے سینگ بنو گے: اس کے سینگ بھی اسی طرح ہوں گے، اور تم اسے پیتل سے ڈھانپنا گے۔\n3۔ اور اس کے برتن اس کی راکھ، بیلچے، اس کے حوالے، اس کے گوشت کے کانٹے اور اس کے آگ کے پین کو قبول کرنے کے لیے بناؤ گے: اس کے تمام برتن پیتل کے بنو گے۔\n4۔ اور تم اس کے لیے پیتل کا جال بناؤ گے؛ اور جال پر چار کونوں میں چار بریزن رنگ بناؤ گے۔\n5۔ اور تم اسے نیچے قربان گاہ کے کمپاس کے نیچے رکھو تاکہ جال قربان گاہ کے بیچ تک پہنچ جائے۔\n6۔ اور تم قربان گاہ کے لیے لاٹھیاں بنو گے، جو شیٹم لکڑی سے ہوں گے، اور ان پر پیتل لگاؤ گے۔\n7۔ اور لاٹھیاں انگوٹھیوں میں رکھی جائیں گی، اور لاٹھیاں قربان گاہ کے دونوں طرف ہوں گی، تاکہ اسے سنبھالا جا سکے۔\n8۔ تختوں سے کھوکھلا ہو جائے گا: جیسے تمہیں پہاڑ میں دکھایا گیا، ویسے ہی وہ بنائیں گے۔ {یہ تھا...: عبرانی۔ انہوں نے دکھایا\n9۔ اور تم خیمہ کے صحن کو بناؤ گے: جنوب کی طرف صحن کے لیے ایک طرف سو ہاتھ کی باریک لپٹی کی لٹکیاں ہوں گی:\n10۔ اور اس کے بیس ستون اور ان کے بیس ساکٹ پیتل کے ہوں گے؛ ستونوں کے کانٹے اور ان کے فلیٹس چاندی کے ہوں گے۔\n11۔ اسی طرح شمالی جانب لمبائی میں سو کیوبٹ لمبے لٹکیاں ہوں گی، اور اس کے بیس ستون اور ان کے بیس ساکٹ پیتل کے ہوں گے؛ ستونوں کے کانٹے اور ان کے چمکدار چاندی کے۔\n12۔ اور {کیونکہ} کہ صحن کی چوڑائی مغربی جانب پچاس کیوبٹ کے لٹکیاں ہوں گی: ان کے ستون دس اور ان کے ساکٹ دس۔\n13۔ اور مشرقی جانب صحن کی چوڑائی مشرق کی طرف پچاس کیوبٹ ہوگی۔\n14۔ دروازے کے ایک طرف کی لٹکیاں پندرہ کیوبٹ ہوں گی: ان کے ستون تین، اور ان کے ساکٹ تین۔\n15۔ اور دوسری طرف پندرہ {cubit} لٹکائے جائیں گے: ان کے تین ستون، اور ان کے ساکٹ تین۔\n16۔ اور دربار کے دروازے کے لیے بیس کیوبٹ کی لٹکی ہوگی، نیلا، جامنی، سرخ اور باریک لٹنی چادر، جو سلائی سے بنی ہوگی: اور ان کے ستون چار ہوں گے، اور ان کے ساکٹ چار۔\n17۔ صحن کے ارد گرد تمام ستون چاندی سے بھرے جائیں گے؛ ان کے کانٹے چاندی کے ہوں گے، اور ان کے ساکٹ پیتل کے۔\n18۔ صحن کی لمبائی سو کیوبٹ ہوگی، اور ہر جگہ چوڑائی پچاس، اور اونچائی پانچ کیوبٹ باریک الجھے ہوئے کپڑے اور ان کے ساکٹ پیتل کے ہوں گے۔ {پچاس...: عبرانی۔ پچاس بائی پچاس}\n19۔ تابوت کے تمام برتن، اس کی تمام خدمت میں، اور اس کے تمام پن، اور عدالت کے تمام پن، پیتل کے ہوں گے۔\n20۔ اور تم بنی اسرائیل کو حکم دو کہ وہ تمہیں روشنی کے لیے پیلا خالص تیل اور زیتون لاؤ، تاکہ چراغ ہمیشہ جلتا رہے۔ {جلانے کے لیے: عبرانی۔ اوپر چڑھنے کے لیے}\n21۔ بغیر پردے کے جماعت کے خیمے میں، جو گواہی کے سامنے ہے، ہارون اور اس کے بیٹے شام سے صبح تک خداوند کے سامنے حکم دیں گے: یہ ان کی نسلوں کے لیے بنی اسرائیل کی طرف سے ہمیشہ کے لیے ایک قانون ہوگا۔","1۔ اور اپنے بھائی ہارون کو، اور اس کے بیٹوں کو، اسرائیل کے بچوں میں سے اپنے پاس لے جاؤ، تاکہ وہ میری خدمت کاہن کے دفتر میں کرے، حتیٰ کہ ہارون، نداب اور ابیہو، الیعزر اور ایثمار، ہارون کے بیٹے۔\n2۔ اور تم اپنے بھائی ہارون کے لیے مقدس لباس بناؤ گے، جلال اور خوبصورتی کے لیے۔\n3۔ اور تم ان سب سے بات کرو گے جو دانا دل رکھتے ہیں، جنہیں میں نے حکمت کی روح سے بھر دیا ہے، تاکہ وہ ہارون کے کپڑے بنا کر اسے مقدس کریں، تاکہ وہ پادری کے دفتر میں میری خدمت کرے۔\n4۔ اور یہ وہ لباس ہیں جو وہ بنائیں گے؛ ایک بریسٹ پلیٹ، ایک ایفود، ایک لباس، اور ایک چوٹی دار کوٹ، ایک تاج اور ایک بیلٹ: اور وہ ہارون کے لیے مقدس لباس بنائیں گے، جو تمہارے بھائی اور اس کے بیٹوں کے لیے ہے، تاکہ وہ پادری کے دفتر میں میری خدمت کرے۔\n5۔ اور وہ سونا، نیلا، جامنی، سرخ اور عمدہ کتان لیں گے۔\n6۔ اور وہ ایفود کو سنہری، نیلا اور جامنی، سرخ اور باریک الجھے ہوئے کتان سے چالاکی سے بنائیں گے۔\n7۔ اس کے دونوں کندھے اس کے دو کناروں پر جڑے ہوں گے؛ اور {یوں} اسے جوڑ دیا جائے گا۔\n8۔ اور ایفود کا عجیب بیلٹ، جو {ہے} ہے، اس کے کام کے مطابق اسی کا ہوگا؛ {حتیٰ کہ} سنہری، {کے} نیلا، اور جامنی، اور سرخ رنگ، اور باریک ٹوئنڈ لینن۔ {تجسس: یا، کڑھائی شدہ}\n9۔ اور تم دو اونکس پتھر لے کر ان پر بنی اسرائیل کے نام دفن کرو:\n10۔ ان کے چھ نام ایک پتھر پر، اور {دوسرا} باقی چھ نام دوسرے پتھر پر، ان کی پیدائش کے مطابق۔\n11۔ پتھر پر کندہ کار کے کام سے، {جیسے نشان کی کندہ کاری ہوئی، تو دو پتھروں پر بنی اسرائیل کے ناموں کندہ کرو گے: انہیں سونے کے آؤچوں میں جڑا دو۔\n12۔ اور تم دو پتھر ایفود کے کندھوں پر رکھو {کیونکہ یہ بنی اسرائیل کی یادگار} کے پتھر ہیں: اور ہارون ان کے نام خداوند کے سامنے اپنے کندھوں پر ایک یادگار کے طور پر اٹھائے گا۔\n13۔ اور تم سونے سے اوچز کرو گے؛\n14۔ اور دو زنجیریں خالص سونے کی ہیں؛ پھولوں کا کام کرو، اور پھولوں کی زنجیریں زخموں سے باندھنا ہے۔\n15۔ اور تم فیصلے کی چادر چالاکی سے بناؤ گے؛ ایفود کے کام کے بعد تم اسے بناؤ گے؛ سنہری، نیلا، اور جامنی، اور سرخ اور باریک الجھے ہوئے کپڑوں کا، تم اسے بناؤ گے۔\n16. فور اسکوائر میں یہ {ہونا} ڈبل ہوگا؛ ایک اسپین {ہوگی} اس کی لمبائی کے برابر، اور ایک اسپین {ہوگا} اس کی چوڑائی کے برابر۔\n17۔ اور تم اس میں پتھروں کی سجاوٹیں رکھو گے، {حتیٰ کہ} چار قطاریں پتھروں کی: {پہلی} قطار {ہوگی} ایک سارڈیئس، ایک ٹوپاز، اور ایک کاربنکل: {یہ ہوگی} پہلی قطار ہوگی۔ {سیٹ...: عبوری۔ اس میں پتھر کی بھرائی بھرو} {سارڈیئس: یا، روبی}\n18۔ اور دوسری قطار میں زمرد، نیلم اور ہیرا ہوگا۔\n19۔ اور تیسری قطار میں ایک لیگور، ایک عقیق، اور ایک امیتھسٹ ہے۔\n20۔ اور چوتھی قطار میں ایک بیریل، ایک اونکس، اور ایک جاسپر ہے: یہ ان کے انکلوسنگ میں سونے کی طرح رکھے جائیں گے۔ {انکلوزنگز: عبدی۔ فلنگز}\n21۔ اور پتھر بنی اسرائیل کے ناموں کے ساتھ ہوں گے، بارہ، ان کے ناموں کے مطابق، {جیسے} نشان کی کندہ کاری؛ ہر ایک جس کا نام ہو، بارہ قبائل کے مطابق ہوگا۔\n22. اور تم سینے کی تختی پر گلدستوں کے سروں پر خالص سونے کی زنجیریں بناؤ گے۔\n23۔ اور تم سینے کی میز پر دو سونے کی انگوٹھیاں بنوانا ہے، اور دونوں انگوٹھیاں سینے کی تختی کے دونوں سروں پر رکھو۔\n24۔ اور تم دو سونے کی زنجیریں {جو سینے کی چادر کے سروں پر ہیں} میں دو سونے کی زنجیریں رکھو۔\n25. اور {دوسرے} دونوں ہاروں {زنجیر} کے دو سروں کو آپ دونوں اوچز میں باندھنا ہے، اور {انہیں} ایفود کے کندھوں پر اس کے سامنے رکھنا ہے۔\n26۔ اور تم دو سونے کی انگوٹھیاں بنو، اور انہیں سینے کی تختی کے دونوں سروں پر اس کے کنارے پر رکھو، جو ایفود کے اندر کی طرف ہے۔\n27۔ اور دو {اور} سونے کی انگوٹھیاں بناؤ گی، اور انہیں ایفود کے دونوں اطراف نیچے، اس کے سامنے کی طرف، اس کے {دیگر} جوڑے کے خلاف، ایفود کے عجیب بیلٹ کے اوپر رکھو گے۔\n28۔ اور وہ بریسٹ پلیٹ کو اس کی انگوٹھیوں سے ایفود کی انگوٹھیوں سے نیلے رنگ کے لیس سے باندھیں گے، تاکہ وہ ایفود کے عجیب و غریب بیلٹ کے اوپر ہو، اور سینہ بند ایفود سے آزاد نہ ہو۔\n29۔ اور ہارون اپنے دل پر فیصلوں کے سینے میں بنی اسرائیل کے نام اٹھائے گا، جب وہ مقدس {جگہ} میں جائے گا، تاکہ خداوند کے سامنے مسلسل یادگار ہو۔\n30۔ اور تم فیصلے کے سینے میں اوریم اور تھمم رکھو؛ اور وہ ہارون کے دل پر ہوں گے، جب وہ خداوند کے سامنے جائے گا: اور ہارون ہمیشہ اپنے دل پر بنی اسرائیل کا فیصلہ خداوند کے سامنے اٹھائے گا۔\n31۔ اور تم ایفود کی چادر کو نیلا کر دو گے۔\n32۔ اور اس کے اوپر ایک سوراخ ہوگا، اس کے بیچ میں: اس کے سوراخ کے گرد بنے ہوئے کام کی ایک بائنڈ ہوگی، جیسے یہ ہیبرجن کا سوراخ ہو، تاکہ وہ پھٹ نہ جائے۔\n33۔ اور اس کے کنارے پر تم انار {کے} نیلا، {کے} جامنی اور {سرخ کے} کے انار بناؤ گے، جو اس کے کنارے کے گرد ہوں گے؛ اور ان کے درمیان سنہری گھنٹیاں تھیں: {ہم: یا اسکرٹ}\n34۔ ایک سونے کی گھنٹی اور ایک انار، ایک سونے کی گھنٹی اور ایک انار، چادر کے کنارے پر۔\n35۔ اور ہارون کی ذمہ داری ہوگی کہ وہ خدمت کرے: اور اس کی آواز سنی جائے گی جب وہ خداوند کے سامنے مقدس مقام پر جائے گا، اور جب وہ باہر آئے گا، کہ وہ نہ مرے۔\n36۔ اور تم خالص سونے کی ایک پلیٹ بناؤ گے، اور اس پر قبر کرو گے، جیسے کسی نشان کی کندہ کاری ہو، خداوند کی پاکیزگی۔\n37۔ اور تم اسے نیلے لیس پر پہن لو، تاکہ یہ مائٹر پر ہو؛ یہ مائٹر کے اگلے حصے پر ہوگا۔\n38۔ اور یہ ہارون کے ماتھے پر ہوگا تاکہ ہارون مقدس چیزوں کی گناہ کو اٹھا سکے، جنہیں بنی اسرائیل اپنی تمام مقدس نعمتوں میں مقدس کریں گے؛ اور یہ ہمیشہ اس کی پیشانی پر ہوگا تاکہ وہ خداوند کے سامنے قبول کیے جا سکیں۔\n39۔ اور تم عمدہ کپڑے کی کڑھائی کرو گے، اور نفیس لینن کا میتر بناؤ گے، اور بیلٹ سلائی کے کام سے بناؤ گے۔\n40۔ اور ہارون کے بیٹوں کے لیے تم کوٹ بناؤ گے، اور ان کے لیے بیلٹ اور ٹوپیاں بناؤ گے، جلال اور خوبصورتی کے لیے۔\n41۔ اور تم انہیں اپنے بھائی ہارون اور اس کے بیٹوں پر رکھو گے؛ اور انہیں مسح کرو، مقدس کرو اور پاک کرو تاکہ وہ پادری کے عہدے میں میری خدمت کریں۔ {تقدیس...: عبرانی۔ ان کا ہاتھ بھر دو}\n42. اور تم انہیں ان کی برہنگی چھپانے کے لیے لینن کی پتلون پہناؤ گے؛ کمر سے لے کر رانوں تک پہنچیں گے: {ان کے...: عبرانی۔ ان کی برہنگی کا گوشت} {پہنچ: عبرانی۔ be}\n43۔ اور وہ ہارون اور اس کے بیٹوں پر ہوں گے، جب وہ جماعت کے خیمے میں آئیں گے، یا جب وہ مقدس مقام پر خدمت کے لیے قربان گاہ کے قریب آئیں گے؛ کہ وہ گناہ نہ اٹھائیں اور مر جائیں: یہ ہمیشہ کے لیے اس کے اور اس کی نسل کے لیے ایک حکم ہوگا۔","1۔ اور یہ وہ کام ہے جو تم ان کے ساتھ کرو گے تاکہ انہیں مقدس سمجھ سکوں، پادری کے دفتر میں میری خدمت کرو: ایک نوجوان بیل اور دو بے داغ مینڈھے لے لو،\n2۔ اور بغیر خمیر کی روٹی، اور بغیر خمیر کے کیک جو تیل سے خشک کیے گئے ہوں، اور بغیر خمیر کے تیل سے مسح شدہ ویفرز: گندم کے آٹے سے تم انہیں بناؤ گے۔\n3۔ اور انہیں ایک ٹوکری میں ڈال کر ٹوکری میں لے آؤ، بیل اور دو مینڈوں کے ساتھ۔\n4۔ اور ہارون اور اس کے بیٹوں کو تم جماعت کے خیمہ کے دروازے تک لے جا کر انہیں پانی سے دھو دینا۔\n5۔ اور تم کپڑے پہن کر ہارون پر کوٹ، ایفود کا لباس، ایفود اور سینہ پوش پہن کر اسے ایفود کے عجیب بیلٹ سے باندھنا:\n6۔ اور تم اس کے سر پر تاج پہناؤ گے، اور مقدس تاج اس پر رکھو گے۔\n7۔ پھر تم مسح کرنے والا تیل لے کر اس کے سر پر ڈال کر اسے مسح کرو۔\n8۔ اور تم اس کے بیٹوں کو لاؤ گے، اور ان پر کوٹ پہناؤ گے۔\n9۔ اور ہارون اور اس کے بیٹوں کو بیلٹ پہن کر ٹوپیاں پہن دو، اور پادری کا عہدہ ہمیشہ کے لیے ان کا ہوگا، اور ہارون اور اس کے بیٹوں کو مقدس کرو گے۔ {لکھیں: عببرانی۔ bind} {تقدیس: عبرانی۔ ہاتھ بھرو}\n10۔ اور تم ایک بیل کو جماعت کے خیمے کے سامنے لے آؤ گے، اور ہارون اور اس کے بیٹے بیل کے سر پر ہاتھ رکھیں گے۔\n11۔ اور تم خداوند کے سامنے بیل کو ذبح کرو گے، جماعت کے خیمہ کے دروازے کے ذریعے۔\n12۔ اور تم بیل کے خون سے لے کر اپنی انگلی سے قربان گاہ کے سینگوں پر رکھو، اور سارا خون قربان گاہ کے نیچے ڈال دو۔\n13۔ اور تم اندرونی حصے کو ڈھانپنے والی تمام چکنائی، اور جگر کے اوپر والی کال، اور دونوں گردے، اور ان پر موجود چکنائی لے کر قربان گاہ پر جلا دو۔ {کال: یہ اناٹومی اور عبرانی ڈاکٹروں کے مطابق درمیانی حصہ لگتا ہے}\n14۔ لیکن بیل کا گوشت، اس کی کھال، اور اس کی گوبر کو تم بغیر کیمپ کے آگ میں جلاؤ گے: یہ گناہ کی قربانی ہے۔\n15۔ تم ایک مینڈھا بھی لے لو؛ اور ہارون اور اس کے بیٹے مینڈھے کے سر پر ہاتھ رکھیں گے۔\n16۔ اور تم مینڈھے کو مارو گے، اور اس کا خون لے کر قربان گاہ پر چھڑک دو گے۔\n17۔ اور تم مینڈھے کو ٹکڑوں میں کاٹ دو، اس کے اندر اور اس کی ٹانگیں دھو دو، اور انہیں اس کے ٹکڑوں اور سر پر رکھ دو۔ {انہ: یا، اوپر}\n18۔ اور تم پورا مینڈھا قربان گاہ پر جلا دو: یہ خداوند کے لیے ایک سلائی ہوئی قربانی ہے: یہ ایک میٹھا ذائقہ ہے، جو آگ سے خداوند کے لیے پیش کی گئی ہے۔\n19۔ اور تم دوسرا مینڈھا لے لو؛ اور ہارون اور اس کے بیٹے مینڈھے کے سر پر ہاتھ رکھیں گے۔\n20۔ پھر تم مینڈھے کو مارو، اس کا خون لے لو، اور اسے ہارون کے دائیں کان کی نوک، اس کے بیٹوں کے دائیں کان کی نوک، ان کے دائیں ہاتھ کے انگوٹھے پر، ان کے دائیں پاؤں کی بڑی انگلی پر رکھو، اور خون کو قربان گاہ کے ارد گرد چھڑک دو۔\n21. اور تم اس خون سے جو قربان گاہ پر ہے، اور مسح کے تیل سے بھی، اور ہارون پر، اس کے کپڑوں پر، اس کے بیٹوں پر، اور اس کے بیٹوں کے کپڑوں پر چھڑک دو، اور وہ مقدس ہو جائے گا، اس کے کپڑے، اس کے بیٹے اور اس کے بیٹوں کے لباس اس کے ساتھ۔\n22۔ اور تم مینڈھے سے چربی اور کمر، اور اندر کی چربی اور جگر کے اوپر، دو گردے، اور ان پر موجود چربی اور دائیں کندھے سے لے لو؛ کیونکہ یہ {ہے} تقدیس کا مینڈھا:\n23۔ اور ایک روٹی کی روٹی، ایک تیل لگی روٹی کا کیک، اور ایک ویفر اس بے خمیر روٹی کی ٹوکری سے جو {خدا} کے سامنے ہے:\n24۔ اور تم سب کچھ ہارون کے ہاتھوں میں اور اس کے بیٹوں کے حوالے کر دو؛ اور انہیں خداوند کے سامنے لہرانے کی قربانی کے طور پر لہرانا ہوگا۔ {لہراتا ہے: یا، ادھر ادھر ہلتا ہے}\n25۔ اور تم انہیں ان کے ہاتھوں سے قبول کرو گے، اور انہیں قربان گاہ پر جلاؤ گے، ایک میٹھی قربانی کے طور پر، خداوند کے سامنے ایک میٹھا ذائقہ کے طور پر: یہ آگ سے خداوند کے لیے پیش کی گئی نذرانہ ہے۔\n26۔ اور تم ہارون کی تقدیس کے مینڈھے کے سینے کو لے کر اسے خداوند کے سامنے لہرانے کی پیشکش کے طور پر لہرو گے: اور یہ تمہارا حصہ ہوگا۔\n27۔ اور تم لہرانے والی قربانی کے سینے کو مقدس کرو گے، اور اس نذرانہ کے کندھے کو، جو لہرایا جاتا ہے اور جو اوپر اٹھایا جاتا ہے، تقدیس کے مینڈھے کی، {حتی} وہ {جو {ہے} ہارون کے لیے ہے، اور {وہ} جو اس کے بیٹوں کے لیے ہے:\n28۔ اور یہ ہمیشہ کے لیے بنی اسرائیل کی طرف سے ایک مجسمے کے مطابق ہارون اور اس کے بیٹوں کی ہوگی، کیونکہ یہ ایک قربانی ہے: اور یہ بنی اسرائیل کی طرف سے ان کی صلح کی قربانیوں کی قربانی کی قربانی ہوگی، {حتیٰ کہ} ان کی خداوند کے لیے نذرانہ بھی۔\n29۔ اور ہارون کے مقدس لباس اس کے بعد اس کے بیٹوں کے ہوں گے، جو ان میں مسح کیے جائیں گے اور ان میں مقدس ہوں گے۔\n30۔ {اور} وہ بیٹا جو اس کی جگہ پادری ہے، انہیں سات دن پر رکھے گا، جب وہ جماعت کے خیمہ میں آ کر مقدس {جگہ} میں خدمت کرے گا۔ {وہ بیٹا: عبرانی۔ اپنے بیٹوں میں سے وہ}\n31۔ اور تم تقدیس کے مینڈھے کو لے کر مقدس جگہ میں اس کے جسم کو جلاؤ گے۔\n32۔ اور ہارون اور اس کے بیٹے مینڈھے کا گوشت کھائیں گے، اور وہ روٹی جو ٹوکری میں ہے، جماعت کے خیمہ کے دروازے کے پاس۔\n33۔ اور وہ وہ چیزیں کھائیں گے جن سے کفارہ کیا گیا تھا، انہیں مقدس اور پاک کرنے کے لیے: لیکن اجنبی ان چیزوں کو نہیں کھائے گا کیونکہ وہ مقدس ہیں۔\n34۔ اور اگر تقدیس کے گوشت یا روٹی کا گوشت صبح تک رہے، تو باقی حصہ آگ سے جلا دو: اسے نہیں کھایا جائے گا کیونکہ یہ مقدس ہے۔\n35۔ اور یہی تم ہارون اور اس کے بیٹوں کے ساتھ کرو گے، جیسا کہ میں نے تمہیں حکم دیا ہے: سات دن تک انہیں مقدس کرو گے۔\n36۔ اور تم ہر روز گناہ کی قربانی کے طور پر ایک بیل پیش کرو گے، اور جب تم نے اس کا کفارہ دے گا تو قربان گاہ کو پاک کرو گے، اور اسے مسح کرو گے تاکہ اسے پاک کر سکو۔\n37۔ سات دن تم قربان گاہ کے لیے کفارہ دو گے، اور اسے مقدس کرو گے؛ اور یہ سب سے مقدس قربان گاہ ہوگی: جو بھی قربان گاہ کو چھوئے گا وہ مقدس ہوگا۔\n38. اب یہ وہ ہے جو تم قربان گاہ پر پیش کرو گے؛ پہلے سال کے دو بکری دن بہ دن مسلسل آتے رہتے ہیں۔\n39۔ وہ ایک بھیڑ جو تم صبح پیش کرو گے؛ اور دوسرا برہ جو تم برابر پیش کرو گے:\n40۔ اور ایک بھیڑ کے ساتھ آٹا کا دسواں حصہ ایک ہین تیل کے چوتھے حصے کے ساتھ ملایا گیا؛ اور شراب کے ہین کا چوتھا حصہ {ایک مشروب کی پیشکش} کے لیے۔\n41۔ اور دوسرا برہ بھی صبح کے گوشت کی نذرانہ اور اس کی نذرانہ کے مطابق، میٹھے ذائقے کے طور پر، جو آگ میں خداوند کے لیے پیش کیا جائے گا، پیش کرو گے۔\n42. {یہ تمہاری نسلوں تک ایک مسلسل جلنے والی قربانی رہے گی {جماعت کے خیمہ کے دروازے پر} خداوند کے سامنے: جہاں میں تم سے ملوں گا، وہاں تم سے بات کرنے کے لیے۔\n43۔ اور وہاں میں اسرائیل کے بچوں سے ملوں گا، اور {خیمہ خانہ} میرے جلال سے پاک ہوگا۔ {خیمہ خانہ: یا، اسرائیل}\n44۔ اور میں جماعت کے خیمے اور قربان گاہ کو مقدس کروں گا: میں ہارون اور اس کے بیٹوں کو بھی مقدس کروں گا، تاکہ وہ پادری کے دفتر میں میری خدمت کریں۔\n45۔ اور میں بنی اسرائیل کے درمیان رہوں گا، اور ان کا خدا بنوں گا۔\n46۔ اور وہ جان جائیں گے کہ میں خداوند ان کا خدا ہوں، جس نے انہیں مصر کی سرزمین سے نکالا تاکہ میں ان کے درمیان رہ سکوں: میں ان کا خدا ہوں۔","1۔ اور تم ایک قربان گاہ بناؤ گے جس پر لوبان جلانے کے لیے ہے: {شٹم} لکڑی سے تم اسے بناؤ گے۔\n2۔ ایک کیوبٹ اس کی لمبائی کے برابر اور ایک کیوبٹ اس کی چوڑائی کے برابر ہو؛ یہ چار مربع ہوگا: اور اس کی اونچائی کے برابر دو کیوبٹ ہوں گے: اس کے سینگ بھی اسی کے ہوں گے۔\n3۔ اور تم اسے خالص سونے سے ڈھانپنا، اس کے اوپر، اس کے اطراف اور اس کے سینگ رکھو؛ اور تم اس کے گرد سونے کا تاج بناؤ گے۔ {اوپر: عبرانی۔ چھت} {سائیڈز: عبرانی۔ دیواریں}\n4۔ اور اس کے تاج کے نیچے، اس کے دو کونوں سے، اس کے دونوں طرف دو سونے کی انگوٹھیاں بنائیں گے؛ اور وہ جگہیں ہوں گی جہاں لاٹھیاں اسے اٹھا سکیں۔ {کونے: عبوری۔ پسلیاں}\n5۔ اور تم شتم کی لکڑی کی لاٹھیاں بناؤ، اور ان پر سونا لگاؤ۔\n6۔ اور تم اسے اس پردے کے سامنے رکھو گے جو گواہی کے صندوق کے پاس ہے، اس رحمت کی نشست کے سامنے جو گواہی کے اوپر ہے، جہاں میں تم سے ملوں گا۔\n7۔ اور ہارون ہر صبح اس پر میٹھا لوبان جلائے گا: جب وہ چراغ سجائے گا تو اس پر لوبان جلائے گا۔ {میٹھا دھوبتیا: عبوری۔ مصالحوں کی خوشبو}\n8۔ اور جب ہارون صبح کے چراغ جلائے گا، تو وہ اس پر دھوپ جلائے گا، جو تمہاری نسلوں تک خداوند کے سامنے ہمیشہ رہنے والی خوشبو ہوگی۔ {lighteth: or setteth up: Hebrew. اوپر جانے کی وجہ سے} {جفت پر: عبرانی۔ دونوں شاموں کے درمیان}\n9۔ تم اس پر کوئی غیر معمولی لوبان پیش نہیں کرو، نہ جلی ہوئی قربانی، نہ گوشت کی قربانی؛ نہ ہی تم اس پر شراب کی قربانی ڈالو گے۔\n10۔ اور ہارون سال میں ایک بار اس کے سینگوں پر کفارہ کے خون سے کفارہ کرے گا: سال میں ایک بار وہ آپ کی نسلوں میں اس پر کفارہ کرے گا: یہ خداوند کے لیے سب سے مقدس ہے۔\n11۔ اور خداوند نے موسیٰ سے کہا،\n12۔ جب تم بنی اسرائیل کی رقم ان کی تعداد کے حساب سے لے لو، تو وہ ہر آدمی کو اس کی جان کے لیے خداوند کے لیے فدیہ دیں گے، جب تم ان کی گنتی کرو گے؛ کہ ان میں کوئی آفت نہ ہو، جب {تو} انہیں شمار کرتا ہے۔ {ان کا نمبر: عبرانی۔ وہ جنہیں نمبر دیا جانا ہے}\n13۔ یہ وہ ہر شخص کو جو ان میں سے گزرے گا، مقدس مقام کے شیکل کے بعد آدھا شیکل دیں گے: (ایک شیکل بیس گرہ ہے:) آدھا شیکل خداوند کی قربانی ہوگی۔\n14۔ جو بھی ان میں سے گزرے گا، جو بیس سال یا اس سے زیادہ عمر کے ہوں، خداوند کے سامنے نذرانہ پیش کرے گا۔\n15۔ امیر زیادہ نہیں دیں گے، اور غریب آدھا شیکل سے کم نہیں دیں گے، جب {و} خداوند کو قربانی دیں تاکہ آپ کی جانوں کا کفارہ ہو۔ {مزید دیں: عبرانی۔ ضرب دیں} {کم دیں: عبرانی۔ diminish}\n16۔ اور تم بنی اسرائیل کے کفارے کے پیسے لو گے، اور اسے جماعت کے خیمے کی خدمت کے لیے مقرر کرو گے؛ تاکہ یہ بنی اسرائیل کے لیے خداوند کے سامنے ایک یادگار ہو، تاکہ تمہاری روحوں کے لیے کفارہ بنایا جا سکے۔\n17۔ اور خداوند نے موسیٰ سے کہا،\n18۔ تم پیتل کا پیتل کا لیور بھی بناؤ گے، اور اس کے پاؤں کو بھی پیتل سے دھونا ہے، اور اسے جماعت کے خیمے اور قربان گاہ کے درمیان رکھو گے، اور اس میں پانی ڈالو گے۔\n19۔ کیونکہ ہارون اور اس کے بیٹے وہاں اپنے ہاتھ اور پاؤں دھوئیں گے:\n20۔ جب وہ جماعت کے خیمے میں جائیں تو پانی سے نہائیں تاکہ وہ نہ مریں؛ یا جب وہ قربان گاہ کے قریب آئیں تاکہ خدمت کریں، تاکہ آگ سے خداوند کے لیے پیش کی گئی نذرانہ:\n21۔ تو وہ اپنے ہاتھ اور پاؤں دھوئیں گے، تاکہ وہ نہ مریں: اور یہ ان کے لیے ہمیشہ کے لیے ایک مجسمہ رہے گا، {حتیٰ کہ} اس کے لیے اور اس کی نسل کے لیے بھی۔\nمزید برآں، خداوند نے موسیٰ سے کہا،\n23۔ تم اپنے پاس پانچ سو شیکل خالص مرہ کے اور آدھی میٹھی دار چینی کے مصالحے بھی لے آؤ، {حتیٰ کہ} دو سو پچاس شیکل، اور میٹھے کلامس کے دو سو پچاس شیکل،\n24۔ اور کاسیا کے پانچ سو شیکل، مقدس مقام کے شیکل کے بعد، اور تیل زیتون آن ہن:\n25۔ اور تم اسے مقدس مرہم کا تیل بنا دو، دوا ساز کے فن کے بعد مرہم کا مرکب: یہ مقدس مسح کا تیل ہوگا۔ {دوا ساز: یا، پرفیومر}\n26۔ اور تم جماعت کے خیمے اور گواہی کے صندوق کو اسی سے مسح کرو گے،\n27۔ اور میز اور اس کے تمام برتن، اور شمعدان اور اس کے برتن، اور لوبان کا قربان گاہ،\n28۔ اور جلانے والی قربان گاہ جس میں اس کے تمام برتن، لاور اور اس کے پاؤں شامل ہیں۔\n29۔ اور تم انہیں پاک کرو تاکہ وہ سب سے زیادہ مقدس ہوں: جو بھی انہیں چھوئے گا وہ مقدس ہوگا۔\n30۔ اور تم ہارون اور اس کے بیٹوں کو مسح کرو گے، اور انہیں مقدس کرو گے تاکہ وہ پادری کے دفتر میں میری خدمت کریں۔\n31۔ اور تم بنی اسرائیل سے کہو کہ، یہ میرے لیے تمہاری نسلوں کے لیے مقدس مسح کا تیل ہوگا۔\n32. انسان کے گوشت پر نہ ڈالا جائے گا، نہ ہی آپ اس جیسا کوئی اور بنائیں گے، جب وہ تیار ہو جائے گا: یہ {مقدس} ہے، {اور} یہ آپ کے لیے مقدس ہوگا۔\n33۔ جو بھی اس جیسا کوئی مرکب کرے گا، یا جو اس کا {کبھی} کسی اجنبی پر لگائے گا، اسے اپنے لوگوں سے بھی کاٹ دیا جائے گا۔\n34۔ اور خداوند نے موسیٰ سے کہا، اپنے پاس میٹھے مصالحے، اسٹیکٹ، اونخا اور گلبانم لے آؤ؛ {یہ} میٹھے مصالحے خالص لوبان کے ساتھ: ہر ایک کا ایک جیسا {وزن} ہوگا:\n35۔ اور تم اسے خوشبو بنا دو، دوا ساز کے فن کے بعد ایک مٹھائی، ایک مضبوط، پاکیزہ {اور} مقدس: {معتدل...: عبرانی۔ نمکین\n36۔ اور تم اس کا کچھ بہت چھوٹا حصہ مارو، اور اسے جماعت کے خیمہ میں گواہی کے سامنے رکھو، جہاں میں تم سے ملوں گا: یہ تمہارے لیے بہت مقدس ہوگا۔\n37۔ اور جو خوشبو تم بناؤ گے، تم اپنے لیے اس کی ساخت کے مطابق نہیں بنا سکتے: وہ تمہارے لیے خداوند کے لیے مقدس ہوگی۔\n38۔ جو بھی ایسا کرے گا، اس کی خوشبو محسوس کرے گا، اسے اپنے لوگوں سے بھی کاٹ دیا جائے گا۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ دیکھیں، میں نے یہوداہ قبیلے کے یوری کے بیٹے بیزلیل کو نام سے پکارا ہے:\n3۔ اور میں نے اسے خدا کی روح سے بھر دیا ہے، حکمت، فہم میں، علم میں، اور ہر قسم کی کاریگری میں،\n4۔ چالاکی سے کام کرنا، سونا، چاندی اور پیتل میں کام کرنا،\n5۔ پتھر کاٹنے، انہیں لگانے میں، اور لکڑی کی کندہ کاری میں ہر قسم کی کاریگری میں کام کرنا۔\n6۔ اور میں نے اس کے ساتھ اہولیاب دیا ہے، جو اہساماک کا بیٹا ہے، دان قبیلے سے: اور تمام دانا دلوں کے دلوں میں میں نے حکمت رکھی ہے، تاکہ وہ وہ سب کچھ کر سکیں جو میں نے تمہیں حکم دیا ہے؛\n7۔ جماعت کا خیمہ خانہ، اور گواہی کا صندوق، اور اس پر موجود رحمت کی نشست، اور خیمہ گاہ کا تمام فرنیچر، {فرنیچر: عبرانی۔ vessels}\n8۔ اور میز اور اس کا فرنیچر، اور خالص موم بتی جس میں اس کا سارا فرنیچر ہے، اور لوبان کا مذبح، {فرنیچر: عبرانی۔ vessels}\n9۔ اور جلانے والی قربان گاہ جس میں اس کا سارا فرنیچر، لیور اور اس کا پاؤں شامل ہے، {فرنیچر: عبرانی۔ vessels}\n10۔ اور خدمت کے کپڑے، اور مقدس لباس ہارون کاہن کے لیے، اور اس کے بیٹوں کے لباس، تاکہ وہ پادری کے دفتر میں خدمت کرے،\n11۔ اور مقدس {جگہ} کے لیے مسح کا تیل، اور میٹھا لوبان ہوگا: جو کچھ میں نے تمہیں حکم دیا ہے اس کے مطابق وہ کریں گے۔\n12۔ اور خداوند نے موسیٰ سے کہا،\n13۔ تو بنی اسرائیل سے بھی کہہ کر کہو، یقینا میرے سبت تم نبھاؤ گے: کیونکہ یہ تمہارے اور میرے درمیان تمہاری نسلوں تک ایک نشانی ہے؛ تاکہ تم جان سکو کہ میں وہ خداوند ہوں جو تمہیں پاک کرتا ہے۔\n14۔ لہٰذا تم سبت کی پابندی کرو گے؛ کیونکہ یہ تمہارے لیے مقدس ہے: جو بھی اسے ناپاک کرے گا اسے ضرور قتل کر دیا جائے گا؛ کیونکہ جو بھی وہاں کوئی کام کرے گا، اس کی روح اپنی قوم میں سے کاٹ دی جائے گی۔\n15۔ چھ دن کام کیا جا سکتا ہے؛ لیکن ساتویں میں آرام کا سبت ہے، جو خداوند کے لیے مقدس ہے: جو بھی سبت کے دن کوئی کام کرے گا، اسے ضرور موت دی جائے گی۔ {مقدس: عبرانی۔ مقدس مقام}\n16۔ اسی لیے بنی اسرائیل سبت کی پاسداری کریں گے، اور اپنی نسلوں تک سبت کی پابندی کریں گے، {کیونکہ} ایک دائمی عہد ہے۔\n17. یہ {ہے} میرے اور بنی اسرائیل کے درمیان ہمیشہ کے لیے ایک نشانی ہے: {چھ} دنوں میں خداوند نے آسمان اور زمین بنائے، اور ساتویں دن اس نے آرام کیا اور تازہ دم ہوا۔\n18۔ اور اس نے موسیٰ کو دی، جب اس نے کوہ سینا پر اس سے بات چیت ختم کی، دو گواہی کی میزیں، پتھر کی تختیں، جو خدا کی انگلی سے لکھی گئی تھیں۔","1۔ اور جب لوگوں نے دیکھا کہ موسیٰ پہاڑ سے اترنے میں دیر کر رہا ہے، تو لوگ ہارون کے پاس جمع ہوئے اور کہا، اوپر، ہمیں خدا بناؤ، جو ہمارے آگے جائیں گے؛ کیونکہ {جہاں تک} اس موسیٰ کا تعلق ہے، وہ شخص جس نے ہمیں مصر کی سرزمین سے نکالا، ہمیں معلوم نہیں تھا کہ اس کا کیا ہوا۔\n2۔ اور ہارون نے ان سے کہا، وہ سنہری بالیاں توڑ دو جو تمہاری بیویوں، بیٹوں اور بیٹیوں کے کانوں میں ہیں، اور انہیں میرے پاس لے آؤ۔\n3۔ اور سب لوگ اپنے کانوں میں لگے سنہری بالیاں توڑ کر ہارون کے پاس لے آئے۔\n4۔ اور اس نے ان کے ہاتھوں سے انہیں قبول کیا، اور اسے ایک کندہ کاری کے اوزار سے بنایا، جب اس نے اسے پگھلا ہوا بچھڑا بنایا: اور انہوں نے کہا، اے اسرائیل، یہ تمہارے خدا ہیں، جنہوں نے تمہیں مصر کی سرزمین سے نکالا۔\n5. اور جب ہارون نے اسے دیکھا، تو اس نے اس کے سامنے ایک قربان گاہ بنائی؛ اور ہارون نے اعلان کیا اور کہا، کل خداوند کے لیے ایک ضیافت ہے۔\n6۔ اور وہ صبح سویرے اٹھے، جلانے کی قربانیاں پیش کیں، اور صلح کی قربانیاں لائی؛ اور لوگ کھانے اور پینے کے لیے بیٹھ گئے، اور کھیلنے کے لیے اٹھ کھڑے ہوئے۔\n7۔ اور خداوند نے موسیٰ سے کہا، جاؤ، نیچے اتر جاؤ؛ کیونکہ تمہارے لوگ، جنہیں تم مصر کی سرزمین سے لائے، نے خود کو بگاڑ دیا ہے:\n8۔ وہ جلدی سے اس راستے سے ہٹ گئے جس کا میں نے انہیں حکم دیا تھا: انہوں نے انہیں پگھلا ہوا بچھڑا بنا دیا، اس کی عبادت کی، اور اس کے لیے قربانی دی، اور کہا، اے اسرائیل، یہ تمہارے خدا ہیں، جنہوں نے تمہیں مصر کی سرزمین سے نکالا۔\n9۔ اور خداوند نے موسیٰ سے کہا، میں نے اس قوم کو دیکھا ہے، اور دیکھو، یہ ایک ضدی قوم ہے:\n10۔ اب مجھے چھوڑ دو، تاکہ میرا غصہ ان پر بھڑکے، اور میں انہیں نگل سکوں: اور میں تمہیں ایک عظیم قوم بناؤں گا۔\n11۔ اور موسیٰ نے خداوند اپنے خدا سے دعا کی اور کہا، اے خداوند، تیری قوم پر غصہ کیوں بھڑک رہا ہے، جنہیں تو نے مصر کی سرزمین سے بڑی طاقت اور طاقتور ہاتھ سے نکالا ہے؟ {خداوند: عبرانی خداوند کا چہرہ}\n12۔ مصریوں نے کیوں بات کی اور کہیں، کیونکہ اس نے انہیں مصیبت کے لیے نکالا، پہاڑوں میں مارا، اور زمین سے کھا گیا؟ اپنے شدید غصے سے منہ موڑ لو، اور اپنے لوگوں کے خلاف اس برائی پر توبہ کرو۔\n13۔ ابراہیم، اسحاق اور اسرائیل کو یاد رکھو، اپنے بندوں کو، جن سے تم نے اپنی جان سے سلام کیا، اور ان سے کہا، میں تمہاری نسل کو آسمان کے ستاروں کی طرح بڑھاؤں گا، اور یہ ساری زمین جس کا میں نے ذکر کیا ہے، تمہاری نسل کو دوں گا، اور وہ ہمیشہ کے لیے اس کے وارث رہیں گے۔\n14۔ اور خداوند نے اس برائی سے توبہ کی جو اس نے اپنے لوگوں کے ساتھ کرنے کا سوچا تھا۔\n15۔ اور موسیٰ مڑا اور پہاڑ سے نیچے آیا، اور گواہی کی دو میزیں {اس کے ہاتھ میں} تھیں: دونوں طرف لکھی ہوئی میزیں {تھیں}؛ ایک طرف اور دوسری طرف وہ لکھ رہے تھے۔\n16۔ اور یہ میزیں خدا کا کام تھیں، اور تحریر خدا کی تحریر تھی، جو میزوں پر کندہ تھی۔\n17۔ اور جب یشوع نے لوگوں کی آواز سنی جو وہ چیخ رہے تھے، تو اس نے موسیٰ سے کہا، {کیمپ میں جنگ کی آواز ہے}۔\n18۔ اور اس نے کہا، {یہ ان لوگوں کی آواز نہیں ہے جو} طاقت کے لیے پکار رہے ہیں، نہ ہی {یہ} ان کی آواز ہے جو مغلوب ہونے کے لیے پکار رہے ہیں: {لیکن} ان {جو} گاتے ہیں ان کی آواز جو میں سنتا ہوں۔ {ہونا...: عبرانی۔ کمزوری}\n19۔ اور جیسے ہی وہ کیمپ کے قریب پہنچا، اس نے بچھڑا اور رقص دیکھا: اور موسیٰ کا غصہ بڑھ گیا، اس نے میزیں اپنے ہاتھوں سے پھینک دیں اور انہیں پہاڑ کے نیچے توڑ دیا۔\n20۔ اور اس نے وہ بچھڑا لیا جو انہوں نے بنایا تھا، اسے آگ میں جلا دیا، اسے پیس کر پاؤڈر بنایا، اور اسے پانی پر تنکا ڈالا، اور بنی اسرائیل کو اس کا پانی پلایا۔\n21۔ اور موسیٰ نے ہارون سے کہا، ان لوگوں نے تمہارے ساتھ کیا کیا کہ تم نے ان پر اتنا بڑا گناہ کیا؟\n22۔ اور ہارون نے کہا، میرے رب کا غصہ نہ بڑھے: تم لوگوں کو جانتے ہو کہ وہ شرارت پر مصر ہیں۔\n23۔ کیونکہ انہوں نے مجھ سے کہا، ہمیں خدا بنا دو، جو ہمارے سامنے آئیں گے: کیونکہ اس موسیٰ کے بارے میں، جس نے ہمیں مصر کی سرزمین سے نکالا، ہمیں معلوم نہیں تھا کہ اس کا کیا ہوا۔\n24۔ اور میں نے ان سے کہا، جس کے پاس سونا ہے، وہ اسے توڑ دے۔ تو انہوں نے مجھے دے دیا: پھر میں نے اسے آگ میں پھینکا، اور وہاں ایک بچھڑا نکلا۔\n25۔ اور جب موسیٰ نے دیکھا کہ لوگ {ننگا} ہیں؛ (کیونکہ ہارون نے انہیں ان کے دشمنوں میں شرمندگی کے لیے ننگا کر دیا تھا:) {ان کے دشمن: عبرانی۔ جو ان کے خلاف اٹھے}\n26۔ پھر موسیٰ کیمپ کے دروازے پر کھڑا ہوا اور کہا، خداوند کی طرف کون ہے؟ {اسے آنے دو} میرے پاس۔ اور لاوی کے تمام بیٹے اس کے سامنے جمع ہو گئے۔\n27۔ اور اس نے ان سے کہا، خداوند اسرائیل کے خدا نے یوں فرمایا، ہر آدمی کی تلوار اس کے پاس رکھو، {اور} پورے کیمپ میں دروازے سے دروازے تک جاؤ، اور ہر آدمی، اس کا بھائی، ہر ساتھی، اور ہر اس کے پڑوسی کو قتل کرو۔\n28۔ اور لاوی کے بچوں نے موسیٰ کے کلام کے مطابق کیا: اور اس دن تقریبا تین ہزار آدمی مارے گئے۔\n29۔ کیونکہ موسیٰ نے کہا تھا، آج خداوند کے لیے خود کو وقف کرو، حتیٰ کہ ہر انسان اپنے بیٹے اور اپنے بھائی کے لیے بھی؛ تاکہ وہ آج تمہیں برکت عطا کرے۔ {موسیٰ کے لیے...: یا، اور موسیٰ نے کہا، آج خداوند کے لیے خود کو وقف کرو، کیونکہ ہر انسان اپنے بھائی کے خلاف رہا ہے، وغیرہ} {تقدیس...: عبرانی۔ اپنے ہاتھ بھر دو}\n30۔ اور کل ایسا ہوا کہ موسیٰ نے لوگوں سے کہا، تم نے بڑا گناہ کیا ہے: اور اب میں خداوند کے پاس جاؤں گا؛ شاید میں تمہارے گناہ کا کفارہ دوں گا۔\n31۔ اور موسیٰ خداوند کے پاس واپس آیا اور کہا، اے یہ لوگ بہت بڑا گناہ کر چکے ہیں، اور انہیں سونے کے دیوتا بنا لیا ہے۔\n32. پھر بھی، اگر تم ان کے گناہ کو معاف کرنا چاہو-؛ اور اگر نہیں، تو مجھے اپنی لکھی ہوئی کتاب سے مٹا دو۔\n33۔ اور خداوند نے موسیٰ سے کہا، جس نے میرے خلاف گناہ کیا ہے، میں اسے اپنی کتاب سے مٹا دوں گا۔\n34۔ لہٰذا اب جاؤ، لوگوں کو اس جگہ لے جاؤ جس کے بارے میں میں نے تم سے بات کی ہے: دیکھو، میرا فرشتہ تمہارے سامنے جائے گا، لیکن جب میں آؤں گا تو ان پر ان کا گناہ نازل کروں گا۔\n35۔ اور خداوند نے لوگوں کو تنگ کیا، کیونکہ انہوں نے بچھڑا بنایا، جو ہارون نے بنایا۔","1۔ اور خداوند نے موسیٰ سے فرمایا، چلے جاؤ، اور وہ لوگ جو تم نے مصر کی سرزمین سے نکالے ہیں، اس زمین کی طرف جس کی میں نے ابراہیم، اسحاق اور یعقوب سے قسم کھائی ہے، کہتا ہوں، میں اسے تیری نسل کو دوں گا:\n2۔ اور میں تمہارے سامنے ایک فرشتہ بھیجوں گا؛ اور میں کنعانی، اموری، حتی، اور پریزی، حوی، اور یبوسیت کو نکالوں گا:\n3۔ دودھ اور شہد سے بہنے والی زمین پر: کیونکہ میں تمہارے درمیان اوپر نہیں جاؤں گا؛ کیونکہ تم ایک ضدی قوم ہو، ورنہ میں تمہیں راستے میں نگل جاؤں گا۔\n4۔ اور جب لوگوں نے یہ بری خبر سنی تو وہ ماتم کرنے لگے: اور کسی نے اس کے زیورات نہیں پہنے۔\n5۔ کیونکہ خداوند نے موسیٰ سے کہا تھا، بنی اسرائیل سے کہو، تم ضدی قوم ہو: میں ایک لمحے میں تمہارے درمیان آؤں گا اور تمہیں کھا جاؤں گا، تو اب اپنے زیورات اپنے سے اتار دو، تاکہ میں جان سکوں کہ تمہارے ساتھ کیا کرنا ہے۔\n6۔ اور بنی اسرائیل نے کوہ حرب کے پاس اپنے زیورات اتار دیے۔\n7۔ اور موسیٰ نے خیمہ گاہ لیا، اور اسے کیمپ سے دور کھڑا کیا اور اسے جماعت کا خیمہ کہا۔ اور ایسا ہوا کہ {کہ} ہر وہ شخص جو خداوند کی تلاش میں تھا، جماعت کے خیمہ میں چلا گیا، جو {کیمپ کے بغیر} تھا۔\n8۔ اور ایسا ہوا جب موسیٰ خیمہ گاہ میں گیا، {کہ} سب لوگ کھڑے ہو گئے، اور ہر آدمی اپنے خیمے کے دروازے پر کھڑے ہو گئے، اور موسیٰ کی دیکھ بھال کی، یہاں تک کہ وہ خیمہ میں چلا گیا۔\n9۔ اور یہ ہوا، جب موسیٰ خیمہ میں داخل ہوا، دھندلا ستون نیچے آیا، اور خیمہ گاہ کے دروازے پر کھڑا ہو گیا، اور {خدا} نے موسیٰ سے بات کی۔\n10۔ اور سب لوگوں نے دیکھا کہ بادلوں والا ستون خیمہ گاہ کے دروازے پر کھڑا ہے: اور سب لوگ اٹھ کھڑے ہوئے اور عبادت کی، ہر آدمی اپنے خیمے کے دروازے پر۔\n11۔ اور خداوند نے موسیٰ سے آمنے سامنے بات کی، جیسے انسان اپنے دوست سے بات کرتا ہے۔ اور وہ دوبارہ کیمپ میں مڑ گیا: لیکن اس کا خادم یشوع، نون کا بیٹا، جو ایک نوجوان تھا، خیمہ گاہ سے باہر نہیں نکلا۔\n12۔ اور موسیٰ نے خداوند سے کہا، دیکھو، تو مجھ سے کہتا ہے، اس قوم کو اوپر لے آؤ، اور تم نے مجھے یہ نہیں بتایا کہ تم میرے ساتھ کس کو بھیجو گے۔ پھر بھی تم نے کہا، میں تمہیں نام سے جانتا ہوں، اور تم نے میری نظر میں بھی فضل پایا ہے۔\n13۔ اب میں تم سے دعا کرتا ہوں، اگر میں نے تیری نظر میں فضل پایا ہے، تو اب مجھے اپنا راستہ دکھاؤ، تاکہ میں تمہیں جان سکوں، تاکہ میں تمہاری نظر میں فضل پا سکوں؛ اور یہ سمجھو کہ یہ قوم تمہاری قوم ہے۔\n14۔ اور اس نے کہا، میری موجودگی تمہارے ساتھ جائے گی، اور میں تمہیں آرام دوں گا۔\n15۔ اور اس نے اس سے کہا، اگر تمہاری موجودگی میرے ساتھ نہیں جاتی، تو ہمیں یہاں سے نہ لے جانا۔\n16۔ کیونکہ یہاں کہاں معلوم ہوگا کہ میں اور تمہارے لوگوں نے تیری نظر میں فضل پایا ہے؟ کیا یہ اس لیے نہیں کہ تم ہمارے ساتھ چلتے ہو؟ اسی طرح ہم، میں اور تمہاری قوم، ان تمام لوگوں سے جدا ہوں گے جو زمین پر موجود ہیں۔\n17۔ اور خداوند نے موسیٰ سے کہا، میں وہ بھی کروں گا جو تم نے کہا ہے: کیونکہ تم نے میری نظر میں فضل پایا ہے، اور میں تمہیں نام سے جانتا ہوں۔\n18۔ اور اس نے کہا، میں تم سے التجا کرتا ہوں، اپنا جلال مجھے دکھاؤ۔\n19۔ اور اس نے کہا، میں اپنی ساری نیکی تیرے سامنے لے آؤں گا، اور خداوند کا نام تمہارے سامنے اعلان کروں گا؛ اور جس پر میں مہربان رہوں گا، اور جس پر رحم کروں گا اس پر رحم کروں گا۔\n20۔ اور اس نے کہا، تم میرا چہرہ نہیں دیکھ سکتے، کیونکہ وہاں کوئی مجھے نہیں دیکھے گا اور زندہ رہے گا۔\n21۔ اور خداوند نے فرمایا، دیکھو، میرے پاس ایک جگہ ہے، اور تم ایک چٹان پر کھڑے ہو گے:\n22۔ اور جب میرا جلال گزرے گا، تو میں تمہیں چٹان کے ٹکڑے میں ڈال دوں گا، اور جب میں گزروں گا تو تمہیں اپنے ہاتھ سے ڈھانپ دوں گا:\n23۔ اور میں اپنا ہاتھ ہٹا دوں گا، اور تم میری پشت کے حصے دیکھو گے: لیکن میرا چہرہ نظر نہیں آئے گا۔","1۔ اور خداوند نے موسیٰ سے کہا، اپنے لیے دو پتھر کی تختیاں تراش، جیسے پہلی جدولوں کی طرح، اور میں {ان} میزوں پر وہ الفاظ لکھوں گا جو پہلی میزوں میں تھے، جنہیں تم نے توڑ دیا۔\n2۔ اور صبح تیار رہو، اور صبح سینا کے پہاڑ پر آؤ، اور وہاں پہاڑ کی چوٹی پر میرے سامنے آنا۔\n3۔ اور کوئی انسان تمہارے ساتھ اوپر نہیں آئے گا، نہ ہی پورے پہاڑ میں کوئی نظر آئے گا؛ نہ تو ریوڑ اور نہ ریوڑ کو اس پہاڑ سے پہلے خوراک دینے دیں۔\n4۔ اور اس نے پہلی کی طرح دو پتھر کی میزیں تراشیں؛ اور موسیٰ صبح سویرے اٹھا، اور سینا پر چڑھ گیا، جیسا کہ خداوند نے حکم دیا تھا، اور اپنے ہاتھ میں دو پتھر کی میزیں لے لیں۔\n5۔ اور خداوند بادلوں میں اترا، اس کے ساتھ کھڑا ہوا، اور خداوند کا نام اعلان کیا۔\n6۔ اور خداوند اس کے سامنے گزرا، اور اعلان کیا، اے خداوند، خداوند خدا، جو رحم کرنے والا اور مہربان ہے، صبر کرنے والا، اور بھلائی اور سچائی میں مالا مال ہے،\n7۔ ہزاروں لوگوں پر رحم کرنا، گناہوں اور گناہوں کو معاف کرنا، اور جو کسی بھی صورت مجرموں کو صاف نہیں کرے گا؛ باپ کی بدکاری بچوں پر، اور بچوں کے بچوں پر، تیسری اور چوتھی نسل تک پہنچنا۔\n8۔ اور موسیٰ نے جلدی کی، اپنا سر زمین کی طرف جھکایا اور عبادت کی۔\n9۔ اور اس نے کہا، اے خداوند، اگر اب میں نے تیری نظر میں فضل پا لیا ہے، تو میرے رب، میں دعا کرتا ہوں، ہمارے درمیان چلا جائے؛ کیونکہ یہ ایک ضدی قوم ہے؛ اور ہمارے گناہوں اور گناہوں کو معاف کرو، اور ہمیں اپنی وراثت کے لیے لے لو۔\n10۔ اور اس نے کہا، دیکھو، میں ایک عہد کرتا ہوں: تیری ساری قوم کے سامنے میں وہ حیرت کروں گا جو نہ تو پوری زمین میں ہو، نہ کسی قوم میں: اور جن لوگوں میں تم ہو وہ سب خدا کا کام دیکھے گا: کیونکہ یہ تمہارے ساتھ بہت برا کام ہے۔\n11۔ آج جو میں تمہیں حکم دیتا ہوں اس پر غور کرو: دیکھو، میں تمہارے سامنے اموری، کنعانی، حتی، پریزی، حوی اور یبوسی کو نکال رہا ہوں۔\n12۔ اپنے آپ سے ہوشیار رہو، کہیں تم اس زمین کے باشندوں سے وعدہ نہ کر لو جہاں تم جاتے ہو، کہیں وہ تمہارے درمیان پھنس نہ جائے:\n13۔ لیکن تم ان کے قربان گاہیں تباہ کرو گے، ان کی تصویریں توڑو گے، اور ان کے باغات کاٹو گے: {تصاویر: عبرانی۔ مجسمے}\n14۔ کیونکہ تم کسی اور خدا کی عبادت نہیں کرو گے: کیونکہ خداوند جس کا نام {حسد} ہے، {ہے} حسد کرنے والا خدا:\n15۔ کہیں تم اس سرزمین کے لوگوں سے عہد نہ کرو، اور وہ اپنے دیوتاؤں کے پیچھے بدکاری کریں، اپنے دیوتاؤں کے لیے قربانی دیں، اور {ایک} تمہیں بلائے اور تم اس کی قربانی میں سے کھا لو؛\n16۔ اور تم ان کی بیٹیوں میں سے اپنے بیٹوں میں شامل کر لیتے ہو، اور ان کی بیٹیاں اپنے دیوتاؤں کے پیچھے بدکاری کرتی ہیں، اور اپنے بیٹوں کو ان کے دیوتاؤں کے پیچھے طوائف بنا دیتی ہو۔\n17۔ تم اپنے لیے پگھلے ہوئے خدا نہیں بناؤ گے۔\n18۔ بغیر خمیر کے روٹی کی عید کو تم مناؤ گے۔ سات دن تم بغیر خمیر کی روٹی کھاؤ گے، جیسا کہ میں نے تمہیں حکم دیا تھا، مہینے ایب کے وقت میں، کیونکہ اس مہینے میں تم مصر سے نکلے ہو۔\n19۔ جو کچھ بھی میٹرکس کو کھولتا ہے وہ میرا ہے؛ اور تمہارے مویشیوں میں سے ہر پہلا اولاد، {چاہے} بیل ہو یا بھیڑ، {جو نر ہو}۔ {بھیڑ: یا، بچے}\n20۔ لیکن گدھے کے سب سے بڑے بچے کو تم ایک بکری سے نجات دو گے، اور اگر تم اسے نجات نہیں دو گے تو اس کی گردن توڑ دو گے۔ اپنے تمام پہلے بیٹوں کو تم نجات دو گے۔ اور کوئی بھی میرے سامنے خالی نہیں آئے گا۔ {لیمب: یا، بچے}\n21۔ چھ دن تم کام کرو گے، لیکن ساتویں دن آرام کرو گے: کان کے وقت اور فصل میں آرام کرو گے۔\n22۔ اور تم ہفتوں کی تہوار، گندم کی فصل کے پہلے پھل، اور سال کے آخر میں جمع کرنے کی عید مناؤ گے۔ {سال کا اختتام: عبرانی۔ سال کا انقلاب}\n23۔ سال میں تین بار تمہارے تمام مرد بچے خداوند خدا، اسرائیل کے خدا کے سامنے ظاہر ہوں گے۔\n24۔ کیونکہ میں تمہارے سامنے قوموں کو نکال دوں گا، اور تمہاری سرحدیں وسیع کروں گا: جب تم سال میں تین بار خداوند اپنے خدا کے سامنے آؤ گے تو کوئی تمہاری زمین کو نہیں چاہے گا۔\n25. تم میری قربانی کا خون خمیر کے ساتھ پیش نہ کرو؛ نہ ہی عید فسح کی قربانی صبح تک ملتوی کی جائے گی۔\n26۔ اپنی زمین کے پہلے پھلوں میں سے پہلا تو اپنے خدا خداوند کے گھر میں لے آؤ گے۔ تم بچے کو اس کی ماں کے دودھ میں نہ اگلاؤ۔\n27۔ اور خداوند نے موسیٰ سے کہا، یہ الفاظ لکھو، کیونکہ ان الفاظ کے بعد میں نے تم سے اور اسرائیل کے ساتھ عہد کیا ہے۔\n28۔ اور وہ خداوند کے ساتھ چالیس دن اور چالیس راتیں وہاں رہا؛ اس نے نہ روٹی کھائی، نہ پانی پیا۔ اور اس نے میزوں پر عہد کے الفاظ، دس احکامات لکھے۔ {احکامات: عبرانی۔ الفاظ}\n29۔ اور جب موسیٰ پہاڑ سینا سے دو میز گواہی موسیٰ کے ہاتھ میں لے کر اترا، جب وہ پہاڑ سے اترا، تو موسیٰ کو یہ احساس نہ ہوا کہ اس کے چہرے کی جلد اس سے بات کرتے ہوئے چمک رہی تھی۔\n30۔ اور جب ہارون اور تمام بنی اسرائیل نے موسیٰ کو دیکھا، تو اس کے چہرے کی جلد چمک اٹھی؛ اور وہ اس کے قریب آنے سے ڈرتے تھے۔\n31۔ اور موسیٰ نے انہیں پکارا؛ اور ہارون اور جماعت کے تمام حکمران اس کے پاس واپس آئے: اور موسیٰ نے ان سے بات کی۔\n32۔ اور اس کے بعد تمام بنی اسرائیل قریب آئے: اور اس نے انہیں حکم میں وہ سب کچھ دیا جو خداوند نے اس سے پہاڑ سینا میں بات کی تھی۔\n33۔ اور جب تک موسیٰ نے ان سے بات نہیں کی، اس نے اپنے چہرے پر پردہ لگا دیا۔\n34۔ لیکن جب موسیٰ خداوند کے سامنے اس سے بات کرنے گیا، تو اس نے پردہ ہٹا دیا، یہاں تک کہ وہ باہر آ گیا۔ اور وہ باہر آیا، اور بنی اسرائیل سے وہی کہا جو اسے حکم دیا گیا تھا۔\n35۔ اور بنی اسرائیل نے موسیٰ کا چہرہ دیکھا، کہ موسیٰ کے چہرے کی جلد چمک رہی تھی: اور موسیٰ نے دوبارہ پردہ اس کے چہرے پر رکھا، یہاں تک کہ وہ اس سے بات کرنے کے لیے اندر گیا۔","1۔ اور موسیٰ نے بنی اسرائیل کی تمام جماعت کو اکٹھا کیا اور ان سے کہا، یہ وہ الفاظ ہیں جو خداوند نے حکم دیا ہے کہ تم انہیں پورا کرو۔\n2۔ چھ دن کام کیا جائے گا، لیکن ساتویں دن آپ کے لیے مقدس دن ہوگا، خداوند کے لیے آرام کا ہفت: جو بھی اس میں کام کرے گا اسے قتل کر دیا جائے گا۔ {an...: عبرانی۔ مقدس مقام}\n3۔ آپ اپنے گھروں میں ہفتہ کے دن آگ نہیں جلا سکتے۔\n4۔ اور موسیٰ نے بنی اسرائیل کی تمام جماعت سے کہا، یہ وہ چیز ہے جس کا خداوند نے حکم دیا تھا، اور کہا،\n5. تم اپنے درمیان سے خداوند کے لیے نذرانہ لو: جو رضا مند دل کا ہے، وہ اسے خداوند کی قربانی دے دے؛ سونا، چاندی، پیتل،\n6۔ اور نیلا، اور جامنی، اور سرخ رنگ کی، اور باریک کپڑا، اور بکریوں کے {بال}،\n7۔ اور مینڈوں کی کھالیں جو سرخ رنگ کی تھیں، اور بیجر کی کھالیں اور شیٹم لکڑی،\n8۔ اور روشنی کے لیے تیل، مسح کے تیل کے لیے مصالحے، اور میٹھے لوبان کے لیے،\n9۔ اور اونکس کے پتھر، اور ایفود اور سینہ پوش کے لیے پتھر لگائے جائیں گے۔\n10۔ اور تم میں سے ہر دانا دل آئے گا، اور وہ سب کچھ کرے گا جو خداوند نے حکم دیا ہے؛\n11۔ خیمہ خانہ، اس کا خیم، اور اس کا پردہ، اس کے ٹیچز، اس کے تختے، اس کی سلاخیں، اس کے ستون، اور اس کے ساکٹ،\n12۔ صندوق، اور اس کی چھڑیاں، رحم کی نشست کے ساتھ، اور پردے کی چادر،\n13۔ دستر، اس کی لاٹھیاں، اور اس کے تمام برتن، اور روٹی،\n14۔ روشنی کے لیے موم بتی کا اسٹک، اور اس کے فرنیچر کے لیے، اور اس کے چراغ، روشنی کے لیے تیل کے ساتھ،\n15۔ اور لوبان کا قربان گاہ، اس کے ڈنڈیاں، مسح کرنے کا تیل، میٹھا لوبان اور خیمے کے دروازے کے لیے لٹکا،\n16۔ جلانے والی قربانی کا قربان گاہ، اس کے منہ کی جالی، اس کی لاٹھیاں، اور اس کے تمام برتن، لاور اور اس کے پاؤں،\n17۔ صحن کے لٹکاؤں، اس کے ستون، ان کے ساکٹ، اور دربار کے دروازے کے لیے لٹکا،\n18۔ خیمہ کے پن، صحن کے پن، اور ان کے رسے،\n19۔ خدمت کے کپڑے، مقدس جگہ پر خدمت کرنے کے لیے، کاهن ہارون کے لیے مقدس لباس، اور اس کے بیٹوں کے لباس، تاکہ وہ پادری کے دفتر میں خدمت کرے۔\n20۔ اور بنی اسرائیل کی تمام جماعت موسیٰ کی موجودگی سے چلی گئی۔\n21۔ اور وہ آئے، ہر وہ جس کا دل اسے جگاتا تھا، اور ہر وہ جسے اس کی روح نے راضی کیا، {اور} انہوں نے جماعت کے خیمہ کے کام کے لیے خداوند کی قربانی دی، اس کی تمام خدمت کے لیے، اور مقدس لباس کے لیے۔\n22۔ اور وہ آئے، مرد اور عورت، جتنے دل سے راضی تھے، {اور} کنگن، بالیاں، انگوٹھیاں، تختیاں اور سونے کے جواہرات لے کر آئے۔\n23۔ اور ہر آدمی جس کے ساتھ نیلا، جامنی، سرخ رنگ، عمدہ کتان، بکریوں کے بال، مینڈوں کی سرخ کھالیں اور بیجر کی کھالیں ملیں، وہ انہیں لے آیا۔\n24۔ ہر وہ شخص جو چاندی اور پیتل کی قربانی پیش کرتا تھا، خداوند کی قربانی لاتا تھا: اور ہر وہ شخص جس کے پاس خدمت کے کام کے لیے لکڑی ملتی تھی، وہ اسے لے آیا۔\n25۔ اور تمام دانا دل والی عورتیں اپنے ہاتھوں سے کاتیں، اور وہ چیز لے آئیں جو انہوں نے بنایا تھا، {دونوں} نیلا، اور جامنی، {اور} سرخ اور عمدہ کتان کا۔\n26۔ اور وہ تمام عورتیں جن کے دل نے انہیں حکمت سے جگایا، بکریوں کے بال بنتی رہیں۔\n27۔ اور حکمرانوں نے اونکس کے پتھر اور پتھر لائے جو ایفود اور سینہ کے لیے پتھر لگائے گئے؛\n28۔ اور مصالحہ، اور روشنی کے لیے تیل، اور مسح کے تیل کے لیے، اور میٹھے لوبان کے لیے۔\n29۔ بنی اسرائیل نے خداوند کے لیے ایک رضاکارانہ قربانی پیش کی، ہر مرد اور عورت، جس کے دل نے انہیں ہر قسم کے کام کے لیے تیار کیا، جو خداوند نے موسیٰ کے ہاتھ سے کرنے کا حکم دیا تھا۔\n30۔ اور موسیٰ نے بنی اسرائیل سے کہا، دیکھو، خداوند نے یہوداہ قبیلے کے یوری کے بیٹے بززلیل کو نام دیا ہے؛\n31۔ اور اس نے اسے خدا کی روح سے بھر دیا ہے، حکمت، فہم میں، علم میں، اور ہر قسم کی کاریگری میں؛\n32۔ اور عجیب و غریب کام تخلیق کرنا، سونے، چاندی، اور پیتل میں کام کرنا،\n33۔ اور پتھر کاٹنے میں، انہیں لگانے میں، اور لکڑی کی کندہ کاری میں، کسی بھی قسم کا چالاکی کرنے کے لیے۔\n34۔ اور اس نے اپنے دل میں رکھا ہے تاکہ وہ اور آہولیاب دونوں، جو احیساماک کا بیٹا ہے، دان قبیلے سے تعلیم دے سکے۔\n35۔ انہوں نے دل کی حکمت سے بھر دیے ہیں، ہر قسم کے کام کرنے کے لیے، کندہ کار، چالاک کاریگر، اور کشیدہ کاری کرنے والے کی، نیلے، جامنی، سرخ رنگ میں، اور عمدہ کپڑے میں، اور بننے والے بھی، حتیٰ کہ جو کوئی کام کرتے ہیں، اور جو چالاک کام کرتے ہیں۔","1۔ پھر بیزلیل اور اہولیاب اور ہر دانا دل والا آدمی پیدا ہوا، جس میں خداوند نے حکمت اور سمجھ بوجھ ڈالی تاکہ وہ مقدس مقام کی خدمت کے لیے ہر قسم کا کام کرے، جیسا کہ خداوند نے حکم دیا تھا۔\n2۔ اور موسیٰ نے بزلیل اور اہولیاب کو بلایا، اور ہر دانا دل والے آدمی کو، جس کے دل میں خداوند نے حکمت رکھی تھی، {حتیٰ کہ} ہر اس شخص کو جس کے دل نے اسے اس کام کے لیے آمادہ کیا:\n3۔ اور انہوں نے موسیٰ سے وہ تمام نذرانہ وصول کی، جو بنی اسرائیل نے مقدس مقام کی خدمت کے کام کے لیے لائی تھی، تاکہ اسے {with} بنایا جا سکے۔ اور وہ ہر صبح اس کے لیے مفت نذرانے لاتے تھے۔\n4۔ اور تمام دانا جنہوں نے مقدس مقام کا سارا کام کیا، ہر انسان اپنے کام سے نکلے؛\n5۔ اور انہوں نے موسیٰ سے کہا، \"لوگ اس کام کی خدمت کے لیے کافی مقدار لاتے ہیں، جسے خداوند نے حکم دیا تھا۔\n6۔ اور موسیٰ نے حکم دیا، اور اسے پورے کیمپ میں اعلان کروایا، کہا، نہ مرد اور نہ عورت مقدس مقام کی قربانی کے لیے مزید محنت نہ کریں۔ اس لیے لوگوں کو لانے سے روکا گیا۔\n7۔ کیونکہ ان کے پاس جو سامان تھا وہ سارا کام کرنے کے لیے کافی تھا، اور بہت زیادہ۔\n8۔ اور ان میں سے ہر دانا دل والا شخص جس نے خیمہ کا کام کیا، دس پردے نفیس الجھے ہوئے کتان، نیلے، جامنی اور سرخ رنگ کے بنائے۔\n9۔ ایک پردے کی لمبائی بیس آٹھ کیوبٹ تھی، اور ایک پردے کی چوڑائی چار کیوبٹ: پردے سب ایک ہی سائز کے تھے۔\n10۔ اور اس نے پانچ پردوں کو ایک دوسرے سے جوڑا: اور {باقی} پانچ پردے ایک دوسرے سے جوڑے۔\n11۔ اور اس نے ایک پردے کے کنارے پر نیلے رنگ کے حلقے بنائے جو جوڑنے کے سیلویج سے نکلے: اسی طرح اس نے {دوسری} پردے کے بالکل بالکل حصے میں، دوسرے پردے کے جوڑ میں بنایا۔ {سیلویج: کپڑے کا ایک کنارہ جو اتنا بنا ہوا ہے کہ وہ کھل نہیں سکتا}\n12۔ ایک پردے میں پچاس حلقے بنائے گئے، اور پچاس حلقے اس پردے کے کنارے میں بنائے جو دوسرے پردے کے جوڑ میں تھا: یہ حلقے ایک {پردے} کو دوسرے سے جوڑتے تھے۔\n13۔ اور اس نے سونے کے پچاس ٹاچ بنائے، اور پردوں کو ایک دوسرے کے ساتھ ٹیچز سے جوڑ دیا، یوں یہ ایک خیمہ بن گیا۔\n14۔ اور اس نے خیمے کے لیے بکریوں کے بالوں کے پردے بنائے: گیارہ پردے بنائے۔\n15۔ ایک پردے کی لمبائی تیس کیوبٹ تھی، اور چار کیوبٹ ایک پردے کی چوڑائی کے برابر تھی: گیارہ پردے ایک ہی سائز کے تھے۔\n16۔ اور اس نے پانچ پردے الگ سے جوڑے، اور چھ پردے اکیلے جوڑے۔\n17۔ اور اس نے پردے کے سب سے کنارے پر پچاس لوپ بنائے، اور پچاس لوپ اس پردے کے کنارے پر بنائے جو دوسرے کو جوڑتا ہے۔\n18۔ اور اس نے ٹینٹ کو جوڑنے کے لیے پچاس پیتل کے ٹچ بنائے۔\n19۔ اور اس نے خیمے کے لیے مینڈوں کی کھالوں کی سرخ رنگ کی تہہ بنائی، اور اس کے اوپر بیجر کی کھالوں کا ڈھانپنا بھی۔\n20۔ اور اس نے کھڑے ہو کر شٹم لکڑی کے تابوت کے لیے تختے بنائے۔\n21۔ تختے کی لمبائی دس کیوبٹ تھی، اور تختہ کی چوڑائی ڈیڑھ کیوبٹ تھی۔\n22۔ ایک تختے پر دو ٹینن تھے، جو ایک دوسرے سے برابر فاصلے پر تھے: یوں اس نے خیمہ کے تمام تختوں کے لیے بنایا تھا۔\n23۔ اور اس نے خیمہ گاہ کے لیے تختے بنائیں؛ جنوبی جانب جنوب کی طرف بیس بورڈز:\n24۔ اور اس نے بیس تختوں کے نیچے چالیس چاندی کے ساکٹ بنائے؛ ایک بورڈ کے نیچے دو ساکٹ اس کے دو ٹینن کے لیے، اور دو ساکٹس دوسرے بورڈ کے نیچے دو ساکٹس اس کے دو ٹینن کے لیے۔\n25۔ اور خیمے کے دوسری طرف، جو شمالی کونے کی طرف ہے، اس نے بیس تختے بنائے۔\n26۔ اور ان کے چالیس چاندی کے ساکٹ؛ ایک بورڈ کے نیچے دو ساکٹ، اور دوسرے بورڈ کے نیچے دو ساکٹ۔\n27۔ اور مغرب کی طرف خیمہ کے اطراف کے لیے اس نے چھ تختے بنائے۔\n28۔ اور دو تختیاں خیمہ کے دونوں اطراف کے کونوں کے لیے بنائی گئیں۔\n29۔ اور وہ نیچے اور اس کے سر پر ایک ہی انگوٹھی میں جڑے ہوئے تھے: اسی طرح اس نے دونوں کو دونوں کونوں میں جوڑا۔ {جوڑے ہوئے: عبرانی۔ جڑواں}\n30۔ اور آٹھ بورڈز تھے؛ اور ان کے ساکٹ سولہ چاندی کے ساکٹ تھے، ہر بورڈ کے نیچے دو ساکٹ۔ {نیچے...: عبرانی دو ساکٹس، ایک بورڈ کے نیچے دو ساکٹ}\n31۔ اور اس نے شٹم لکڑی کی سلاخیں بنائیں؛ ٹیبرنیکل کے ایک طرف کے تختوں کے لیے پانچ،\n32۔ اور خیمہ کے دوسری طرف کی تختیوں کے لیے پانچ باریں، اور مغرب کی طرف طرف کے اطراف کے لیے خیمہ کے تختوں کے لیے پانچ سلاخیں۔\n33۔ اور اس نے درمیانی بار کو ایک سرے سے دوسرے سرے تک بورڈز کے درمیان سے شاٹ مارا۔\n34۔ اور اس نے تختوں پر سونا ڈال دیا، اور ان کی انگوٹھیوں کو سونے کی طرح سلاخوں کے لیے جگہ بنایا، اور سلاخوں پر سونے سے ڈھانپ دیا۔\n35۔ اور اس نے نیلے، جامنی، سرخ اور باریک الجھے ہوئے کپڑوں کا پردہ بنایا: فرشتہوں نے اسے چالاکی سے بنایا۔\n36۔ اور اس نے اس پر چار ستون شتیم {لکڑی} کے بنائے، اور ان پر سونے کی طرح سجاوٹ کی: ان کے کانٹے سونے کے تھے؛ اور اس نے ان کے لیے چاندی کے چار ساکٹ ڈالے۔\n37۔ اور اس نے خیمہ گاہ کے دروازے کے لیے نیلا، جامنی، سرخ اور باریک لٹکا ہوا کپڑا سوئی کا لٹکایا؛ {سلائی کے کام کی: عبوری۔ ایک سلائی ساز یا کڑھائی کرنے والے کا کام}\n38۔ اور اس کے پانچ ستون ان کے کانٹے کے ساتھ: اور اس نے ان کے چپٹرز اور ان کے فلیٹ کو سونے سے ڈھانپ دیا، لیکن ان کے پانچ ساکٹ پیتل کے تھے۔","1۔ اور بزالیل نے شتیم کی لکڑی کا صندوق بنایا: اس کی لمبائی دو کیوبٹ اور آدھ، چوڑائی ڈیڑھ کیوبٹ اور اونچائی کے برابر ایک کیوبٹ اور آدھا:\n2۔ اور اس پر اندر اور باہر خالص سونے سے ڈھانپ دیا، اور اس کے گرد سونے کا تاج بنایا۔\n3۔ اور اس نے اس کے لیے چار سونے کی انگوٹھیاں ڈالیں، {جو چاروں کونوں سے سیٹ کی جائیں گی}؛ یہاں تک کہ اس کے ایک طرف دو حلقے، اور دوسری طرف دو حلقے۔\n4۔ اور اس نے شتیم کی لکڑی سے لاٹھیاں بنائیں، اور ان پر سونا لگا دیا۔\n5۔ اور اس نے لاٹھیاں صندوق کے کناروں پر انگوٹھیوں میں رکھ دیں، تاکہ وہ صندوق کو سنبھال سکیں۔\n6۔ اور اس نے رحمت کی نشست خالص سونے سے بنائی: دو ہاتھ اور آدھا اس کی لمبائی کے برابر اور اس کی چوڑائی کے برابر ایک کیوبٹ اور ڈیڑھ۔\n7۔ اور اس نے دو فرشتہ سونے سے بنائے، ایک ٹکڑے سے مارا گیا اور انہیں رحم کی نشست کے دونوں سروں پر بنایا؛ {پر...: یا، باہر، وغیرہ}\n8۔ ایک فرشتہ اس طرف اور دوسرے سرے پر دوسرا فرشتہ: رحم کی نشست سے اس نے اس کے دونوں سروں پر فرشتہ بنایا۔ {آخر میں: یا، باہر، وغیرہ} {دوسری طرف: یا، باہر، وغیرہ}\n9۔ اور فرشتہ اپنے پروں کو اونچا پھیلا دیتے ہیں، {اور} اپنے پروں سے رحم کی نشست پر ڈھانپتے ہیں، اور ان کے چہرے ایک دوسرے سے ملتے ہیں؛ {حتیٰ کہ} رحم کی نشستوں کے لیے کروبیمز کے چہرے بھی تھے۔\n10۔ اور اس نے میز شتیم لکڑی سے بنائی: اس کی لمبائی دو کیوبٹ، چوڑائی کے برابر ایک کیوبٹ، اور اونچائی ڈیڑھ کیوبٹ:\n11۔ اور اس کے اوپر خالص سونے کی تہہ کی، اور اس کے گرد سونے کا تاج بنایا۔\n12۔ اس نے اس کے گرد ایک ہاتھ کی چوڑائی کی سرحد بنائی؛ اور اس کے گرد کے کنارے کے لیے سونے کا تاج بنایا۔\n13۔ اور اس نے اس کے لیے چار سونے کی انگوٹھیاں ڈالیں، اور ان کے چار کونوں پر انگوٹھیاں رکھ دیں جو چار فٹ میں تھیں۔\n14۔ سرحد کے سامنے انگوٹھیاں تھیں، وہ جگہیں جہاں لاٹھیاں میز رکھتی تھیں۔\n15۔ اور اس نے شٹیم لکڑی کے لاٹھیوں کو بنایا اور ان پر سونا ڈال کر میز پر رکھ دیا۔\n16۔ اور اس نے وہ برتن جو میز پر رکھے تھے، اپنے برتن، چمچ، پیالے اور چادر جو انہیں ڈھانپنے کے لیے تھے، خالص سونے کے بنائے۔ {ڈھانپنے کے لیے...: یا، باہر نکالنے کے لیے}\n17۔ اور اس نے خالص سونے کی موم بتی بنائیں: {پھٹے ہوئے کام سے} نے شمعدان بنایا؛ اس کا ڈنٹھ، شاخ، پیالی، نوپ، اور پھول بھی ایک جیسے تھے:\n18۔ اور اس کے اطراف سے نکلنے والی چھ شاخیں؛ موم بتی کی ایک طرف سے تین شاخیں، اور دوسری طرف سے تین شاخیں:\n19۔ ایک شاخ میں بادام کے طرز پر تین پیالے بنے، ایک نوپ اور ایک پھول؛ اور ایک شاخ میں بادام کی طرح تین پیالے، ایک نوپ اور ایک پھول: یوں چھ شاخیں موم بتی سے باہر نکلتی ہیں۔\n20۔ اور موم بتی میں چار پیالے تھے جو بادام کی طرح بنے تھے، اس کے نوپس، اور اس کے پھول:\n21۔ اور ایک ہی شاخوں کے نیچے دو شاخوں کے نیچے ایک نوپ، اور ایک نوپ دو شاخوں کے نیچے، اور ایک نوپ دو شاخوں کے نیچے، جیسا کہ چھ شاخیں اس سے نکلتی ہیں۔\n22۔ ان کے نوپ اور شاخیں ایک جیسی تھیں: سب ایک خالص سونے کا ایک ہی پھینٹا ہوا کام تھا۔\n23۔ اور اس نے اپنے سات چراغ بنائیں، اپنے سنفرز اور اپنے سنف ڈشز خالص سونے سے بنائے۔\n24۔ {آف} خالص سونے کی صلاحیت نے اسے بنایا، اور اس کے تمام برتن بھی۔\n25۔ اور اس نے بخور کی قربان گاہ شتیم لکڑی سے بنائی: اس کی لمبائی ایک کیوبٹ اور چوڑائی ایک کیوبٹ تھی؛ {یہ تھا} فوراسکوائر؛ اور اس کی اونچائی سے دو کیوبٹ تھے؛ ان کے سینگ بھی ایک جیسے تھے۔\n26۔ اور اس کے اوپر خالص سونے کی تہہ کی، اس کے اوپر دونوں، اس کے اطراف اور اس کے سینگ، اور اس کے گرد سونے کا تاج بھی بنایا۔\n27۔ اور اس نے اس کے تاج کے نیچے دو سونے کی انگوٹھیاں بنائیں، اس کے دو کونوں پر، اس کے دونوں اطراف میں، تاکہ لکڑیاں اسے رکھنے کے لیے رکھی جا سکیں۔\n28۔ اور اس نے شتیم لکڑی کے ڈنڈے بنائے، اور ان پر سونا چڑھایا۔\n29۔ اور اس نے مقدس مسح کا تیل اور میٹھے مصالحوں کا خالص لوبان تیار کیا، جو دوا ساز کے کام کے مطابق تھا۔","1۔ اور اس نے شتیم کی لکڑی کی سلائی کی قربان گاہ بنائی: اس کی لمبائی پانچ ہاتھ اور چوڑائی پانچ ہاتھ تھی؛ {یہ تھا} فوراسکوائر؛ اور اس کی اونچائی سے تین کیوبٹ۔\n2۔ اور اس نے اس کے چاروں کونوں پر اس کے سینگ بنائے؛ اس کے سینگ بھی اسی طرح کے تھے: اور اس نے اس پر پیتل سے ڈھانپ دیا۔\n3۔ اور اس نے قربان گاہ کے تمام برتن، برتن، بیلچے، حوض اور گوشت کے کانٹے اور آگ کے برتن بنائے: ان کے تمام برتن پیتل کے بنائے۔\n4۔ اور اس نے قربان گاہ کے لیے اس کے کمپاس کے نیچے ایک جال کی جالی بنائی، جو اس کے بیچ تک تھی۔\n5۔ اور اس نے پیتل کی جالی کے چاروں سروں کے لیے چار انگوٹھیاں پھینکیں، جو لکڑیوں کے لیے جگہیں ہوں گی۔\n6۔ اور اس نے شیتم لکڑی کی لاٹھیاں بنائیں، اور ان پر پیتل لگا دیا۔\n7۔ اور اس نے لاٹھیاں قربان گاہ کے کناروں پر انگوٹھیوں میں رکھ دیں، تاکہ اسے اٹھا سکیں؛ اس نے قربان گاہ کو تختوں سے کھوکھلا بنایا۔\n8۔ اور اس نے پیتل کا لیور بنایا، اور اس کے پاؤں کو پیتل کا، عورتوں کے اجتماع کے چشموں کا، جو جماعت کے خیمہ کے دروازے پر جمع ہوتے تھے۔ {دیکھنے کے چشمے: یا، بریسن چشمہ} {جمع کر رہے ہیں: عبوری۔ فوجیوں کے ذریعے جمع ہونا}\n9۔ اور اس نے صحن بنایا: جنوب کی طرف صحن کی لٹکیاں عمدہ جڑی ہوئی چادروں کی تھیں، سو کیوبٹ:\n10۔ ان کے ستون بیس تھے، اور ان کے براسن ساکٹس بیس؛ ستونوں کے ہکس اور ان کے فلیٹس چاندی کے تھے۔\n11۔ اور شمالی طرف کے لیے {لٹکیاں } سو کیوبٹ تھیں، ان کے ستون {بیس} تھے، اور ان کے ساکٹ پیتل کے بیس تھے؛ ستونوں کے کانٹے اور ان کے چمکدار چاندی کے۔\n12۔ اور مغربی طرف کے لیے پچاس کیوبٹ کے لٹکے، ان کے ستون دس اور ان کے ساکٹ دس تھے؛ ستونوں کے کانٹے اور ان کے چمکدار چاندی کے۔\n13۔ اور مشرق کی طرف مشرق کی طرف پچاس کیوبٹ۔\n14۔ دروازے کے ایک طرف کی لٹکی پندرہ کیوبٹ تھی؛ ان کے ستون تین، اور ان کے ساکٹ تین۔\n15۔ اور عدالت کے دروازے کے دوسری طرف، اس ہاتھ اور اس ہاتھ پر، پندرہ کیوبٹ کے پھانسی تھے؛ ان کے ستون تین، اور ان کے ساکٹ تین۔\n16۔ دربار کے ارد گرد کے تمام لٹکیاں عمدہ جڑی ہوئی کپڑوں کی تھیں۔\n17۔ اور ستونوں کے ساکٹ پیتل کے تھے؛ ستونوں کے کانٹے اور ان کے چمکدار چاندی کی؛ اور ان کے چپٹرز کی اوورلینگ چاندی کی؛ اور دربار کے تمام ستون چاندی سے بھرے گئے۔\n18۔ اور دربار کے دروازے کے لیے لٹکایا ہوا سلائی کا کام تھا، نیلا، جامنی، سرخ اور باریک الجھا ہوا کتان: اور بیس کیوبٹ لمبائی اور چوڑائی کی اونچائی پانچ کیوبٹ تھی، جو دربار کے پھانسی کے مطابق تھی۔\n19۔ اور ان کے ستون چار تھے، اور ان کے ساکٹ چار پیتل کے؛ ان کے کانٹے چاندی کے تھے، اور ان کے چپٹرز اور ان کے فلیٹس چاندی کے اوپر تھے۔\n20۔ اور خیمہ گاہ اور آس پاس کے صحن کے تمام پن پیتل کے تھے۔\n21. یہ خیمہ گاہ کا مجموعہ ہے، {حتی} گواہی کے خیمے کا، جیسا کہ موسیٰ کے حکم کے مطابق لاویوں کی خدمت کے لیے شمار کیا گیا، جو ہارون کاهن کا بیٹا ایتھامار کے ہاتھوں تھا۔\n22۔ اور یوری کا بیٹا، جو یہوداہ قبیلے سے ہور کا بیٹا تھا، نے وہ سب کچھ بنایا جو خداوند نے موسیٰ کو حکم دیا تھا۔\n23۔ اور اس کے ساتھ اہولیاب تھا، احساماخ کا بیٹا، دان قبیلے سے تھا، ایک کندہ کاریگر، چالاک کاریگر، اور نیلے، جامنی، سرخ اور عمدہ کپڑے میں کڑھائی کرنے والا۔\n24۔ مقدس جگہ کے تمام کاموں میں کام کے لیے جو سونا استعمال ہوا، حتیٰ کہ نذرانہ کا سونا بھی، مقدس مقام کے شیکل کے مطابق بیس نو ٹیلنٹ اور سات سو تیس شیکل تھا۔\n25۔ اور جماعت کے افراد کی چاندی سو ٹیلنٹ اور ہزار سات سو تیس پندرہ شیکل تھی، مقدس مقام کے شیکل کے مطابق:\n26۔ ہر آدمی کے لیے ایک بیکا، {یعنی}، آدھا شیکل، مقدس مقام کے شیکل کے بعد، ہر اس شخص کے لیے جو بیس سال کی عمر سے اوپر کی عمر میں چھ لاکھ تین ہزار پانچ سو پچاس آدمی شمار کیا جائے۔ {ہر مرد: عبوری۔ ایک پول}\n27۔ اور سو چاندی کے ٹالنٹ میں سے مقدس مقام کے ساکٹ اور پردے کے ساکٹ ڈھالے گئے؛ سو ساکٹ آف دی سو ٹیلنٹس، ایک ساکٹ کے لیے ایک ٹیلنٹ۔\n28۔ اور ہزار سات سو ستر پانچ شیکل میں سے اس نے ستونوں کے لیے کانٹے بنائے، ان کے چپٹرز کو اوپر سے ڈھانپ کر فلیٹ کیا۔\n29۔ اور نذرانہ کا پیتل ستر ٹیلنٹ اور دو ہزار چار سو شیکل تھا۔\n30۔ اور اس کے ساتھ اس نے جماعت کے خیمے کے دروازے کے ساکٹ، براسن قربان گاہ، اس کے لیے برازن جالی اور قربان گاہ کے تمام برتن بنائے۔\n31۔ اور صحن کے گرد کے ساکٹ، اور صحن کے دروازے کے ساکٹ، خیمہ کے تمام پن، اور صحن کے تمام پن گرد۔","1۔ اور نیلے، جامنی اور سرخ رنگ کے کپڑے بنائے تاکہ مقدس جگہ پر خدمت کی جا سکے، اور ہارون کے لیے مقدس لباس بنائیں؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n2۔ اور اس نے ایفود سونا، نیلا، جامنی، سرخ اور باریک لپٹا ہوا کتان بنایا۔\n3۔ اور انہوں نے سونے کو پتلی پلیٹوں میں پھینکا، اور اسے تاروں میں کاٹ دیا، تاکہ نیلا، جامنی، سرخ اور باریک کپڑا میں کام کیا جا سکے، {چالاکی سے} کام کے ساتھ۔\n4۔ انہوں نے اس کے لیے شولڈر پیسز بنائے، تاکہ {اسے} کو جوڑا جا سکے: دونوں کناروں سے یہ آپس میں جڑا ہوا تھا۔\n5۔ اور اس کے ایفود کی عجیب بیلٹ، جو {تھا} اس پر تھی، {تھی} اسی کا تھا، اس کے کام کے مطابق؛ سنہری، نیلا، جامنی، سرخ رنگ، اور باریک بنے ہوئے کتان؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n6۔ اور انہوں نے سونے کے اوچز میں لپٹے ہوئے اونکس پتھر بنائے، جیسے نشان تراشے جاتے ہیں، اور بنی اسرائیل کے نام کندہ کیے گئے۔\n7۔ اور اس نے انہیں ایفود کے کندھوں پر رکھا، {تاکہ وہ بنی اسرائیل کی یاد میں پتھر بن جائیں}؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n8۔ اور اس نے بریسٹ پلیٹ کو چالاکی سے کام کیا، جیسے ایفود کا کام؛ سنہری، نیلا اور جامنی، اور سرخ رنگ، اور باریک جڑی ہوئی کتان۔\n9۔ یہ چار چوکور تھا؛ انہوں نے بریسٹ پلیٹ کو دوہرا بنایا: ایک اسپین {تھا} کی لمبائی کے برابر اور ایک اسپین اس کی چوڑائی، {جو دوگنا تھا}۔\n10۔ اور انہوں نے اس میں چار قطاریں پتھروں کی لیں: {پہلی} قطار {تھی} ایک سارڈیئس، ایک ٹوپاز، اور ایک کاربنکل: یہ {تھی} پہلی قطار۔ {سارڈیئس: یا، روبی}\n11۔ اور دوسری قطار، ایک زمرد، ایک نیلم، اور ایک ہیرا۔\n12۔ اور تیسری قطار، ایک لیگور، ایک عقیق، اور ایک امیتھسٹ۔\n13۔ اور چوتھی قطار، ایک بیریل، ایک اونکس، اور ایک جیسپر: {وہ} اپنے انکلوسنگ میں سونے کے اوچز میں بند تھے۔\n14۔ اور پتھر {تھے} بنی اسرائیل کے ناموں کے مطابق، بارہ، ان کے ناموں کے مطابق، {جیسے} ایک نشان کی کندہ کاری، ہر ایک کے نام کے ساتھ، بارہ قبائل کے مطابق۔\n15۔ اور انہوں نے سینے کی تختی کے سروں پر خالص سونے کی ہاروں کی زنجیریں بنائیں۔\n16۔ اور انہوں نے دو اوچز سونے اور دو سونے کی انگوٹھیاں بنائیں؛ اور دونوں انگوٹھیاں بریسٹ پلیٹ کے دونوں سروں میں رکھیں۔\n17۔ اور انہوں نے دو سونے کی زنجیریں سینے کے سروں پر دو انگوٹھیوں میں لگا دیں۔\n18۔ اور دونوں ہاروں کی زنجیروں کے دونوں سرے دو اوچز میں باندھ دیے گئے، اور انہیں ایفود کے کندھوں پر لگا دیا، اس کے سامنے۔\n19۔ اور انہوں نے دو سونے کی انگوٹھیاں بنائیں، اور {ان} کو سینے کی تختی کے دونوں سروں پر، اس کے کنارے پر، جو {تھا} ایفود کے اندر کی طرف تھا۔\n20۔ اور انہوں نے دو {دیگر} سونے کی انگوٹھیاں بنائیں، اور انہیں ایفود کے دونوں اطراف کے نیچے، اس کے سامنے کی طرف، اس کے {دیگر} جوڑنے کے ساتھ، ایفود کے عجیب بیلٹ کے اوپر رکھ دیا۔\n21۔ اور انہوں نے سینے کی تختی کو اس کی انگوٹھیوں سے ایفود کی انگوٹھیوں سے نیلے لیس سے باندھ دیا، تاکہ وہ ایفود کے عجیب بیلٹ کے اوپر ہو، اور سینہ پوش ایفود سے آزاد نہ ہو؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n22۔ اور اس نے ایفود کی چادر کو مکمل نیلا بنایا۔\n23۔ اور {چادر کے بیچ میں} ایک سوراخ تھا، جو ایک ہبرجن کے سوراخ کی طرح تھا، {اور گڑھے کے گرد ایک پٹی تھی} کہ وہ پھٹ نہ جائے۔\n24۔ اور انہوں نے لباس کے کناروں پر نیلے، جامنی، اور سرخ انار {اور} لڑھے ہوئے {لینن} بنائے۔\n25۔ اور انہوں نے خالص سونے کی گھنٹیاں بنائیں، اور اناروں کے درمیان گھنٹیاں چادر کے کنارے رکھیں، اناروں کے درمیان گھنٹیاں رکھیں؛\n26۔ ایک گھنٹی اور ایک انار، ایک گھنٹی اور ایک انار، چادر کے کنارے کے گرد خدمت کے لیے؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n27. اور انہوں نے ہارون اور اس کے بیٹوں کے لیے باریک کتان کے کوٹ بنائے۔\n28۔ اور عمدہ لینن کا ایک میتر، اور عمدہ لینن کے خوبصورت ٹوپی، اور لینن کے پتلون جو باریک الجھے ہوئے لینن کے ہیں،\n29۔ اور ایک بیلٹ جو باریک جڑی ہوئی لینن کا ہے، نیلا، اور جامنی، اور سرخ رنگ کا، سلائی کا کام؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n30۔ اور انہوں نے مقدس تاج کی پلیٹ خالص سونے کی بنائی اور اس پر ایک تحریر لکھی، {جیسے کہ ایک نشان کی کندہ کاری، خداوند کی پاکیزگی۔\n31۔ اور انہوں نے اس پر نیلے رنگ کی فیتہ باندھی، تاکہ اسے اوپر مائٹر پر باندھا جا سکے؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n32۔ یوں جماعت کے خیمے کے خیمے کے خیمے کا سارا کام مکمل ہوا: اور بنی اسرائیل نے وہ سب کچھ کیا جو خداوند نے موسیٰ کو حکم دیا تھا، انہوں نے بھی ایسا ہی کیا۔\n33۔ اور انہوں نے موسیٰ کو خیمہ دیا، خیمہ اور اس کا سارا فرنیچر، اس کے تاش، اس کے تختے، اس کی سلاخیں، اس کے ستون، اور اس کے ساکٹ،\n34۔ اور سرخ رنگ کے مینڈوں کی کھالوں کا ڈھانپنا، اور بیجرز کی کھالوں کا ڈھانپنا، اور پردے کی پردہ،\n35۔ گواہی کا صندوق، اس کے ڈنڈے اور رحم کی نشست،\n36۔ دسترگی، {اور} اس کے تمام برتن، اور شیو بریڈ،\n37۔ خالص موم بتی کی چھٹی، اس کے چراغوں کے ساتھ، چراغوں کے ساتھ جو ترتیب سے لگائے جائیں، اور ان کے تمام برتن، اور روشنی کے لیے تیل،\n38۔ اور سونے کی قربان گاہ، اور مسح کا تیل، اور میٹھا لوبان اور خیمہ گاہ کے دروازے کے لیے لٹکا، {میٹھا...: عبرانی۔ میٹھے مصالحوں کی خوشبو}\n39۔ براسن قربان گاہ، اس کا پیتل کا جالی، اس کے عصا، اور اس کے تمام برتن، لیور اور اس کا پاؤں،\n40۔ صحن کے لٹکا، اس کے ستون، اس کے ساکٹ، اور صحن کے دروازے کے لیے لٹکاؤ، اس کے رسے، اس کے پن، اور عبادت گاہ کی خدمت کے تمام برتن، جماعت کے خیمے کے لیے،\n41۔ مقدس جگہ پر خدمت کے لیے کپڑے اور مقدس لباس جو ہارون کاہن اور اس کے بیٹوں کے لباس کے لیے پادری کے دفتر میں خدمت کرتے ہیں۔\n42. خداوند نے موسیٰ کو جو کچھ حکم دیا تھا، اسی طرح بنی اسرائیل نے سارا کام کیا۔\n43۔ اور موسیٰ نے تمام کام دیکھا، اور دیکھتے ہی انہوں نے وہ کام کیا جیسا خداوند نے حکم دیا تھا، اور انہوں نے بھی ایسا ہی کیا: اور موسیٰ نے انہیں برکت دی۔","1۔ اور خداوند نے موسیٰ سے کہا،\n2۔ پہلے مہینے کے پہلے دن تم جماعت کے خیمے کا خیمہ قائم کرو گے۔\n3۔ اور اس میں گواہی کا صندوق رکھو، اور صندوق کو پردے سے ڈھانپ دو۔\n4۔ اور تم میز لاؤ گے، اور جو چیزیں ترتیب دینی ہیں انہیں ترتیب میں رکھو گے؛ اور تم موم بتی لاؤ گے، اور اس کے چراغ جلاؤ گے۔ {چیزیں...: عبرانی اس کی ترتیب}\n5۔ اور تم سونے کی قربان گاہ کو اگربتی کے لیے تابوت کے سامنے رکھو، اور خیمے کے دروازے کو لٹکا دو۔\n6۔ اور تم جماعت کے خیمے کے خیمے کے دروازے کے سامنے جلنے والی قربانی کا مذبح رکھو گے۔\n7۔ اور تم جماعت کے خیمے اور قربان گاہ کے درمیان لیور رکھو گے، اور اس میں پانی ڈالو گے۔\n8۔ اور تم عدالت کو ارد گرد لگاؤ گے، اور پھانسی کو دربار کے دروازے پر لٹکا دو۔\n9۔ اور تم مسح کرنے کا تیل لے کر آؤ گے، اور خیمہ اور اس میں موجود سب کچھ مسح کرو گے، اور اسے اور اس کے تمام برتن مقدس کرو گے: اور یہ مقدس ہوگا۔\n10۔ اور تم جلنے والی قربانی کے محراب اور اس کے تمام برتنوں کو مسح کرو گے، اور قربان گاہ کو پاک کرو گے: اور یہ سب سے مقدس قربان گاہ ہوگی۔ {سب سے مقدس: عبرانی۔ تقدس کی مقدسیت}\n11۔ اور تم لیور اور اس کے پاؤں کو مسح کرو گے اور اسے پاک کرو گے۔\n12۔ اور تم ہارون اور اس کے بیٹوں کو جماعت کے خیمہ کے دروازے پر لے جا کر پانی سے دھو دینا۔\n13۔ اور تم ہارون پر مقدس لباس پہنا دو، اسے مسح کرو اور پاک کرو؛ تاکہ وہ پادری کے دفتر میں میری خدمت کرے۔\n14۔ اور تم اس کے بیٹوں کو لاؤ گے، اور انہیں کپڑے پہناؤ گے:\n15۔ اور تم انہیں اسی طرح مسح کرو گے جیسے تم نے ان کے باپ کو مسح کیا، تاکہ وہ میرے لیے پادری کے عہدے پر خدمت کریں: کیونکہ ان کی مسح بندی یقینا ان کی نسلوں میں ہمیشہ کے لیے پادری رہے گی۔\n16۔ موسیٰ نے بھی ایسا ہی کیا: خداوند نے جو کچھ حکم دیا، اس کے مطابق اس نے بھی کیا۔\n17۔ اور یہ دوسرے سال کے پہلے مہینے میں ہوا، مہینے کے پہلے {دن} کو، {کہ} خیمہ قائم کیا گیا۔\n18۔ اور موسیٰ نے خیمہ گاہ کو اٹھایا، اپنے ساکٹ باندھے، اس کے تختیاں لگائیں، اس کی سلاخیں لگا دیں اور اپنے ستون کھڑے کیے۔\n19۔ اور اس نے خیمے کو خیمہ کے اوپر پھیلا دیا، اور خیمے کی چادر اس پر رکھ دی؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n20۔ اور اس نے گواہی کو صندوق میں رکھا، لاٹھیاں صندوق پر رکھیں، اور رحم کی نشست کو اوپر صندوق پر رکھا:\n21۔ اور اس نے تابوت کو خیمہ میں لایا، اور پردے کا پردہ لگایا، اور گواہی کے صندوق کو ڈھانپ دیا؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n22۔ اور اس نے جماعت کے خیمے میں میز رکھی، خیمہ کے شمال کی طرف، بغیر پردے کے۔\n23۔ اور اس نے روٹی کو خداوند کے سامنے ترتیب دیا؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا تھا۔\n24۔ اور اس نے شمعدان کو جماعت کے خیمے میں، میز کے ساتھ، خیمہ کے جنوب کی طرف رکھ دیا۔\n25۔ اور اس نے خداوند کے سامنے چراغ روشن کیے؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n26۔ اور اس نے جماعت کے خیمے میں سنہری قربان گاہ کو پردے کے سامنے رکھا:\n27۔ اور اس پر میٹھا لوبان جلایا؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n28۔ اور انہوں نے خیمہ گاہ کے دروازے پر لٹکانے کا انتظام کیا۔\n29۔ اور اس نے اجتماع کے خیمے کے خیمے کے دروازے کے پاس جلنے والی قربانی کی قربان گاہ رکھی، اور اس پر سلائی ہوئی قربانی اور گوشت کی قربانی پیش کی؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n30۔ اور اس نے لیور کو جماعت کے خیمے اور قربان گاہ کے درمیان رکھا، اور وہاں پانی ڈال کر دھویا۔\n31۔ اور موسیٰ، ہارون اور اس کے بیٹوں نے وہاں اپنے ہاتھ اور پاؤں دھوئے:\n32۔ جب وہ جماعت کے خیمے میں گئے، اور جب وہ قربان گاہ کے قریب پہنچے، تو انہوں نے نہایا؛ جیسا کہ خداوند نے موسیٰ کو حکم دیا۔\n33۔ اور اس نے صحن کو خیمہ اور قربان گاہ کے ارد گرد کھڑا کیا، اور دربار کے دروازے کو لٹکانے کا انتظام کیا۔ تو موسیٰ نے کام مکمل کیا۔\n34۔ پھر ایک بادل نے جماعت کے خیمے کو ڈھانپ لیا، اور خداوند کی شان نے خیمے کو بھر دیا۔\n35۔ اور موسیٰ جماعت کے خیمے میں داخل نہیں ہو سکا، کیونکہ وہاں بادل تھا، اور خداوند کی شان نے خیمہ کو بھر دیا تھا۔\n36۔ اور جب بادل خیمہ کے اوپر سے اٹھایا گیا، تو بنی اسرائیل اپنی تمام سفروں میں آگے بڑھے: {آگے بڑھے: عبرانی۔ سفر کیا}\n37۔ لیکن اگر بادل نہ اٹھایا گیا تو وہ اس دن تک سفر نہیں کرتے جب تک وہ اٹھا نہ جائے۔\n38۔ کیونکہ خداوند کا بادل دن میں خیمہ گاہ پر تھا، اور رات کو اس پر آگ تھی، تمام اسرائیلی خاندان کی نظر میں، ان کے تمام سفر کے دوران۔"];
